-- Susan (bd730c91, 2026-10-21): "why are you not using umlauts here?
-- change any ae to ä etc." -- found this is a real, project-wide data bug,
-- not just the one row she screenshotted: 49 rows across EvoMentor
-- Thuringia have ASCII-transliterated German (ae/oe/ue instead of ä/ö/ü) in
-- one or more text fields, most commonly the kognitionsverb tag
-- ("erlaeutern", "begruenden") but several rows have it in user-visible text
-- too. Fixed with an exact word dictionary (never a blind ae->ä substitution,
-- which would corrupt unrelated words) -- see
-- lab_manager/scripts (gen_migration_153_umlauts.mjs pattern, run from the
-- openlpm worktree) for the dictionary and how this list was generated.

UPDATE lpm_data_objects SET content = '{"thema":"2.2.1 Naturwissenschaftliche Denk- und Arbeitsmethoden","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung","originaltext":"naturwissenschaftliche Informationen (Texte, Zeichnungen, Tabellen, Diagramme, Schemata, Protokolle) erfassen, auswerten, in geeigneter Form darstellen, einfache Protokolle anfertigen und in andere Darstellungsformen übertragen (z. B. Text in Schema)","curriculum_version":"2026-erprobungsfassung"}'::jsonb, description = 'naturwissenschaftliche Informationen (Texte, Zeichnungen, Tabellen, Diagramme, Schemata, Protokolle) erfassen, auswerten, in geeigneter Form darstellen, einfache Protokolle anfertigen und in andere Darstellungsformen übertragen (z. B. Text in Schema)' WHERE id = '5dcd1531-8572-4b55-bc81-5f905efd37de'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ATM-5","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-ATM-5","unterthema":"Atmungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung begründen: ausreichende Lüftung von Räumen","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"begründen","kurzbezeichnung":"Gesunderhaltung: Lüftung","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das menschliche Nervensystem ist evolutionär auf CO₂-Konzentration als primären Atemantrieb kalibriert – nicht auf O₂-Mangel. Dies erklärt, warum erhöhte CO₂-Konzentrationen in schlecht belüfteten Räumen zu Konzentrationsmangel, Kopfschmerzen und Müdigkeit führen. Die Empfindlichkeit gegenüber CO₂ ist evolutionär entstanden, weil CO₂-Anstieg im Blut ein verlässlicher Marker für Sauerstoffverbrauch und Ventilationsbedarf ist.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck","Evolutionäres Mismatch"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"}]},{"begruendung":"Raumlüftung betrifft die Umweltbedingungen, nicht die individuelle Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen sind für die Begründung ausreichender Lüftung nicht relevant.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse werden hier nur am Rande über die CO2-Empfindlichkeit des Atemzentrums berührt, stehen aber nicht im Fokus.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die CO2-Konzentration in der Raumluft ist eine unmittelbare Stoffgröße, die die Begründung für ausreichende Lüftung liefert: Mit zunehmender Verweildauer von Menschen in einem geschlossenen Raum steigt der Kohlenstoffdioxidgehalt der Luft an, was die Konzentrationsfähigkeit beeinträchtigen kann. Maßnahmen zur Gesunderhaltung wie regelmäßiges Lüften zu begründen stützt sich unmittelbar auf diese messbare stoffliche Veränderung der Raumluft.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Begründung von Raumlüftung nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Gedankenexperiment: ''Warum hält der Körper an der CO₂-Konzentration fest als Atemantrieb – nicht am O₂-Gehalt?'' Überraschendes biologisches Faktum diskutieren."},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Messung: CO₂-Konzentration in der Klasse vor und nach dem Lüften messen (CO₂-Messgerät) – direkter Beweis der Notwendigkeit."},{"rang":3,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"''Wie hat COVID-19 unser Verständnis von Raumlüftung verändert? Welche biologischen Prinzipien stecken dahinter?''"}],"bezug_zum_lehrplan_kontext":"Anwendungsorientiertes Integrationslernziel; Verbindung zu HUM-ATM-4 (Zellatmung und CO₂)","moegliche_fehlvorstellungen":"Schüler könnten denken, Atemnot entsteht durch O₂-Mangel; die primäre Rolle des CO₂ als Atemantrieb muss erklärt werden.","evolutionsdidaktischer_impuls":"Impuls: ''Unser Körper misst CO₂ statt O₂ als Atemantrieb – wäre es nicht sinnvoller, O₂ zu messen? Warum hat die Evolution CO₂ als Signal gewählt?'' Evolutionäre Erklärung einer überraschenden physiologischen Tatsache."},"_2026_erprobungsfassung":{"note":"2026 reframes this as one example-based statement (''Maßnahmen zur Gesunderhaltung begründen (z. B. regelmäßige sportliche Betätigung)'') instead of separately naming Sport, Ernährung, and Lüftung as three required bullets. Not consolidated or deleted here -- whether to keep these as distinct items or fold them into one is a curriculum judgment call, not a mechanical one.","source":"LP Thueringen Bio Gym 2026 Erprobungsfassung (Erprobungsfassung, in Kraft seit 2026-08-01, noch nicht endgueltig verabschiedet)","updatedAt":"2026-09-12","textChanged":false},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-ATM-4"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '5d2bc0e2-339a-529f-8ab1-e02f04fd8db4'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-BHK-5","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-BHK-5","unterthema":"Blut und Herz-Kreislauf-System","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung begründen: regelmäßige sportliche Betätigung","bk_prinzipien":["Homöostase"],"ist_praktisch":false,"kognitionsverb":"begründen","kurzbezeichnung":"Gesunderhaltung: Sport","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Regelmäßige körperliche Betätigung ist evolutionär der Normalzustand des Menschen: In der evolutionären Umwelt des Homo sapiens war körperliche Aktivität ein täglicher Bestandteil des Lebens. Die Persistenzjagd-Hypothese erklärt die außergewöhnliche Ausdauerleistungsfähigkeit des Menschen. Die physiologischen Adaptationen an Training sind evolutionäre Plastizitäten, die nicht nur das Herz-Kreislauf-System betreffen (Herzvolumenzunahme, Kapillarisierung), sondern auch das Nervensystem (verbesserte Kognition, Stressresistenz), das Hormonsystem (Regulation von Cortisol, Endorphinen) und die psychische Gesundheit positiv beeinflussen. Bewegungsmangel als modernes Phänomen ist ein evolutionäres Mismatch mit nachweisbaren negativen Folgen für mehrere Organsysteme.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Evolutionäres Mismatch","Anpassung und Angepasstheit","Phänotypische Plastizität","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Phänotypische Plastizität","taxonomyElementId":"f24a74bb-ac84-4f12-8645-694213b6239b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Sportliche Betätigung als Gesundheitsmaßnahme betrifft nicht primär die individuelle biologische Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Organe sind für diese Gesundheitsempfehlung nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelmäßiges Training verbessert die Regelfähigkeit des Herz-Kreislauf-Systems, indem es dessen Kapazität erhöht, unter körperlicher Belastung schnell und effizient auf einen veränderten Sauerstoffbedarf zu reagieren. Ein trainiertes Herz-Kreislauf-System erreicht eine gegebene Belastung mit geringerem Frequenzanstieg und kehrt nach Belastungsende schneller zum Ruhewert zurück – ein messbarer Ausdruck effizienterer Homöostase unter Belastung, der die Begründung sportlicher Betätigung stützt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Negative Rückkopplung (inkl. Homöostase-Prinzip)"],"relevante_unterkonzepte_taxonomie":[{"value":"Negative Rückkopplung (inkl. Homöostase-Prinzip)","taxonomyElementId":"b1a84980-ecba-4199-8157-4be6c4fada55"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Sportliche Betätigung erhöht den Energieumsatz und verbessert langfristig die Effizienz der Energiebereitstellung im Körper: Regelmäßiges Training steigert nicht nur den kurzfristigen Kalorienverbrauch, sondern verbessert auch die Fähigkeit des Körpers, Sauerstoff und Nährstoffe effizient in nutzbare Energie umzuwandeln. Maßnahmen zur Gesunderhaltung wie regelmäßige sportliche Betätigung zu begründen stützt sich auf diesen energetischen Zusammenhang.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__energie"],"relevante_unterkonzepte":["Energieumwandlung"],"relevante_unterkonzepte_taxonomie":[{"value":"Energieumwandlung","taxonomyElementId":"cae3dfc7-1e67-428e-94a3-1bce20a1c28a"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Begründung sportlicher Betätigung nicht der zentrale Aspekt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_steuerung_regelung__regelung","basiskonzepte_primaer":["bk_steuerung_regelung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Experiment (GY-78-HUM-FPA-5): Pulsmessung vor und nach Belastung – Schüler erleben kardiovaskuläre Adaptation direkt."},{"rang":2,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Steinzeitmenschen haben täglich viele Kilometer gelaufen – was macht das mit dem Herz-Kreislauf-System, dem Nervensystem, den Hormonen und der psychischen Gesundheit? Und was macht Bewegungsmangel damit?'' – Wirkungen von Sport auf mehrere Organsysteme thematisieren."},{"rang":3,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich: Herzvolumen von Ausdauersportlern vs. Untrainierten – evolutionäre Erklärung der Trainingsanpassung."}],"bezug_zum_lehrplan_kontext":"Verbindung zu HUM-FPA-5 (Pulsmessung); Integrationslernziel mit Bezug zu Gesundheitsförderung","moegliche_fehlvorstellungen":"Schüler könnten Sport als ''zusätzliche'' Belastung betrachten; das evolutionäre Argument, dass Bewegung der Normalzustand ist, dreht diese Perspektive um.","evolutionsdidaktischer_impuls":"Leitfrage: ''Der Mensch wurde evolutionär als Ausdauerläufer geformt – was passiert mit einem Körper, der für Bewegung gebaut wurde, wenn er kaum bewegt wird?'' Einführung in evolutionäres Mismatch als Erklärung für Herz-Kreislauf-Erkrankungen und weitere Zivilisationskrankheiten."},"_2026_erprobungsfassung":{"note":"2026 reframes this as one example-based statement (''Maßnahmen zur Gesunderhaltung begründen (z. B. regelmäßige sportliche Betätigung)'') instead of separately naming Sport, Ernährung, and Lüftung as three required bullets. Not consolidated or deleted here -- whether to keep these as distinct items or fold them into one is a curriculum judgment call, not a mechanical one.","source":"LP Thueringen Bio Gym 2026 Erprobungsfassung (Erprobungsfassung, in Kraft seit 2026-08-01, noch nicht endgueltig verabschiedet)","updatedAt":"2026-09-12","textChanged":false},"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung"],"bk_prinzipien_taxonomie":[{"value":"Homöostase","taxonomyElementId":"d133832d-a92c-44f8-a967-db1f7b6a56ac"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-BHK-2"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '9e84fb43-0757-538e-8417-4316e36b7a27'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.10 Bionik - vom Entdecken zum Erfinden","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.10.4","unterthema":"10.4 Der Lotuseffekt","originaltext":"Vorbild: Laubblaetter, von denen Wassertropfen abperlen und dabei Schmutzteilchen mitnehmen. Prinzip: Oberfläche mit Wachsnoppen, sodass die Adhäsion eines Wassertropfens kleiner ist als die Kohäsion -- die Wassertropfen perlen ab. Funktionsmodell: Verhalten von Wasser auf wasserabweisender, genoppter Oberfläche; geprueft an verschiedenen Materialien mit entsprechenden Oberflächen. Übertragen: Autolacke, wasserabweisende Materialien für Zeltplanen, Wetterjacken und Schuhe. Fachpraktisch: Verhalten von Wassertropfen auf Laubblaettern unterschiedlicher Oberflächenbeschaffenheit beobachten (z. B. Kohlrabi, Gartenkresse, Erdbeere); Modellversuche mit unbehandeltem vs. gewachstem Baumwollstoff, einem wassergefuellten Ballon auf glatter vs. genoppter Oberfläche (z. B. Eierkarton, Akustikschaumstoff), und der Mitnahme von Russteilchen beim Abrollen von Wassertropfen über eine schraeg gestellte, berusste Glasplatte.","unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","note_2015_baseline":"Kein direktes 2015-Gegenstueck -- gleiche Anmerkung wie Klettverschluss. Baut ausdruecklich auf dem neuen Kohäsion/Adhäsion-Lernbereich (2.2.5) auf."}'::jsonb, description = 'Schuelerinnen und Schueler koennen den Lotuseffekt als biologisches Vorbild für wasserabweisende, selbstreinigende technische Oberflächen erläutern.' WHERE id = 'cc6fc4d8-88e3-4fce-80ec-2272bb5527ee'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-BHK-6","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-BHK-6","unterthema":"Blut und Herz-Kreislauf-System","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung begründen: ausgewogene Ernährung","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"begründen","kurzbezeichnung":"Gesunderhaltung: Ernährung","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das menschliche Herz-Kreislauf-System ist auf eine Ernährung ausgelegt, die reich an ungesättigten Fettsäuren und arm an gesättigten Fettsäuren war. Atherosklerose als Hauptursache von Herz-Kreislauf-Erkrankungen ist ein evolutionäres Mismatch: Das Blutgefäßsystem ist nicht für eine dauerhaft hohe Zufuhr gesättigter Fettsäuren und Zucker ausgelegt. Die evolutionäre Medizin (Darwinian medicine) betrachtet Herz-Kreislauf-Erkrankungen als Zivilisationskrankheiten, die durch die Abweichung moderner Ernährung von der evolutionären Nahrungsumwelt entstehen.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Evolutionäres Mismatch","Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Ausgewogene Ernährung betrifft die Stoffversorgung des Körpers, nicht direkt die individuelle Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen sind für die Begründung ausgewogener Ernährung nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für diese Ernährungsempfehlung nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Zufuhr ungesättigter statt gesättigter Fettsäuren ist eine unmittelbare Frage der Stoffaufnahme und ihrer Auswirkung auf das Kreislaufsystem: Ungesättigte Fettsäuren wirken sich günstiger auf die Blutfettwerte aus als gesättigte, was langfristig das Risiko für Gefäßerkrankungen beeinflusst. Ausgewogene Ernährung als Maßnahme zur Gesunderhaltung zu begründen setzt damit ein Verständnis dafür voraus, welche aufgenommenen Stoffe sich wie auf den Körper auswirken.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Begründung ausgewogener Ernährung nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Ernährungsanalyse: Schüler vergleichen typische Steinzeit-Ernährung mit moderner westlicher Ernährung – Fettsäurezusammensetzung, Zuckergehalt, Ballaststoffe."},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallstudie Atherosklerose: Wie entwickeln sich Ablagerungen in Blutgefäßen? Welche Ernährungsfaktoren begünstigen sie?"},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Wenn die Paleo-Diät evolutionär richtig ist – ist sie das wirklich? Was sind die Grenzen dieses Arguments?'' – kritische Reflexion."}],"bezug_zum_lehrplan_kontext":"Verbindung zu HUM-VD (Verdauungssystem und Ernährung); übergreifendes Integrationslernziel","moegliche_fehlvorstellungen":"Schüler könnten alle Fette als ''schlecht'' betrachten; die evolutionäre Bedeutung ungesättigter Fettsäuren muss differenziert erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Atherosklerose war in der Steinzeit kaum verbreitet – warum ist sie heute eine der häufigsten Todesursachen? Was hat sich in unserer Ernährung verändert?'' Evolutionäres Mismatch als Erklärung für moderne Herz-Kreislauf-Erkrankungen."},"_2026_erprobungsfassung":{"note":"2026 reframes this as one example-based statement (''Maßnahmen zur Gesunderhaltung begründen (z. B. regelmäßige sportliche Betätigung)'') instead of separately naming Sport, Ernährung, and Lüftung as three required bullets. Not consolidated or deleted here -- whether to keep these as distinct items or fold them into one is a curriculum judgment call, not a mechanical one.","source":"LP Thueringen Bio Gym 2026 Erprobungsfassung (Erprobungsfassung, in Kraft seit 2026-08-01, noch nicht endgueltig verabschiedet)","updatedAt":"2026-09-12","textChanged":false},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-VD-1"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '03081d03-3673-5cef-8662-ddde8fe16516'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-WIR-WTG-7","thema":"Wirbellose in ihren Lebensräumen","anmerkung":"Integrationslernziel mit BNE-Bezug","_source_id":"GY-78-WIR-WTG-7","unterthema":"Wirbellose als vielfältige Tiergruppe","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"Eingriffe des Menschen in Lebensräume von Wirbellosen bewerten und Maßnahmen zum Schutz begründen","bk_prinzipien":["Selektion"],"ist_praktisch":false,"kognitionsverb":"bewerten_begründen","kurzbezeichnung":"Eingriffe bewerten und Schutz begründen","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Anthropogene Eingriffe in Lebensräume stellen evolutionär relevante Selektionsdrücke dar, die in kurzen Zeiträumen zu messbaren evolutionären Veränderungen führen können (z. B. Pestizidresistenz bei Insekten durch gerichtete Selektion). Habitatverlust und -fragmentierung reduzieren die Populationsgrößen und erhöhen den genetischen Drift, was zur Verarmung der genetischen Diversität und langfristig zum Aussterben führen kann. Der Verlust von Wirbellosen unterbricht koevolutiv entstandene ökologische Netzwerke mit oft irreversiblen Folgen. Die Bewertung von Schutzmaßnahmen verbindet evolutionsbiologisches Wissen mit bioethischen Fragestellungen: Welche Verantwortung trägt der Mensch gegenüber dem Ergebnis von Milliarden Jahren Evolution? Biodiversität als evolutionär entstandenes Naturkapital ist einmal verloren nicht wiederherstellbar.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_evolutive_entwicklung__stammesgeschichte"],"relevante_evolutionskonzepte":["gerichtete Selektion","Gendrift","Aussterben","Koevolution","Evolutionäres Mismatch"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"gerichtete Selektion","taxonomyElementId":"73e20c77-73a9-4560-8ba6-abe7a9eb2de2"},{"value":"Gendrift","taxonomyElementId":"bae8d337-40e0-4b80-8be8-532953d27547"},{"value":"Aussterben","taxonomyElementId":"cf369ee2-c943-4d3b-968b-707b015c3ddf"},{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"}]},{"begruendung":"Die Bewertung von Habitateingriffen betrifft Populationen und Lebensräume, nicht die individuelle Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Zusammenhänge einzelner Merkmale stehen bei dieser Bewertungsaufgabe nicht im Vordergrund.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelkreise sind für die Bewertung anthropogener Habitateingriffe nicht das zentrale Konzept.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Verlust von Wirbellosen als Glieder von Nahrungsketten wirkt sich unmittelbar auf Stoffkreisläufe und das gesamte Ökosystem aus: Fehlen etwa Bestäuber oder Zersetzer, werden wichtige Stoffkreisläufe unterbrochen, was sich auf viele weitere Arten auswirken kann. Die Bewertung menschlicher Eingriffe in Lebensräume von Wirbellosen und die Begründung von Schutzmaßnahmen stützen sich unmittelbar auf diese stofflichen Zusammenhänge.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffkreislauf"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffkreislauf","taxonomyElementId":"a6c1d105-286c-4240-9db6-9c1851ee30fc"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Bewertung von Schutzmaßnahmen nicht der zentrale Aspekt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q1","systemebene_primaer":"Ökosystem","teilkonzept_primaer":"bk_evolutive_entwicklung__stammesgeschichte","basiskonzepte_primaer":["bk_evolutive_entwicklung"],"kognitive_anforderung":"analyse_und_bewertung","systemebene_sekundaer":"Population","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Bioethische Diskussionsrunde: Landwirtschaftliche Nutzung vs. Naturschutz – Schüler argumentieren aus verschiedenen Perspektiven und reflektieren die Verantwortung des Menschen gegenüber dem Ergebnis der Evolution. Explizite Einbeziehung bioethischer Fragen: Haben wir eine Pflicht, evolutionäre Diversität zu erhalten?"},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallstudie: Rückgang der Feldhamsterpopulationen oder Insektensterben in Deutschland – Schüler bewerten Maßnahmen anhand von Daten und diskutieren evolutionäre Konsequenzen des Verlusts genetischer Diversität."},{"rang":3,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Rollenspiel: Bauer, Naturschützer, Politiker, Wissenschaftler diskutieren Schutzmaßnahmen aus verschiedenen Perspektiven."}],"bezug_zum_lehrplan_kontext":"Integrationslernziel mit Bezug zu Bildung für nachhaltige Entwicklung (BNE) und Bioethik","moegliche_fehlvorstellungen":"Schüler könnten glauben, dass ''die Natur sich selbst hilft'' und der Mensch nicht eingreifen muss; die Irreversibilität von Artensterben und der Verlust evolutionärer Diversität muss deutlich gemacht werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Wenn Insekten durch Pestizide dezimiert werden – welche Arten überleben? Ist das ein evolutionärer Prozess? Und welche bioethische Verantwortung haben wir, wenn wir in die Evolution eingreifen?'' Führt zur Diskussion über anthropogene Selektion und Bioethik."},"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung"],"bk_prinzipien_taxonomie":[{"value":"Selektion","taxonomyElementId":"151dc9fd-9307-465a-9171-2163f889fd5e"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-WIR-WTG-5","GY-78-WIR-WTG-6"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'f3e19907-4d3d-52fd-ac91-b4cc0b03dece'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-WIR-INS-5","thema":"Wirbellose in ihren Lebensräumen","anmerkung":"Schlüssellernziel für Ind/Evo – Evolutiv","_source_id":"GY-78-WIR-INS-5","unterthema":"Insekten","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"die Angepasstheit an ihre Lebensweise bzw. Lebensräume erläutern: Nahrungsaufnahme","bk_prinzipien":["Selektion"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Insekten: Angepasstheit Nahrungsaufnahme","abstraktionsgrad":"mittel","ist_konzeptanker":true,"basiskonzeptbezug":[{"begruendung":"Die Mundwerkzeuge der Insekten sind eines der eindrucksvollsten Beispiele für adaptive Evolution: Ausgehend von einem ursprünglichen beißend-kauenden Grundtyp haben sich zahlreiche spezialisierte Formen entwickelt – saugend-leckende bei Bienen, stechend-saugende bei Stechmücken, saugende Rüssel bei Schmetterlingen. Diese Diversifikation hat in vielen Fällen Hand in Hand mit der Diversifikation der Nahrungsquellen (insbesondere Blütenpflanzen) stattgefunden – ein klassisches Beispiel für Koevolution. Dabei sind auf der Seite der Pflanzen spezifische Blütenformen, Farbmuster, Duftstoffe und Nektarangebote entstanden, die auf die Mundwerkzeuge und Sinnesorgane der jeweiligen Bestäuber abgestimmt sind. Umgekehrt haben sich die Mundwerkzeuge der Insekten an die Blütenstrukturen ihrer Nahrungsquellen angepasst. Die spezifische Angepasstheit der Mundwerkzeuge illustriert das Konzept der ökologischen Nischendifferenzierung.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_evolutive_entwicklung__variation_selektion"],"relevante_evolutionskonzepte":["Artbildung und adaptive Radiation","Koevolution","gerichtete Selektion","Anpassung und Angepasstheit","Funktion von Merkmalen"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Artbildung und adaptive Radiation","taxonomyElementId":"32b4337f-19eb-4860-99a1-fb1e4d73c731"},{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"gerichtete Selektion","taxonomyElementId":"73e20c77-73a9-4560-8ba6-abe7a9eb2de2"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Funktion von Merkmalen","taxonomyElementId":"912a42ac-9e13-4107-89cb-0a30a387e73e"}]},{"begruendung":"Die Angepasstheit der Mundwerkzeuge wird artvergleichend behandelt, nicht als individuelle Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die spezialisierten Mundwerkzeuge der Insekten, ob saugend, stechend oder kauend, sind ein direktes Beispiel für Struktur-Funktions-Zusammenhänge: Jeder Mundwerkzeugtyp ist strukturell exakt auf die jeweilige Nahrungsquelle abgestimmt, vom Saugrüssel des Schmetterlings über den Stechapparat der Stechmücke bis zu den kräftigen Kauwerkzeugen der Heuschrecke. Diese Vielfalt an Mundwerkzeugformen bei gleichem Grundbauplan veranschaulicht die enge Kopplung von Struktur und Ernährungsfunktion besonders eindrücklich.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelkreise sind für die Angepasstheit der Mundwerkzeuge an die Nahrungsquelle nicht das zentrale Konzept.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die spezialisierten Mundwerkzeuge der Insekten dienen unmittelbar der Nahrungsaufnahme und damit dem Stoffgewinn der Tiere: Ob saugend, stechend oder kauend, jeder Mundwerkzeugtyp ermöglicht die Aufnahme einer bestimmten Nahrungsquelle und damit bestimmter Stoffe aus der Umwelt. Die Erläuterung dieser Angepasstheit an die Nahrungsaufnahme berührt damit auch den stofflichen Aspekt der Ernährung.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die morphologische Angepasstheit der Mundwerkzeuge nicht ausschlaggebend.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q1","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_evolutive_entwicklung__variation_selektion","basiskonzepte_primaer":["bk_evolutive_entwicklung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Organ","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Mikroskopie (GY-78-WIR-FPA-2): Mundwerkzeuge verschiedener Insekten unter dem Mikroskop betrachten und Funktion ableiten."},{"rang":2,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Zuordnungsaufgabe: Mundwerkzeugtyp → Nahrungsquelle → Insektenart und entsprechendes Blütenmerkmal (Blütenform, Farbe, Duft, Nektarangebot) → Bestäuber; Schüler begründen koevolutionäre Zusammenhänge auf beiden Seiten."},{"rang":3,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Kreativaufgabe: ''Entwirf das ideale Mundwerkzeug für ein Insekt, das ausschließlich in röhrenförmigen Blüten Nektar saugt – und entwirf die passende Blütenform.'' Transfer evolutionären Denkens auf beide Koevolutionspartner."}],"bezug_zum_lehrplan_kontext":"Verbindung zu GY-78-WIR-WTG-6 (Bestäuber) und GY-78-WIR-FPA-2 (Mikroskopie von Mundwerkzeugen)","moegliche_fehlvorstellungen":"Schüler könnten denken, Insekten ''suchen sich aus'', was sie fressen; der Zusammenhang zwischen Mundwerkzeug-Morphologie und Selektionsvorteil muss erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum sieht der Rüssel eines Schmetterlings so anders aus als das Mundwerkzeug eines Maikäfers, obwohl beide Insekten sind? Und welche Blütenmerkmale haben sich an den Schmetterlingsrüssel angepasst?'' Einstieg in adaptive Evolution der Nahrungsaufnahme und Koevolution auf beiden Seiten."},"basiskonzepte_sekundaer":["bk_struktur_funktion"],"bk_prinzipien_taxonomie":[{"value":"Selektion","taxonomyElementId":"151dc9fd-9307-465a-9171-2163f889fd5e"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-WIR-INS-6","GY-78-WIR-INS-7"],"ermoeglichende_lernziele":["GY-78-WIR-WTG-7"],"konzeptanker_begruendung":"Erster expliziter Einstieg in evolutive Angepasstheit; Brücke zwischen Str/Fkt und Ind/Evo","voraussetzende_lernziele":["GY-78-WIR-INS-1","GY-78-WIR-INS-2"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '74dc2715-8e10-5728-997c-2a4701fd1cae'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-WIR-INS-6","thema":"Wirbellose in ihren Lebensräumen","anmerkung":"Gegenspielerprinzip kann hier eingeführt werden","_source_id":"GY-78-WIR-INS-6","unterthema":"Insekten","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"die Angepasstheit an ihre Lebensweise bzw. Lebensräume erläutern: Fortbewegung","bk_prinzipien":["Selektion","Gegenspielerprinzip"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Insekten: Angepasstheit Fortbewegung","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die Fortbewegungsorgane der Insekten – sechs gegliederte Beine und bei vielen Gruppen Flügel – sind genetisch festgelegte evolutionäre Anpassungen, die ihnen die Erschließung unterschiedlichster Lebensräume ermöglicht haben. Der Insektenflug ist eine der bedeutendsten Schlüsselinnovationen in der Erdgeschichte. Die Entstehung der Insektenflügel ist evolutionsbiologisch noch nicht vollständig geklärt (paranotal vs. Kiemenplattentheorie), was dieses Thema besonders interessant für die Wissenschaftsgeschichte macht. Verschiedene Fortbewegungsformen innerhalb der Insekten – Laufen, Springen, Graben, Schwimmen, Fliegen – illustrieren, wie ein gemeinsamer genetisch konservierter Grundbauplan (sechs Beine, dreigeteilter Körper) durch evolutionäre Differenzierung für sehr unterschiedliche Fortbewegungsweisen genutzt werden kann. Diese Diversifikation ist auf genetisch verankerte Unterschiede zurückzuführen, nicht auf individuelle Reaktionen auf Umwelteinflüsse (Modifikation im umweltbedingten Sinne). Es lohnt sich auch zu fragen, warum Insekten sechs Gliedmaßen haben – und nicht vier wie Säugetiere oder acht wie Spinnen – und was das über die genetisch fixierten Baupläne der Arthropodengruppen aussagt.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_evolutive_entwicklung__variation_selektion"],"relevante_evolutionskonzepte":["Exaptation (Umfunktionieren von Merkmalen)","Anpassung und Angepasstheit","Artbildung und adaptive Radiation","Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Exaptation (Umfunktionieren von Merkmalen)","taxonomyElementId":"2c3d2273-be42-4e8e-bc27-a8f1a8b94339"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Artbildung und adaptive Radiation","taxonomyElementId":"32b4337f-19eb-4860-99a1-fb1e4d73c731"},{"value":"Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)","taxonomyElementId":"80535000-9149-4a60-b7d3-5d56d5deddf3"}]},{"begruendung":"Die verschiedenen Fortbewegungsformen werden artvergleichend erklärt, nicht als individueller Entwicklungsschritt.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Beine und Flügel als Fortbewegungsorgane sind ein klassisches Beispiel für die Angepasstheit von Struktur an Funktion: Laufbeine sind für schnelle Bodenfortbewegung optimiert, Sprungbeine für weite Sprünge, Flügel für den Luftraum. Diese funktionale Vielfalt bei gemeinsamem Grundbauplan der Gliedmaßen macht die Angepasstheit der Insekten an ihre jeweilige Lebensweise strukturell besonders anschaulich.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die motorische Steuerung einzelner Bewegungsabläufe ist hier nicht der Fokus, sondern der Organbau selbst.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der energetische Aufwand der Fortbewegung wird bei diesem Lernziel nicht thematisiert.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die morphologische Angepasstheit der Fortbewegungsorgane nicht zentral.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q1","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_evolutive_entwicklung__variation_selektion","basiskonzepte_primaer":["bk_evolutive_entwicklung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Vergleichsaufgabe: Beine von Lauf-, Spring-, Grab- und Schwimminsekten vergleichen – Funktion aus Form ableiten. Diskussion: Wie sind diese Unterschiede genetisch festgelegt und durch natürliche Selektion entstanden – nicht durch individuelle Anpassung an die Umwelt?"},{"rang":2,"favorit":false,"methode":"Digitale Medien","beschreibung":"Videoanalyse: Zeitlupenaufnahmen von Insektenflug – Schüler beschreiben und diskutieren, wie der Flügel funktioniert."},{"rang":3,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Evolutionsdebatte: ''Woher kamen die Insektenflügel?'' – Schüler recherchieren zwei Hypothesen und diskutieren die Evidenz (Einblick in die Natur der Wissenschaft). Anschlusskfrage: Warum haben Insekten sechs Beine – im Kontrast zu Spinnen mit acht?"}],"bezug_zum_lehrplan_kontext":"Verbindung zu GY-78-WIR-INS-8 (Flügelausbildung als Klassifikationsmerkmal)","moegliche_fehlvorstellungen":"Schüler könnten Flügel und Beine als unabhängige Entwicklungen sehen; die evolutionäre Reihenfolge (zuerst Beine, dann Flügel) sollte thematisiert werden. Außerdem muss klar sein, dass ''Modifikation'' hier nicht im Sinne einer umweltbedingten phänotypischen Reaktion zu verstehen ist – die Unterschiede zwischen Insektenarten in der Fortbewegung sind genetisch verankert.","evolutionsdidaktischer_impuls":"Leitfrage: ''Insekten haben alle sechs Beine – trotzdem gibt es springende, grabende, schwimmende und fliegende Arten. Wie ist diese Vielfalt durch genetisch fixierte evolutionäre Differenzierung des gemeinsamen Grundbaus entstanden? Und warum sechs Beine – nicht vier oder acht?'' Einführung in adaptive Diversifikation bei konserviertem Grundplan."},"basiskonzepte_sekundaer":["bk_struktur_funktion"],"bk_prinzipien_taxonomie":[{"value":"Selektion","taxonomyElementId":"151dc9fd-9307-465a-9171-2163f889fd5e"},{"value":"Gegenspielerprinzip","taxonomyElementId":"c1db43df-ca8b-445e-8ff6-059bbba5e739"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-WIR-INS-5"],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-WIR-INS-1","GY-78-WIR-INS-2"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '64eba29c-e79b-5ac9-b240-278d4784ce3b'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-WIR-INS-9","thema":"Wirbellose in ihren Lebensräumen","anmerkung":"Kommunikation auf Populationsebene","_source_id":"GY-78-WIR-INS-9","unterthema":"Insekten","_source_file":"lernziele_gy78.json","alltagsnaehe":"mittel","originaltext":"das Zusammenleben in einem Insektenstaat an einem Beispiel erläutern","bk_prinzipien":["Signaltransduktion","Codierung und Decodierung von Information"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Insektenstaat erläutern","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Der Insektenstaat (Eusozialität) ist eines der faszinierendsten Phänomene der Evolutionsbiologie und hat lange als Rätsel für Darwins Evolutionstheorie gegolten: Wie kann die natürliche Selektion sterile Arbeiterinnen hervorbringen? Die Lösung lieferten William Hamilton (1964) mit dem Konzept der Gesamteignung (inclusive fitness) und der Verwandtenselektion (kin selection). Das Kastensystem im Insektenstaat ist das Ergebnis von Selektionsprozessen auf Gruppen- und Genebene. Die phänotypische Plastizität (Entwicklung zur Arbeiterin oder Königin abhängig von der Ernährung) zeigt, wie Umweltfaktoren die Genexpression steuern können. Ein Vergleich mit menschlichen Gesellschaften oder Familienstrukturen kann das Verständnis fördern und motivieren – dabei sollten aber die fundamentalen Unterschiede (genetisch-selektive Grundlage beim Insektenstaat vs. kulturelle Normen beim Menschen) klar herausgearbeitet werden, um Anthropomorphismen zu vermeiden. Eine Verbindung zur Evolution von Kooperation allgemein (z. B. Endosymbiose) ist ebenfalls wertvoll.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Verwandtenselektion","Evolution von Kooperation/Altruismus","Multilevel-Selektion","Phänotypische Plastizität","Fitness"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Verwandtenselektion","taxonomyElementId":"6d0f28c3-e728-4531-a825-7e40c0fc10e1"},{"value":"Evolution von Kooperation/Altruismus","taxonomyElementId":"856558c3-d1da-4c45-aa40-f757e2dd3c0a"},{"value":"Multilevel-Selektion","taxonomyElementId":"8b62ca52-5a75-4a0d-bc07-ee8c7f9a2f59"},{"value":"Phänotypische Plastizität","taxonomyElementId":"f24a74bb-ac84-4f12-8645-694213b6239b"},{"value":"Fitness","taxonomyElementId":"e39f4e1a-a37e-4dc3-bfcb-a031250cee54"}]},{"begruendung":"Die Kastenentwicklung wird hier nur am Rande berührt; der Fokus liegt auf dem sozialen Zusammenleben, nicht der individuellen Ontogenese.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Organe sind für das Zusammenleben im Insektenstaat nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Kastensystem eines Insektenstaats funktioniert wie ein Regelsystem, das über Pheromonsignale der Königin die Aufgabenverteilung im Staat konstant hält: Sinkt etwa die Konzentration bestimmter Pheromone, reagieren Arbeiterinnen mit einer veränderten Aufzucht neuer Königinnen. Diese Rückkopplung zwischen chemischem Signal und Verhaltensantwort stabilisiert die Sozialstruktur des gesamten Staates.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Negative Rückkopplung (inkl. Homöostase-Prinzip)"],"relevante_unterkonzepte_taxonomie":[{"value":"Negative Rückkopplung (inkl. Homöostase-Prinzip)","taxonomyElementId":"b1a84980-ecba-4199-8157-4be6c4fada55"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoffumwandlung ist für das soziale Zusammenleben im Insektenstaat nicht das zentrale Thema.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Chemische Kommunikation über Pheromone und die Tanzsprache der Bienen sind der Kern des koordinierten Zusammenlebens im Insektenstaat: Pheromone der Königin unterdrücken etwa die Eierstockentwicklung der Arbeiterinnen und halten so die soziale Ordnung aufrecht, während die Tanzsprache Informationen über Richtung und Entfernung einer Futterquelle codiert und an andere Sammlerinnen weitergibt. Beide Kommunikationsformen zeigen, wie komplex koordiniertes Sozialverhalten ganz ohne Sprache im menschlichen Sinne organisiert sein kann.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_information_kommunikation__kommunikation"],"relevante_unterkonzepte":["Chemische Kommunikation (Pheromone)","Akustische und visuelle Kommunikation"],"relevante_unterkonzepte_taxonomie":[{"value":"Chemische Kommunikation (Pheromone)","taxonomyElementId":"63378b82-f2c6-4fab-a91f-e386335fa2e4"},{"value":"Akustische und visuelle Kommunikation","taxonomyElementId":"b2de5a4e-d6ca-4d3e-8087-8096c4b61bf7"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q1","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_information_kommunikation__kommunikation","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallstudie Honigbiene: Schüler erarbeiten den Aufbau des Bienenstaates und stellen die Frage: ''Warum arbeitet eine Arbeiterin, ohne selbst Nachkommen zu haben?''"},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Simulation: Schüler modellieren mit Verwandtschaftsgraden, wieviel Gene eine Arbeiterin über die Königin weitergibt."},{"rang":3,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Analogie und Abgrenzung: Vergleich des Insektenstaates mit einer menschlichen Gesellschaft oder Familie – Gemeinsamkeiten (Arbeitsteilung, Kooperation) und grundlegende Unterschiede (genetisch-selektive Grundlage vs. kulturelle Normen) herausarbeiten. Auch: Verbindung zur Evolution von Kooperation allgemein (z. B. Endosymbiose als weiteres Beispiel)."}],"bezug_zum_lehrplan_kontext":"Besonders geeignet als Brücke zu Verhaltensbiologie und Evolutionsbiologie in höheren Klassenstufen","moegliche_fehlvorstellungen":"Schüler könnten Altruismus im Insektenstaat mit menschlichem Altruismus verwechseln; der mechanistische, selektionsbasierte Erklärungsansatz muss klar herausgearbeitet werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Eine Bienenarbeiterin arbeitet ihr ganzes Leben, ohne eigene Kinder zu haben. Aus Sicht der Evolution – macht das Sinn? Und wie unterscheidet sich das vom Zusammenleben in einer menschlichen Familie oder Gesellschaft?'' Hochmotivierende Frage, die zum Konzept der Gesamteignung und zum Vergleich mit menschlicher Kooperation führt."},"basiskonzepte_sekundaer":["bk_steuerung_regelung"],"bk_prinzipien_taxonomie":[{"value":"Signaltransduktion","taxonomyElementId":"599e5fa0-ac5f-4866-9fdb-69c99396b426"},{"value":"Codierung und Decodierung von Information","taxonomyElementId":"ef214769-1ffa-462e-bee3-b3000f803eb8"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-HUM-NER-3"],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-WIR-INS-4"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '21f94a7e-8a81-51a6-9fa9-601863d4b49e'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-ZEL-PTZ-4","thema":"Zellen als Lebensbausteine","anmerkung":"Brücke von Zellbiologie zu Verdauung und Zellatmung","_source_id":"GY-78-ZEL-PTZ-4","unterthema":"Pflanzliche und tierische Zellen","_source_file":"lernziele_gy78.json","alltagsnaehe":"mittel","originaltext":"den Zusammenhang zwischen Bau der Zelle und autotropher sowie heterotropher Ernährungsweise erläutern","bk_prinzipien":["Energetische Kopplung"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Zellbau und Ernährungsweise verknüpfen","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die Entstehung der Photosynthese (vor ca. 3,5 Milliarden Jahren bei Cyanobakterien) war eines der bedeutendsten evolutionären Ereignisse der Erdgeschichte und veränderte die Atmosphäre der Erde grundlegend (Große Sauerstoffkatastrophe). Die Photosynthese ermöglichte die Entstehung einer sauerstoffreichen Atmosphäre, die wiederum die Aerobiose und die Entstehung komplexen mehrzelligen Lebens ermöglichte. Der Besitz von Chloroplasten (durch Endosymbiose erworben) als strukturelle Grundlage der Autotrophie zeigt, wie ein evolutionäres Ereignis eine völlig neue Ernährungsstrategie ermöglichte. Heterotrophie ist evolutionär ursprünglicher, Autotrophie eine evolutionäre Innovation.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Endosymbiontentheorie","Natürliche Selektion und Selektionsdruck","Tiefenzeit","Anpassung und Angepasstheit"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Endosymbiontentheorie","taxonomyElementId":"94eb6ae3-f936-4cab-9181-f45197233dfa"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Tiefenzeit","taxonomyElementId":"733b2bfc-8d20-4d6f-b875-f97958cfbab7"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"}]},{"begruendung":"Ernährungsweisen werden hier artvergleichend erklärt, nicht als individueller Entwicklungsprozess.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Besitz von Chloroplasten als strukturelle Voraussetzung für Autotrophie ist der Kern dieses Lernziels: Nur Zellen mit diesem spezialisierten Kompartiment können mithilfe von Lichtenergie eigene organische Stoffe herstellen, während heterotrophe Zellen ohne Chloroplasten auf die Aufnahme bereits fertiger organischer Stoffe angewiesen sind. Diese Verknüpfung eines Zellorganells mit einer grundlegenden Ernährungsstrategie zeigt exemplarisch, wie strukturelle Ausstattung die möglichen Funktionen einer Zelle bestimmt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_struktur_funktion__struktur"],"relevante_unterkonzepte":["Zelluläre Kompartimentierung (Organellen)"],"relevante_unterkonzepte_taxonomie":[{"value":"Zelluläre Kompartimentierung (Organellen)","taxonomyElementId":"ceb27789-809b-4e36-8a86-b667c83148d6"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für den Zusammenhang von Zellbau und Ernährungsweise nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Autotrophie und Heterotrophie sind grundlegend verschiedene Strategien der Stoff- und Energieaufnahme: Autotrophe Zellen stellen ihre energiereichen Stoffe selbst aus anorganischen Ausgangsstoffen her, heterotrophe Zellen müssen diese Stoffe bereits fertig aus der Umwelt aufnehmen. Den Zusammenhang zwischen Zellbau und Ernährungsweise zu erläutern macht diesen fundamentalen Unterschied stofflicher Versorgungsstrategien nachvollziehbar.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__energie"],"relevante_unterkonzepte":["Stoffumwandlung"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffumwandlung","taxonomyElementId":"0d4c7b1d-0a19-483e-82fc-e5c1cc3a863d"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation spielt für den Zusammenhang von Zellbau und Ernährungsweise keine Rolle.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q2","systemebene_primaer":"Zelle","teilkonzept_primaer":"bk_stoff_energie_umwandlung__energie","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Organell","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Erdgeschichtlicher Zeitstrahl: Wann entstand Photosynthese? Was veränderte sich auf der Erde danach?"},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Modellversuch: Photosynthese nachweisen (Blasenbildung bei Wasserpflanzen im Licht) und mit Zellatmung vergleichen."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Warum haben Tiere keine Chloroplasten – wäre das nicht praktisch?'' Führt zur Diskussion über evolutionäre Möglichkeiten und Einschränkungen."}],"bezug_zum_lehrplan_kontext":"Verbindung zu ZEL-PTZ-2 (Endosymbiose); Grundlage für das Verständnis von Stoffkreisläufen in der Ökologie","moegliche_fehlvorstellungen":"Schüler könnten Photosynthese als selbstverständlich betrachten; die revolutionäre Natur dieser evolutionären Innovation muss herausgestellt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Wie hat die Erfindung der Photosynthese das Leben auf der Erde verändert?'' Einführung in evolutionäre Schlüsselereignisse mit globalen Konsequenzen."},"basiskonzepte_sekundaer":["bk_struktur_funktion"],"bk_prinzipien_taxonomie":[{"value":"Energetische Kopplung","taxonomyElementId":"9cd03f9a-998e-462d-a3c8-46fb60d0cc75"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-HUM-ATM-4"],"ermoeglichende_lernziele":["GY-78-HUM-ATM-4","GY-78-HUM-VD-1"],"voraussetzende_lernziele":["GY-78-ZEL-PTZ-2","GY-78-ZEL-PTZ-3"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'ac6ac392-ee3a-5a24-adc9-ea004a64144e'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-ZEL-BAK-2","thema":"Zellen als Lebensbausteine","anmerkung":"Alltagsrelevanz herstellen: Joghurt, Krankheiten, Kompost","_source_id":"GY-78-ZEL-BAK-2","unterthema":"Bakterien","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"die Bedeutung von Bakterien erläutern (z. B. in der Lebensmittelherstellung, als Krankheitserreger, als Zersetzer)","bk_prinzipien":["Stoffkreislauf"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Bedeutung von Bakterien erläutern","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die ökologischen Rollen der Bakterien sind das Ergebnis einer über 3,5 Milliarden Jahre andauernden evolutionären Diversifikation. Pathogene Bakterien sind Beispiele für Koevolution zwischen Erreger und Wirt: Das Immunsystem des Menschen wurde durch den evolutionären Rüstungswettlauf mit Bakterien geformt. Antibiotikaresistenz ist eines der eindrücklichsten Beispiele für Evolution in Echtzeit durch Selektion. Die Nutzung von Bakterien in der Lebensmittelherstellung zeigt, wie Menschen biotische Evolutionsergebnisse für ihre Zwecke nutzen (Domestikation von Mikroorganismen).","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","gerichtete Selektion","Artbildung und adaptive Radiation","Domestikation"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"gerichtete Selektion","taxonomyElementId":"73e20c77-73a9-4560-8ba6-abe7a9eb2de2"},{"value":"Artbildung und adaptive Radiation","taxonomyElementId":"32b4337f-19eb-4860-99a1-fb1e4d73c731"},{"value":"Domestikation","taxonomyElementId":"300c7d55-390e-4c29-a319-4fa1a95292a9"}]},{"begruendung":"Die ökologische Bedeutung der Bakterien betrifft Populationen und Prozesse, nicht die individuelle Entwicklung eines Organismus.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Bakterienarten stehen bei dieser Bedeutungsbetrachtung nicht im Vordergrund.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die ökologische und anwendungsbezogene Bedeutung der Bakterien nicht zentral.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Als Zersetzer sind Bakterien zentrale Akteure im Stoffkreislauf von Ökosystemen: Sie bauen abgestorbenes organisches Material in anorganische Bestandteile ab und führen diese damit wieder dem Nährstoffkreislauf zu, aus dem sie von Pflanzen erneut aufgenommen werden können. Die Bedeutung von Bakterien zu erläutern, etwa auch in Lebensmittelherstellung oder als Krankheitserreger, macht ihre zentrale Rolle für stoffliche Kreisläufe in unterschiedlichen Kontexten sichtbar.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffkreislauf"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffkreislauf","taxonomyElementId":"a6c1d105-286c-4240-9db6-9c1851ee30fc"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Krankheitserregende Bakterien interagieren über molekulare Signale mit dem Immunsystem des Wirts: Bestimmte Oberflächenstrukturen der Bakterien werden von Immunzellen erkannt und lösen darüber eine Abwehrreaktion aus, während manche Erreger diese Signalwege gezielt manipulieren, um der Immunantwort zu entgehen. Diese molekulare Signalinteraktion ist damit ein zentraler, wenn auch hier nur mitgedachter Aspekt der vielfältigen Bedeutung von Bakterien.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_information_kommunikation__kommunikation"],"relevante_unterkonzepte":["Signaltransduktion"],"relevante_unterkonzepte_taxonomie":[{"value":"Signaltransduktion","taxonomyElementId":"876b0ce3-b903-4bcc-9364-382a7ceae31e"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q2","systemebene_primaer":"Ökosystem","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Organismus","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallstudie Antibiotikaresistenz: Schüler erarbeiten, wie Selektion durch Antibiotika zu resistenten Stämmen führt – Evolution in Echtzeit."},{"rang":2,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Experiment: Joghurtherstellung mit Milchsäurebakterien als Erfahrung biotechnologischer Nutzung evolutionärer Produkte."},{"rang":3,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Rollenspiel: ''Gut-Bakterien vs. krank-machende Bakterien'' – Unterscheidung und evolutionäre Hintergründe aus der Perspektive verschiedener Bakterienarten."}],"bezug_zum_lehrplan_kontext":"Verbindung zu GY-78-HUM-ABW (Abwehrsystem, Immunisierung); hochaktuelles Gesellschaftsthema","moegliche_fehlvorstellungen":"Schüler könnten denken, Bakterien ''lernen'', Antibiotika zu widerstehen; der zufällige Charakter der Mutation und die Selektion danach muss klar erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Wenn wir Antibiotika nehmen und die meisten Bakterien sterben – welche überleben? Was passiert mit der nächsten Generation?'' Einführung in das Konzept der Selektion am aktuellen Beispiel."},"basiskonzepte_sekundaer":["bk_information_kommunikation"],"bk_prinzipien_taxonomie":[{"value":"Stoffkreislauf","taxonomyElementId":"df08b5ac-d37e-4767-8844-2bb4757a8233"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-HUM-ABW-1"],"voraussetzende_lernziele":["GY-78-ZEL-BAK-1"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '6948a765-3f49-53b9-90d7-8668176c79e4'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-VD-1","thema":"Biologie des Menschen","anmerkung":"Phänomenologischer Einstieg in Stoff/Energie über Essen","_source_id":"GY-78-HUM-VD-1","unterthema":"Verdauungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"die Zusammensetzung der Nahrung aus Nährstoffen (Kohlenhydrate, Fette, Proteine) und Ergänzungsstoffen (z. B. Vitamine, Mineralsalze, Wasser, Ballaststoffe) erläutern","bk_prinzipien":["Fließgleichgewicht"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Nahrungszusammensetzung erläutern","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die Nährstoffbedürfnisse des Menschen sind das Ergebnis evolutionärer Anpassungen an die Ernährungsweise unserer Vorfahren. Die Omnivorie des Menschen ist eine evolutionäre Flexibilitätsstrategie. Die Abhängigkeit von bestimmten Vitaminen (z. B. Vitamin C), die der Mensch selbst nicht synthetisieren kann (im Gegensatz zu den meisten anderen Säugetieren), ist das Ergebnis eines evolutionären Genverlusts – ein klassisches Beispiel für ''use it or lose it'' in der Evolution. Der menschliche Verdauungstrakt zeigt ebenfalls evolutionäre Angepasstheit an Omnivorie.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck","Evolutionäres Mismatch","genetische Variation"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"genetische Variation","taxonomyElementId":"31375847-cad0-4b61-9b67-74e68ea8c520"}]},{"begruendung":"Die Nährstoffzusammensetzung der Nahrung betrifft die Ernährung, nicht die individuelle Entwicklung direkt.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Organe sind für die Nährstoffzusammensetzung nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die reine Beschreibung der Nährstoffzusammensetzung nicht relevant.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kohlenhydrate, Fette, Proteine und Ergänzungsstoffe wie Vitamine, Mineralsalze oder Ballaststoffe sind unmittelbar Gegenstand der Stoffaufnahme, dem Kern dieses Basiskonzepts: Jede dieser Stoffgruppen erfüllt eine eigene Funktion im Körper, von der Energiebereitstellung über den Aufbau körpereigener Strukturen bis zur Unterstützung der Verdauung. Die Erläuterung der Nahrungszusammensetzung liefert damit die stoffliche Grundlage für alle weiteren Ernährungslernziele.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Nährstoffzusammensetzung der Nahrung nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"reproduktion_und_verstaendnis","systemebene_sekundaer":"Molekül","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich: Darmlänge verschiedener Säugetiere (Carnivore, Herbivore, Omnivore) – Was sagt die Länge über die Ernährungsweise aus?"},{"rang":2,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Fallbeispiel Vitamin C: Warum werden Matrosen auf langen Reisen von Skorbut krank? Evolutionäre Erklärung des Vitamin-C-Bedarfs."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Ist die moderne westliche Ernährung mit dem evolutionären Nährstoffbedarf des Menschen vereinbar?'' – kritische Reflexion."}],"bezug_zum_lehrplan_kontext":"Grundlage für HUM-VD-2 bis -8; Verbindung zur Gesundheitserziehung und Ernährungskunde","moegliche_fehlvorstellungen":"Schüler könnten Nährstoffbedürfnisse als ''zufällig'' betrachten; die evolutionäre Ursache spezifischer Nährstoffabhängigkeiten muss herausgearbeitet werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum kann der Mensch kein Vitamin C selbst herstellen, obwohl fast alle anderen Säugetiere das können? Wann und warum wurde diese Fähigkeit aufgegeben?'' Evolutionärer Genverlust als faszinierendes Konzept."},"basiskonzepte_sekundaer":[],"bk_prinzipien_taxonomie":[{"value":"Fließgleichgewicht","taxonomyElementId":"23d0855d-a60f-4bfb-becb-8f1824c28c58"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-HUM-VD-2"],"voraussetzende_lernziele":["GY-78-ZEL-PTZ-4"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'b8782eea-f8c3-56cc-a82c-7cf35d72fcc2'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-VD-4","thema":"Biologie des Menschen","anmerkung":"Abstraktes Regelkreisschema vor diesem Lernziel einführen","_source_id":"GY-78-HUM-VD-4","unterthema":"Verdauungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"die Regulierung des Blutzuckerspiegels erläutern (Regelkreis, Zusammenspiel von Insulin und Glukagon)","bk_prinzipien":["Negative Rückkopplung","Homöostase"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Blutzuckerregelung erläutern","abstraktionsgrad":"hoch","ist_konzeptanker":true,"basiskonzeptbezug":[{"begruendung":"Die hormonelle Regulierung des Blutzuckerspiegels durch Insulin und Glukagon ist ein evolutionär hoch konserviertes System: Insulin-ähnliche Moleküle finden sich bereits bei Wirbellosen (z. B. bei Tintenfischen und sogar bei Nematoden). Das negative Rückkopplungsprinzip des Blutzuckersystems ist ein evolutionäres Grundprinzip der Homöostase. Diabetes mellitus Typ 2 kann als evolutionäres Mismatch interpretiert werden: Der ''Thrifty Genotype'' (Neel, 1962) postuliert, dass die evolutionäre Selektion auf effiziente Glukosespeicherung unter modernen Bedingungen des permanenten Nahrungsüberflusses zu Insulinresistenz und Diabetes führt.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)","Evolutionäres Mismatch","gemeinsame Abstammung/Verwandtschaft","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)","taxonomyElementId":"80535000-9149-4a60-b7d3-5d56d5deddf3"},{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Die Blutzuckerregulierung ist ein physiologischer Regelmechanismus ohne Bezug zur individuellen Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Zellen der Bauchspeicheldrüse sind hier dem Regelkreis nachgeordnet.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Insulin und Glukagon wirken als hormonelle Gegenspieler in einem negativen Rückkopplungskreis und bilden damit das Paradebeispiel für Homöostase-Regelung in diesem Basiskonzept: Steigt der Blutzuckerspiegel nach einer Mahlzeit über den Sollwert, schüttet die Bauchspeicheldrüse Insulin aus, das die Zellen zur Glukoseaufnahme anregt und den Spiegel senkt; sinkt er dagegen unter den Sollwert, wird stattdessen Glukagon ausgeschüttet, das gespeicherte Glukose freisetzt. Durch dieses Wechselspiel zweier gegensätzlich wirkender Hormone wird der Blutzuckerspiegel in einem engen Bereich konstant gehalten.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Negative Rückkopplung (inkl. Homöostase-Prinzip)"],"relevante_unterkonzepte_taxonomie":[{"value":"Negative Rückkopplung (inkl. Homöostase-Prinzip)","taxonomyElementId":"b1a84980-ecba-4199-8157-4be6c4fada55"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Blutzuckerspiegel selbst ist eine Stoffgröße, die durch die hormonelle Regelung mithilfe von Insulin und Glukagon konstant gehalten wird: Glukose als zentraler Energieträger im Blut muss in einem engen Bereich gehalten werden, weder zu hoch noch zu niedrig, um die Versorgung der Körperzellen sicherzustellen. Die Erläuterung dieser Regelung berührt damit auch diesen stofflichen Aspekt, auch wenn der Schwerpunkt eher bei Steuerung und Regelung liegt.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffumwandlung"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffumwandlung","taxonomyElementId":"0d4c7b1d-0a19-483e-82fc-e5c1cc3a863d"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Insulin und Glukagon übermitteln als chemische Botenstoffe Information zwischen Bauchspeicheldrüse und Zielorganen: Beide Hormone signalisieren den Zellen von Leber, Muskel und Fettgewebe, ob Glukose aufgenommen und gespeichert oder freigesetzt werden soll. Diese hormonelle Informationsübertragung macht die Regulierung des Blutzuckerspiegels zu einem anschaulichen Beispiel chemischer Kommunikation im Körper.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_information_kommunikation__kommunikation"],"relevante_unterkonzepte":["Hormonelle Kommunikation (endokrines System)"],"relevante_unterkonzepte_taxonomie":[{"value":"Hormonelle Kommunikation (endokrines System)","taxonomyElementId":"43e673f6-34ea-4ffa-9c21-4e5afbd1614b"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organ","teilkonzept_primaer":"bk_steuerung_regelung__regelung","basiskonzepte_primaer":["bk_steuerung_regelung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Molekül","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Regelkreis-Diagramm: Schüler zeichnen und erläutern den Blutzucker-Regelkreis mit Insulin und Glukagon."},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallstudie Diabetes Typ 2: ''Was passiert, wenn der Regelkreis gestört ist? Warum ist Diabetes eine Zivilisationskrankheit?''"},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Welchen Vorteil hatte die effiziente Glukosespeicherung für Steinzeitmenschen? Warum ist dasselbe Gen heute ein Risikofaktor?'' – Mismatch-Konzept diskutieren."}],"bezug_zum_lehrplan_kontext":"Verbindung zu HUM-FES-1 (Hormonsystem); Grundlage für HUM-VD-5 bis -8 (Ernährungsgesundheit)","moegliche_fehlvorstellungen":"Schüler könnten Diabetes als rein moderne Erkrankung ohne evolutionären Hintergrund sehen; die evolutionäre Erklärung über die Thrifty-Genotype-Hypothese ist aufschlussreich und motivierend.","evolutionsdidaktischer_impuls":"Leitfrage: ''Insulin-ähnliche Moleküle gibt es schon bei Würmern – warum hat die Evolution dieses System so lange beibehalten? Und warum macht uns dasselbe System heute krank?'' Einführung in evolutionäre Konservierung und Mismatch."},"basiskonzepte_sekundaer":["bk_information_kommunikation","bk_stoff_energie_umwandlung"],"bk_prinzipien_taxonomie":[{"value":"Negative Rückkopplung","taxonomyElementId":"b943e1a0-07ed-4050-8637-03597c11e2e1"},{"value":"Homöostase","taxonomyElementId":"d133832d-a92c-44f8-a967-db1f7b6a56ac"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-HUM-ATM-2"],"ermoeglichende_lernziele":["GY-78-HUM-FES-3","GY-78-HUM-AUS-2","GY-78-HUM-ZUS-2"],"konzeptanker_begruendung":"Erste und wichtigste explizite Einführung des Regelkreisprinzips; Konzeptanker für Steu/Reg – Regelung","voraussetzende_lernziele":["GY-78-HUM-VD-3","GY-78-HUM-BHK-3"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":2}'::jsonb WHERE id = '41939086-fa9c-5888-a8a4-4ac0dcf0772b'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-VD-5","thema":"Biologie des Menschen","anmerkung":"Integrationslernziel Ernährung","_source_id":"GY-78-HUM-VD-5","unterthema":"Verdauungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung erläutern: bedarfsangepasste Ernährung","bk_prinzipien":["Energieentwertung","Fließgleichgewicht"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Gesunde Ernährung: bedarfsangepasst","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Bedarfsangepasste Ernährung spiegelt die evolutionäre Anpassung des menschlichen Stoffwechsels an unterschiedliche Lebensphasen und Aktivitätsniveaus wider. Der veränderte Nährstoffbedarf in der Pubertät (Wachstum), im Alter (Muskelabbau, Knochendichte) und bei hoher körperlicher Aktivität ist das Ergebnis evolutionärer Anpassungen. Im evolutionären Kontext war bedarfsangepasste Ernährung selbstregulierend (Hungergefühl, Sattheitsgefühl). Die modernen Ernährungsempfehlungen versuchen, diese evolutionär entstandenen Bedürfnisse unter modernen Bedingungen zu optimieren.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Lebensgeschichte / Life-History-Theorie","Anpassung und Angepasstheit","Evolutionäres Mismatch"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Lebensgeschichte / Life-History-Theorie","taxonomyElementId":"c6d1f463-8049-4f4b-b430-1c8ae90c07c6"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"}]},{"begruendung":"Der veränderte Nährstoffbedarf in Pubertät und im höheren Lebensalter ist unmittelbar mit unterschiedlichen Phasen individueller Entwicklung verknüpft: Während der Wachstumsphase ist der Bedarf an Baustoffen wie Proteinen besonders hoch, im Alter verändert er sich durch nachlassende Stoffwechselaktivität erneut. Bedarfsangepasste Ernährung berücksichtigt damit den jeweiligen Entwicklungsstand des Körpers.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_individuelle_entwicklung__reifung"],"relevante_unterkonzepte":["Wachstum","Seneszenz/Alterung"],"relevante_unterkonzepte_taxonomie":[{"value":"Wachstum","taxonomyElementId":"cdbe94e3-b8d8-4ad9-843f-58ad11a56faf"},{"value":"Seneszenz/Alterung","taxonomyElementId":"fd772680-41ea-4c70-a704-0461d2d5a550"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Organe sind für bedarfsangepasste Ernährung nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Hunger- und Sättigungsgefühl regeln die Nahrungsaufnahme in Abhängigkeit vom aktuellen Energiebedarf des Körpers: Sinkt der Blutzuckerspiegel, entsteht Hungergefühl, das zur Nahrungsaufnahme anregt; steigt er nach der Mahlzeit wieder an, setzt Sättigung ein und beendet sie. Bedarfsangepasste Ernährung berücksichtigt damit bewusst diese natürliche Regelung.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Negative Rückkopplung (inkl. Homöostase-Prinzip)"],"relevante_unterkonzepte_taxonomie":[{"value":"Negative Rückkopplung (inkl. Homöostase-Prinzip)","taxonomyElementId":"b1a84980-ecba-4199-8157-4be6c4fada55"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Anpassung der Nährstoffzufuhr an Lebensphase und Aktivität ist der Kern dieses Lernziels zur Energieumwandlung: Der Energiebedarf eines Menschen variiert je nach Alter, Wachstumsphase und körperlicher Aktivität erheblich, weshalb eine bedarfsangepasste Ernährung genau diese schwankende Energiebilanz berücksichtigen muss. Maßnahmen zur bedarfsangepassten Ernährung zu erläutern setzt damit ein Verständnis individuell unterschiedlicher Energieumsätze voraus.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__energie"],"relevante_unterkonzepte":["Energieumwandlung"],"relevante_unterkonzepte_taxonomie":[{"value":"Energieumwandlung","taxonomyElementId":"cae3dfc7-1e67-428e-94a3-1bce20a1c28a"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die bedarfsangepasste Ernährung nicht der zentrale Aspekt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__energie","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Nährstoffbedarfs-Analyse: Schüler vergleichen Nährstoffbedarf von Kindern, Jugendlichen, Erwachsenen und Senioren – warum unterscheidet er sich?"},{"rang":2,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Was ist die Paleo-Diät? Hat sie wissenschaftliche Grundlagen? Wo sind ihre Grenzen?'' – kritische Reflexion über evolutionäre Ernährungskonzepte."},{"rang":3,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Selbstanalyse: Schüler dokumentieren ihre Ernährung einer Woche und vergleichen mit Empfehlungen – Reflexion über evolutionären Bedarf vs. moderne Ernährungsgewohnheiten."}],"bezug_zum_lehrplan_kontext":"Verbindung zu HUM-VD-1 (Nährstoffe); Teil der integrativen Gesundheitserziehung","moegliche_fehlvorstellungen":"Schüler könnten Ernährungsempfehlungen als willkürlich betrachten; die evolutionäre und physiologische Grundlage von Ernährungsempfehlungen muss verdeutlicht werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Wie hat sich der Ernährungsbedarf des Menschen im Laufe der Evolution verändert – und passt unsere heutige Ernährung dazu?'' Einführung in die evolutionäre Ernährungswissenschaft."},"basiskonzepte_sekundaer":[],"bk_prinzipien_taxonomie":[{"value":"Energieentwertung","taxonomyElementId":"89267acc-76d8-4c21-9d6d-d8450bd849ec"},{"value":"Fließgleichgewicht","taxonomyElementId":"23d0855d-a60f-4bfb-becb-8f1824c28c58"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-VD-1"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'b1da5a23-a72e-593c-82d0-710c71e6176f'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-VD-7","thema":"Biologie des Menschen","anmerkung":"Sensibles Thema; einfühlsam behandeln","_source_id":"GY-78-HUM-VD-7","unterthema":"Verdauungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung erläutern: Prävention essgestörten Verhaltens (an einem Beispiel)","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Essstörungen: Prävention","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das menschliche Körpergewichtsregulationssystem (Leptin-Ghrelin-Achse) ist evolutionär auf die Vermeidung von Untergewicht hin optimiert, was erklärt, warum Diäten evolutionär konterkariert werden (Jojo-Effekt). Das Schönheitsideal der Schlankheit ist kulturell, kollidiert aber mit evolutionären Körperreserven-Regulationssystemen – ein Beispiel für das Spannungsfeld zwischen kultureller und biologischer Evolution.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Evolutionäres Mismatch","Anpassung und Angepasstheit","kulturelle Evolution","Lebensgeschichte / Life-History-Theorie"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"kulturelle Evolution","taxonomyElementId":"2905fb0d-c1cb-47c9-8772-bf107e6843e4"},{"value":"Lebensgeschichte / Life-History-Theorie","taxonomyElementId":"c6d1f463-8049-4f4b-b430-1c8ae90c07c6"}]},{"begruendung":"Essstörungen berühren psychische und soziale Aspekte, die über die individuelle körperliche Entwicklung hinausgehen und hier nicht vertieft werden.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Organe sind für die Prävention von Essstörungen nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Essgestörtes Verhalten stört die körpereigene Regelung von Hunger- und Sättigungsgefühl empfindlich: Bei Anorexie oder Bulimie wird das natürliche Rückkopplungssignal zwischen Nahrungsaufnahme und Sättigung bewusst oder unbewusst überschrieben, sodass die Regelung ihre stabilisierende Funktion verliert. Präventionsmaßnahmen setzen an dieser gestörten Regelung an.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Negative Rückkopplung (inkl. Homöostase-Prinzip)"],"relevante_unterkonzepte_taxonomie":[{"value":"Negative Rückkopplung (inkl. Homöostase-Prinzip)","taxonomyElementId":"b1a84980-ecba-4199-8157-4be6c4fada55"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Essstörungen betreffen unmittelbar die Energiebilanz und -aufnahme des Körpers: Bei Erkrankungen wie Anorexie oder Bulimie gerät das Gleichgewicht zwischen aufgenommener und benötigter Energie schwer aus dem Takt, mit teils gravierenden gesundheitlichen Folgen. Maßnahmen zur Prävention essgestörten Verhaltens zu erläutern setzt ein Verständnis dieser gestörten Energiebilanz voraus.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__energie"],"relevante_unterkonzepte":["Energieumwandlung"],"relevante_unterkonzepte_taxonomie":[{"value":"Energieumwandlung","taxonomyElementId":"cae3dfc7-1e67-428e-94a3-1bce20a1c28a"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Prävention essgestörten Verhaltens nicht der zentrale Aspekt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__energie","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"analyse_und_bewertung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Sachtext-Analyse: Artikel über Leptin und Ghrelin als Hunger- und Sättigungshormone – evolutionäre Funktion herausarbeiten."},{"rang":2,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Warum ist Diäthalten schwer? Was passiert im Körper, wenn man weniger isst?'' – evolutionärer Hintergrund des Jojo-Effekts."},{"rang":3,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Sensibilisierungsaufgabe: Schüler reflektieren Schönheitsideale in den Medien und hinterfragen sie mit biologischem Wissen."}],"bezug_zum_lehrplan_kontext":"Integrationslernziel mit Bezug zu Gesundheitserziehung und psychischer Gesundheit; sensibles Thema erfordert einfühlsamen didaktischen Ansatz","moegliche_fehlvorstellungen":"Schüler könnten Essstörungen als reine Willensschwäche betrachten; die neurobiologische und evolutionäre Grundlage muss sensibel aber klar erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Unser Körper kämpft gegen Gewichtsverlust – warum wurde dieses System evolutionär so eingestellt? Und warum ist das heute manchmal ein Problem?'' Einführung in evolutionäres Mismatch bei Essstörungen."},"basiskonzepte_sekundaer":["bk_steuerung_regelung"],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-VD-5"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '81c6fff3-200a-5394-a7e3-186c4c30acec'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ATM-6","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-ATM-6","unterthema":"Atmungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung begründen: Reduzierung von Luftschadstoffen","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"begründen","kurzbezeichnung":"Gesunderhaltung: Luftschadstoffe","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Luftschadstoffe (Feinstaub, Stickoxide, Ozon) stellen evolutionäre Stressoren dar, auf die das Immunsystem und die Atemwegsschleimhäute evolutionär nicht vorbereitet sind – ein weiteres Beispiel für evolutionäres Mismatch. Die zunehmende Prävalenz von Asthma und anderen Atemwegserkrankungen in industrialisierten Ländern kann teilweise als evolutionäres Mismatch des Immunsystems mit modernen Umweltbedingungen interpretiert werden (Hygiene-Hypothese).","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Evolutionäres Mismatch","Anpassung und Angepasstheit","Koevolution"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"}]},{"begruendung":"Luftschadstoffe betreffen Gesundheitsrisiken, nicht direkt die individuelle Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen sind für die Begründung der Schadstoffreduzierung nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für dieses Gesundheitsthema nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Feinstaub und Stickoxide sind Stoffe, deren Aufnahme über die Atemwege hier begründet vermieden werden soll: Beide Schadstoffgruppen gelangen beim Einatmen tief in die Lunge und können dort gesundheitsschädliche Wirkungen entfalten. Maßnahmen zur Reduzierung von Luftschadstoffen zu begründen setzt ein Verständnis dieses unerwünschten stofflichen Eintrags in den Körper voraus.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Reduzierung von Luftschadstoffen nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallstudie: Atemwegserkrankungen in Städten mit hoher Luftverschmutzung vs. ländlichen Gebieten – Schüler analysieren epidemiologische Daten."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Modell der Luftreinigung: Schüler demonstrieren die Filterfunktion der Nasenhaare mit einfachen Materialien."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Hygiene-Hypothese: ''Warum haben Kinder, die auf Bauernhöfen aufwachsen, seltener Allergien? Was sagt uns das über unser Immunsystem?''"}],"bezug_zum_lehrplan_kontext":"Verbindung zu HUM-ABW (Abwehrsystem); Bezug zu Umweltbildung und BNE","moegliche_fehlvorstellungen":"Schüler könnten sauberere Luft immer als ''besser'' betrachten; das Konzept eines evolutionär ausbalancierten Immunsystems, das Reize benötigt, muss differenziert erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Unser Immunsystem erwartet Kontakt mit Bakterien und Parasiten – was passiert, wenn es diesen Kontakt nicht bekommt? Warum könnten zu saubere Umgebungen Allergien fördern?'' Einführung in die Hygiene-Hypothese als evolutionäres Konzept."},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-ATM-4"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '43f61a79-3d84-50c7-b5fb-0c79d0e11b8b'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-WIR-WTG-6","thema":"Wirbellose in ihren Lebensräumen","anmerkung":"Erster Kontakt mit Stoff/Energie auf Ökosystemebene","_source_id":"GY-78-WIR-WTG-6","unterthema":"Wirbellose als vielfältige Tiergruppe","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"die Bedeutung Wirbelloser in der Natur (z. B. als Glieder von Nahrungsketten, Bestäuber, Krankheitsüberträger) an Beispielen erläutern","bk_prinzipien":["Stoffkreislauf"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Bedeutung Wirbelloser in der Natur","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die ökologischen Rollen Wirbelloser sind Ergebnis langer koevolutiver Prozesse. Die Bestäubung durch Insekten ist eines der bekanntesten Beispiele für Koevolution: Die wechselseitige Abhängigkeit von Blütenpflanzen und bestäubenden Insekten hat sowohl die Diversifikation der Angiospermen als auch die der Insekten maßgeblich vorangetrieben. Auf der Seite der Pflanzen sind Blütenformen, Duftstoffe, Nektarangebote und Farbmuster (einschließlich UV-Muster) durch wechselseitige Selektion auf die Sensorik der Bestäuber hin optimiert worden. Auf der Seite der Insekten sind Mundwerkzeuge, Körperform und Sinnesorgane (z. B. UV-Sehvermögen, Blütenduft-Rezeptoren) koevolutiv auf die Pflanzen abgestimmt. Wirbellose als Krankheitsüberträger (z. B. Stechmücken als Vektoren für Malaria) sind Beispiele für koevolutive Wettbewerbe zwischen Pathogen, Vektor und Wirt.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","Natürliche Selektion und Selektionsdruck","Anpassung und Angepasstheit","Nischenkonstruktion","Artbildung und adaptive Radiation"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Nischenkonstruktion","taxonomyElementId":"90d33e38-ad06-4ce6-b3c3-3eee58a48292"},{"value":"Artbildung und adaptive Radiation","taxonomyElementId":"32b4337f-19eb-4860-99a1-fb1e4d73c731"}]},{"begruendung":"Ökologische Rollen wie Bestäuber oder Vektor betreffen Populationen, nicht die individuelle Entwicklung eines Tieres.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Mundwerkzeuge und Sinnesorgane als funktionale Anpassung an die Bestäubungsleistung von Insekten sind hier indirekt mitgedacht: Dass Wirbellose als Bestäuber wichtig sind, hängt strukturell davon ab, dass ihre Mundwerkzeuge zum Blütenbau der jeweiligen Pflanze passen. Die Bedeutung Wirbelloser in der Natur zu erläutern berührt damit am Rande auch strukturelle Passungen zwischen Tier und Pflanze.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelkreise einzelner Organismen sind für die ökologische Bedeutung Wirbelloser nicht der Fokus.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Als Glieder von Nahrungsketten sind Wirbellose zentral in den Stoff- und Energiefluss von Ökosystemen eingebunden: Ob als Beute für größere Tiere, als Bestäuber, die den Fortbestand von Pflanzen sichern, oder als Zersetzer, die organisches Material in den Stoffkreislauf zurückführen, Wirbellose übernehmen an vielen Stellen der Nahrungskette unverzichtbare Funktionen. Die Bedeutung Wirbelloser an Beispielen zu erläutern macht diese vielfältige Einbindung in Stoff- und Energieflüsse konkret sichtbar.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Energiefluss durch Nahrungsketten"],"relevante_unterkonzepte_taxonomie":[{"value":"Energiefluss durch Nahrungsketten","taxonomyElementId":"a4f52ebd-a511-417d-8dfa-40028b379690"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Bestäubung beruht auf chemischer und optischer Signalübertragung zwischen Blüte und Insekt: Blüten locken Bestäuber gezielt mit Duftstoffen und auffälligen Farben an, während das Insekt im Gegenzug Pollen zwischen den Blüten überträgt. Diese wechselseitige Signalkommunikation ist eine Voraussetzung dafür, dass Wirbellose als Bestäuber überhaupt ihre ökologische Bedeutung entfalten können.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_information_kommunikation__kommunikation"],"relevante_unterkonzepte":["Chemische Kommunikation (Pheromone)"],"relevante_unterkonzepte_taxonomie":[{"value":"Chemische Kommunikation (Pheromone)","taxonomyElementId":"63378b82-f2c6-4fab-a91f-e386335fa2e4"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q1","systemebene_primaer":"Ökosystem","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Organismus","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Fallstudie Biene und Blüte: Schüler analysieren, welche Merkmale der Biene zur Bestäubung beitragen und – ebenso wichtig – welche Merkmale der Blüte (Farbe, Form, Duft, UV-Muster, Nektarangebot) evolutionär auf die Sensorik der Bestäuber abgestimmt sind. Beide Seiten der Koevolution werden gleichwertig betrachtet."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Nahrungsnetz-Modell: Schüler konstruieren ein Nahrungsnetz mit Wirbellosen und diskutieren, was passiert, wenn eine Art ausfällt."},{"rang":3,"favorit":false,"methode":"Recherche","beschreibung":"Aktueller Bezug: Bienensterben – Schüler recherchieren und bewerten die Folgen für Ökosysteme und Landwirtschaft."}],"bezug_zum_lehrplan_kontext":"Verbindung zu Umweltbildung und Naturschutz (GY-78-WIR-WTG-7); Anknüpfung an Ökologie aus Klasse 5/6","moegliche_fehlvorstellungen":"Schüler könnten denken, Pflanzen ''wollen'' bestäubt werden oder Insekten ''wollen'' helfen – teleologische Deutungen müssen korrigiert werden. Außerdem sollte betont werden, dass Koevolution immer beide Partner betrifft.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum sehen manche Blüten genau so aus, dass nur bestimmte Insekten sie bestäuben können – und warum haben diese Insekten genau die Sinnesorgane und Mundwerkzeuge, die dazu passen? War das ein Zufall?'' Einstieg in das Konzept der Koevolution auf beiden Seiten – Pflanze und Insekt."},"basiskonzepte_sekundaer":["bk_evolutive_entwicklung"],"bk_prinzipien_taxonomie":[{"value":"Stoffkreislauf","taxonomyElementId":"df08b5ac-d37e-4767-8844-2bb4757a8233"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-HUM-ZUS-2"],"ermoeglichende_lernziele":["GY-78-WIR-WTG-7"],"voraussetzende_lernziele":["GY-78-WIR-WTG-5"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '25137dc5-0488-5d75-9f4c-a4e01ed1a1fb'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ATM-7","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-ATM-7","unterthema":"Atmungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung begründen: Rauchverbot","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"begründen","kurzbezeichnung":"Gesunderhaltung: Rauchverbot","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Tabakrauch enthält über 4000 chemische Verbindungen, darunter viele Karzinogene, auf die das menschliche Atmungssystem evolutionär nicht angepasst ist. Das Flimmerepithel der Atemwege ist evolutionär zur Partikelfiltration entstanden und wird durch Tabakrauch dauerhaft geschädigt. Nikotin wirkt auf das evolutionär entstandene nicotinische Acetylcholinrezeptorsystem – ähnlich wie andere Suchtmittel das Dopaminsystem nutzen. Das Rauchverbot ist eine gesellschaftliche Maßnahme, die einen evolutionären Mismatch durch regulatorische Intervention begrenzt.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Evolutionäres Mismatch","Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Das Rauchverbot betrifft eine gesellschaftliche Gesundheitsmaßnahme, nicht direkt die individuelle Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen (Flimmerepithel) werden hier nur am Rande berührt, stehen aber nicht im Zentrum der Begründung.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die Begründung des Rauchverbots nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Tabakrauch enthält zahlreiche Schadstoffe, die als Fremdstoffe in die Atemwege gelangen und dort dem natürlichen Stoffaustausch mit der Umwelt schaden – zentral für die Begründung dieses Lernziels: Neben Nikotin enthält Tabakrauch auch krebserregende Teerstoffe und Kohlenmonoxid, die die Sauerstoffaufnahme im Blut zusätzlich beeinträchtigen können. Ein Rauchverbot zu begründen stützt sich unmittelbar auf diese stofflichen Belastungen der Atemwege.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Begründung des Rauchverbots nicht der zentrale Aspekt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Digitale Medien","beschreibung":"Bildvergleich: Gesundes Lungengewebe vs. Raucherlunge (histologische Präparate oder Fotos) – visuelle Konfrontation mit Schadensbild."},{"rang":2,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Wirkungsmechanismus Nikotin: Schüler erarbeiten, wie Nikotin auf Acetylcholinrezeptoren wirkt und Sucht erzeugt – Vergleich mit GY-78-HUM-NER-12."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Warum ist Rauchen nicht nur eine individuelle Entscheidung, sondern ein gesellschaftliches Problem?'' – Verbindung von Biologie und Sozialpolitik."}],"bezug_zum_lehrplan_kontext":"Verbindung zu HUM-NER-12 (Suchtmittel); anwendungsorientiertes Integrationslernziel mit starker Gesundheitserziehungskomponente","moegliche_fehlvorstellungen":"Schüler könnten denken, der Körper ''gewöhnt sich ans Rauchen''; die irreversiblen Schäden am Flimmerepithel und Lungengewebe müssen klar kommuniziert werden.","evolutionsdidaktischer_impuls":"Impuls: ''Unser Körper hat keine evolutionäre Abwehr gegen Tabakrauch – warum nicht? Was sagt uns das über die Grenzen evolutionärer Anpassung?'' Evolutionäres Mismatch als Erklärung für die Schädlichkeit des Rauchens."},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-ATM-4"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'b336a6b6-3968-557e-9b4d-176206518007'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-WIR-INS-7","thema":"Wirbellose in ihren Lebensräumen","anmerkung":"Brücke zu menschlicher Entwicklung in Klasse 8","_source_id":"GY-78-WIR-INS-7","unterthema":"Insekten","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"die Angepasstheit an ihre Lebensweise bzw. Lebensräume erläutern: Fortpflanzung und Entwicklung (Metamorphose)","bk_prinzipien":["Zelldifferenzierung","Reproduktion"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Insekten: Metamorphose","abstraktionsgrad":"mittel","ist_konzeptanker":true,"basiskonzeptbezug":[{"begruendung":"Die Metamorphose ist eine der bedeutendsten evolutionären Innovationen der Insekten. Die vollständige Metamorphose (Holometabola) ermöglicht eine vollständige ökologische Trennung von Larven- und Adultstadium: Larven und Imagines konkurrieren nicht um dieselben Ressourcen, da sie in unterschiedlichen Lebensräumen leben und unterschiedliche Nahrung aufnehmen. Diese ökologische Entkopplung wird als eine der Hauptursachen für die außerordentliche evolutionäre Diversität der holometabolen Insekten (ca. 85% aller Insektenarten) angesehen. Das Puppenstadium der Holometabola ist eine evolutionäre Neuerung, die eine vollständige Reorganisation des Körpers ermöglicht. Die extreme Körperumgestaltung in der Puppe ist ein beeindruckendes Beispiel für phänotypische Plastizität innerhalb eines Individuums, gesteuert durch das Hormonsystem und in den Genen verankert. Die Evolutionäre Entwicklungsbiologie (Evo-Devo) untersucht, wie Hox-Gene und andere Regulatoren diese drastischen Entwicklungsänderungen steuern.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Artbildung und adaptive Radiation","Lebensgeschichte / Life-History-Theorie","Anpassung und Angepasstheit","Evolutionäre Entwicklungsbiologie (Evo-Devo)","Phänotypische Plastizität"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Artbildung und adaptive Radiation","taxonomyElementId":"32b4337f-19eb-4860-99a1-fb1e4d73c731"},{"value":"Lebensgeschichte / Life-History-Theorie","taxonomyElementId":"c6d1f463-8049-4f4b-b430-1c8ae90c07c6"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Evolutionäre Entwicklungsbiologie (Evo-Devo)","taxonomyElementId":"620df2d4-8482-4070-8308-befe4758beef"},{"value":"Phänotypische Plastizität","taxonomyElementId":"f24a74bb-ac84-4f12-8645-694213b6239b"}]},{"begruendung":"Die Metamorphose ist das Paradebeispiel für individuelle Entwicklung durch tiefgreifende Zelldifferenzierung und Körperumbau: Larve und erwachsenes Insekt unterscheiden sich trotz identischen Genoms fundamental in Gestalt, Lebensraum und Ernährungsweise. Bei der vollständigen Metamorphose wird dieser Umbau im Puppenstadium durch weitgehende Auflösung und Neubildung von Gewebe realisiert, bei der unvollständigen Metamorphose erfolgt er schrittweise über mehrere Häutungen hinweg. Damit verbindet dieses Lernziel exemplarisch, wie ein und dasselbe Genom über die Zeit hinweg sehr unterschiedliche Körperformen hervorbringen kann.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_individuelle_entwicklung__zelldifferenzierung"],"relevante_unterkonzepte":["Metamorphose (vollständige/unvollständige Verwandlung)","Zelldifferenzierung"],"relevante_unterkonzepte_taxonomie":[{"value":"Metamorphose (vollständige/unvollständige Verwandlung)","taxonomyElementId":"99c41e90-ca7d-41d4-a0e4-18d3cf5f4752"},{"value":"Zelldifferenzierung","taxonomyElementId":"77e0949b-32a4-4392-9b4b-f753ce14a851"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Larve und Imago zeigen völlig unterschiedliche Struktur-Funktions-Ausprägungen desselben Genoms: Während die Larve meist auf Wachstum und Nahrungsaufnahme spezialisiert ist, dient der Körperbau des erwachsenen Insekts vor allem der Fortpflanzung und Verbreitung. Diese radikale strukturelle Umgestaltung während der Metamorphose zeigt, wie flexibel ein einziger genetischer Bauplan unterschiedliche Funktionsstrukturen hervorbringen kann.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der hormonell gesteuerte Ablauf der Metamorphose, etwa durch Häutungs- und Juvenilhormon, ist ein Beispiel für biologische Steuerung von Entwicklungsschritten nach einem genetisch festgelegten Programm. Sinkt der Juvenilhormonspiegel unter einen bestimmten Wert, setzt die Verpuppung ein, ohne dass eine Rückmeldung über den tatsächlichen Entwicklungserfolg diesen Ablauf noch verändern könnte.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Vorprogrammierte/genetisch determinierte Steuerungsprozesse"],"relevante_unterkonzepte_taxonomie":[{"value":"Vorprogrammierte/genetisch determinierte Steuerungsprozesse","taxonomyElementId":"54e8f1fd-a167-4791-9d4d-900ea9dd05b6"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoffumwandlung ist für die Metamorphose als Entwicklungsprozess nicht der zentrale Aspekt.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation steht bei der Metamorphose nicht im Vordergrund gegenüber der hormonellen Steuerung.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q1","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_individuelle_entwicklung__zelldifferenzierung","basiskonzepte_primaer":["bk_individuelle_entwicklung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Organ","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Lebenszyklus-Poster: Schüler erstellen Poster zum Lebenszyklus eines holometabolen Insekts und eines hemimetabolen und vergleichen. Diskussion: Was ist der evolutionäre Vorteil der vollständigen Metamorphose?"},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Analyse: ''Wo lebt die Larve, wo das Imago?'' am Beispiel Mücke (Larve im Wasser, Imago in der Luft) – ökologische Trennung herausarbeiten und als Life-History-Strategie interpretieren."},{"rang":3,"favorit":false,"methode":"Digitale Medien","beschreibung":"Zeitrafferfilm: Verwandlung einer Raupe zum Schmetterling – Diskussion: Wie kann aus einer Raupe ein Schmetterling werden? Was steuert diese Entwicklung (Hormonsystem, Gene)?"}],"bezug_zum_lehrplan_kontext":"Direkte Verbindung zu GY-78-WIR-INS-8 (Insektengruppen anhand Flügelausbildung) und evolutionärer Diversität","moegliche_fehlvorstellungen":"Schüler könnten die Puppe für ''inaktiv'' halten; der aktive Umbau des Körpers (Histolyse und Histogenese) sollte zumindest erwähnt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum ist es ein Vorteil, wenn Larve und Imago völlig unterschiedlich aussehen und an verschiedenen Orten leben? Und wie ist es möglich, dass dasselbe genetische Programm zwei so verschiedene Körper hervorbringt?'' Führt zur Erkenntnis des evolutionären Vorteils der ökologischen Entkopplung und zum Konzept der phänotypischen Plastizität."},"basiskonzepte_sekundaer":["bk_steuerung_regelung"],"bk_prinzipien_taxonomie":[{"value":"Zelldifferenzierung","taxonomyElementId":"ba40119c-d226-463a-9d10-192d395801b8"},{"value":"Reproduktion","taxonomyElementId":"ceaee223-7f05-4ca2-ada6-7223c25ba731"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-HUM-FES-4"],"ermoeglichende_lernziele":["GY-78-HUM-FES-2"],"konzeptanker_begruendung":"Phänomenologisch stärkster Einstieg in Ind/Evo – Individuell; dramatische Entwicklung sichtbar","voraussetzende_lernziele":["GY-78-WIR-INS-2"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '43d146a6-7021-5a2d-912f-efc3dd9a433a'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-ZEL-PTZ-5","thema":"Zellen als Lebensbausteine","anmerkung":"Verbindet Merkmale des Lebens mit Zellbiologie","_source_id":"GY-78-ZEL-PTZ-5","unterthema":"Pflanzliche und tierische Zellen","_source_file":"lernziele_gy78.json","alltagsnaehe":"niedrig","originaltext":"am Beispiel eines Einzellers erläutern, dass eine Zelle alle Merkmale des Lebens erfüllen kann","bk_prinzipien":["Reproduktion"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Einzeller erfüllt Merkmale des Lebens","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Einzeller (Protisten) sind die evolutionär ursprünglichste Form des eukaryotischen Lebens und demonstrieren, dass das Leben in seiner vollständigsten Form in einer einzigen Zelle realisiert werden kann. Einzeller wie Paramecium oder Amoeba zeigen alle Merkmale des Lebens in einer Zelle integriert. Die Diversität der Einzeller ist enorm und stellt das evolutionäre Grundrauschen dar, aus dem mehrzellige Organismen entstanden sind. Das Studium von Einzellern ist fundamental für das Verständnis der Übergänge zwischen Prokaryoten, einfachen Eukaryoten und Vielzellern. Einzeller sind keine ''unvollständigen'' Lebewesen, sondern evolutionär hocherfolgreiche Organismen, die seit über einer Milliarde Jahren alle Lebensräume der Erde besiedeln.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Evolution von Einzellern zu Vielzellern","gemeinsame Abstammung/Verwandtschaft","Tiefenzeit","Artbildung und adaptive Radiation"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolution von Einzellern zu Vielzellern","taxonomyElementId":"e5b7c6e1-e650-4053-9b80-767aaf023d6f"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"},{"value":"Tiefenzeit","taxonomyElementId":"733b2bfc-8d20-4d6f-b875-f97958cfbab7"},{"value":"Artbildung und adaptive Radiation","taxonomyElementId":"32b4337f-19eb-4860-99a1-fb1e4d73c731"}]},{"begruendung":"Dass eine einzelne Zelle Wachstum, Fortpflanzung und alle weiteren Lebensmerkmale eigenständig realisiert, ist der Kern dieses Lernziels zur individuellen Entwicklung. Am Beispiel eines Einzellers wird besonders deutlich, dass Individualentwicklung nicht zwingend Vielzelligkeit voraussetzt: Eine einzige Zelle wächst, reagiert auf Reize, betreibt Stoffwechsel und pflanzt sich durch Zellteilung fort, und durchläuft damit im Kleinen denselben grundlegenden Entwicklungszyklus wie ein komplexer vielzelliger Organismus, nur ohne die dafür sonst nötige Arbeitsteilung zwischen spezialisierten Zellen.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_individuelle_entwicklung__zelldifferenzierung"],"relevante_unterkonzepte":["Wachstum","Reproduktion"],"relevante_unterkonzepte_taxonomie":[{"value":"Wachstum","taxonomyElementId":"cdbe94e3-b8d8-4ad9-843f-58ad11a56faf"},{"value":"Reproduktion","taxonomyElementId":"d1597cd6-5648-49bc-9ad2-9f27f9f43bc5"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Zellaufbau des Einzellers steht hier nicht im Vordergrund, sondern die Erfüllung aller Lebensmerkmale.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse einzelner Organellen werden am Beispiel des Einzellers nicht vertieft behandelt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Stoffwechsel als eines der von einer einzelnen Zelle erfüllten Lebensmerkmale ist hier mitgedacht: Dass bereits ein Einzeller Stoffe aufnimmt, umwandelt und wieder abgibt, zeigt, dass Stoffwechsel keine Eigenschaft ist, die erst komplexe, vielzellige Organismen benötigen. Das Erläutern der Lebensmerkmale am Beispiel eines Einzellers schließt diesen stofflichen Aspekt mit ein.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffumwandlung"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffumwandlung","taxonomyElementId":"0d4c7b1d-0a19-483e-82fc-e5c1cc3a863d"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für den Nachweis der Lebensmerkmale am Einzeller nicht zentral.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q2","systemebene_primaer":"Zelle","teilkonzept_primaer":"bk_individuelle_entwicklung__zelldifferenzierung","basiskonzepte_primaer":["bk_individuelle_entwicklung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Mikroskopie lebender Einzeller (z. B. Paramecium aus Heupilzinfus): Schüler beobachten alle Lebensmerkmale direkt."},{"rang":2,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich: Einzeller vs. Körperzelle – Was kann der Einzeller, was die Körperzelle nicht kann (und umgekehrt)?"},{"rang":3,"favorit":false,"methode":"Digitale Medien","beschreibung":"Zeitlupenfilm: Paramecium bei der Nahrungsaufnahme – Diskussion aller Lebensmerkmale."}],"bezug_zum_lehrplan_kontext":"Vorbereitung auf ZEL-PTZ-7 (Entstehung der Vielzelligkeit); Verbindung zu ZEL-PTZ-1 (Merkmale des Lebens)","moegliche_fehlvorstellungen":"Schüler könnten Einzeller als ''unvollständig'' betrachten; ihre evolutionäre Vollständigkeit und Angepasstheit muss betont werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Was ist das kleinste, einfachste Lebewesen, das du dir vorstellen kannst? Könnte eine einzige Zelle wirklich ein vollständiges Lebewesen sein?'' Einführung in das evolutionäre Konzept minimaler Lebenskomplexität und die evolutionäre Vollständigkeit von Einzellern."},"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung"],"bk_prinzipien_taxonomie":[{"value":"Reproduktion","taxonomyElementId":"ceaee223-7f05-4ca2-ada6-7223c25ba731"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-ZEL-PTZ-7"],"voraussetzende_lernziele":["GY-78-ZEL-PTZ-1","GY-78-ZEL-PTZ-2"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '8952ba0c-8240-5f35-a306-fb0d7ec25880'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-ZEL-PTZ-7","thema":"Zellen als Lebensbausteine","anmerkung":"Evolutive Dimension der Zellbiologie","_source_id":"GY-78-ZEL-PTZ-7","unterthema":"Pflanzliche und tierische Zellen","_source_file":"lernziele_gy78.json","alltagsnaehe":"niedrig","originaltext":"die Entwicklung von Einzellern zu Vielzellern am Beispiel der Grünalgen erläutern","bk_prinzipien":["Zelldifferenzierung","Selektion"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Einzeller zu Vielzeller: Grünalgen","abstraktionsgrad":"hoch","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Der Übergang von Einzellern zu Vielzellern ist eines der bedeutendsten Ereignisse in der Evolutionsgeschichte des Lebens. Grünalgen (Chlorophyta) bieten eine ideale Modellgruppe, da sie eine kontinuierliche Reihe von Organisationsformen zeigen: Einzeller (Chlamydomonas), Kolonien (Gonium, Pandorina), einfache Vielzeller (Volvox). Diese Reihe illustriert, wie Vielzelligkeit durch schrittweise Selektion auf Kooperation zwischen Zellen entstand. Volvox zeigt bereits eine Prototyp-Arbeitsteilung zwischen somatischen Zellen und Keimzellen – ein Vorläufer der Differenzierung in Körper- und Keimbahnzellen bei Tieren.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_evolutive_entwicklung__stammesgeschichte"],"relevante_evolutionskonzepte":["Evolution von Einzellern zu Vielzellern","Evolution von Kooperation/Altruismus","Natürliche Selektion und Selektionsdruck","Tiefenzeit"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolution von Einzellern zu Vielzellern","taxonomyElementId":"e5b7c6e1-e650-4053-9b80-767aaf023d6f"},{"value":"Evolution von Kooperation/Altruismus","taxonomyElementId":"856558c3-d1da-4c45-aa40-f757e2dd3c0a"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Tiefenzeit","taxonomyElementId":"733b2bfc-8d20-4d6f-b875-f97958cfbab7"}]},{"begruendung":"Der Übergang wird stammesgeschichtlich, nicht als individuelle Ontogenese eines einzelnen Organismus behandelt.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Reihe Chlamydomonas–Gonium–Volvox zeigt strukturell, wie sich zelluläre Organisation schrittweise zu echter Vielzelligkeit entwickelt: Vom eigenständigen Einzeller über lose Zellkolonien bis zur arbeitsteiligen Kugelkolonie mit spezialisierten Zelltypen wird eine zunehmende strukturelle Kompartimentierung auf Organisationsebene sichtbar. Dieser Vergleich veranschaulicht anschaulich, wie sich aus einfacher zellulärer Struktur höhere Organisationsformen entwickeln können.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_struktur_funktion__struktur"],"relevante_unterkonzepte":["Gewebe- und Organebene der Kompartimentierung"],"relevante_unterkonzepte_taxonomie":[{"value":"Gewebe- und Organebene der Kompartimentierung","taxonomyElementId":"08929832-d41e-4cd4-9657-dc97ca8d3815"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse zwischen Zellen sind bei diesem Übergang nicht der zentrale Betrachtungsaspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoffumwandlung ist für den Übergang zur Vielzelligkeit an diesem Beispiel nicht das zentrale Thema.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Arbeitsteilung zwischen somatischen Zellen und Keimzellen beim kolonialen Grünalgen Volvox setzt Zell-Zell-Kommunikation voraus: Nur wenn benachbarte Zellen Signale austauschen können, lässt sich koordinieren, welche Zellen sich auf vegetative Funktionen und welche sich auf die Fortpflanzung spezialisieren. Dieser frühe Schritt zellulärer Arbeitsteilung zeigt, dass innerorganismische Kommunikation bereits bei einfachen Übergangsformen zur Vielzelligkeit notwendig wird.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_information_kommunikation__kommunikation"],"relevante_unterkonzepte":["Kommunikation innerhalb eines Organismus"],"relevante_unterkonzepte_taxonomie":[{"value":"Kommunikation innerhalb eines Organismus","taxonomyElementId":"73061b7b-8e48-486c-9410-4d9ebed74ab5"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q2","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_evolutive_entwicklung__stammesgeschichte","basiskonzepte_primaer":["bk_evolutive_entwicklung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Zelle","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Mikroskopie: Volvox unter dem Mikroskop beobachten – Tochterkugeln, somatische Zellen und Keimzellen identifizieren."},{"rang":2,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Bilderserie: Chlamydomonas → Gonium → Pandorina → Volvox – Schüler beschreiben die schrittweise Zunahme der Zellzahl und Differenzierung."},{"rang":3,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Analogie: Vielzelligkeit wie eine Gemeinschaft – Warum ist Zusammenarbeit evolutionär vorteilhaft? Vergleich mit arbeitsteiligen menschlichen Gesellschaften."}],"bezug_zum_lehrplan_kontext":"Höchste Evolutionsrelevanz im Zellenthema; direkte Verbindung zur Stammesgeschichte der Pflanzen und Tiere in höheren Klassenstufen","moegliche_fehlvorstellungen":"Schüler könnten denken, Vielzelligkeit entstand ''auf einmal''; die Kontinuität der Übergänge am Beispiel der Grünalgen muss herausgearbeitet werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum ist ein Vielzeller besser als ein Einzeller? Was gewinnt man – und was verliert man?'' Diskussion über evolutionäre Vor- und Nachteile der Vielzelligkeit."},"basiskonzepte_sekundaer":["bk_struktur_funktion"],"bk_prinzipien_taxonomie":[{"value":"Zelldifferenzierung","taxonomyElementId":"ba40119c-d226-463a-9d10-192d395801b8"},{"value":"Selektion","taxonomyElementId":"151dc9fd-9307-465a-9171-2163f889fd5e"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-ZEL-PTZ-5"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '32e8f1bd-38ac-5418-bc7c-e068d0befa17'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-BHK-4","thema":"Biologie des Menschen","anmerkung":"Schlüssel-Schloss-Prinzip auf Antigen-Antikörper vorbereiten","_source_id":"GY-78-HUM-BHK-4","unterthema":"Blut und Herz-Kreislauf-System","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"die Klassifikation der Blutgruppen nach dem AB0- und Rhesus-System erläutern und deren Bedeutung z. B. für Bluttransfusionen ableiten","bk_prinzipien":["Schlüssel-Schloss-Prinzip"],"ist_praktisch":false,"kognitionsverb":"erläutern_ableiten","kurzbezeichnung":"Blutgruppen erläutern","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das AB0-Blutgruppensystem ist ein eindrückliches Beispiel für balancierende Selektion: Alle drei Allele (A, B, 0) werden in menschlichen Populationen weltweit beibehalten, weil verschiedene Blutgruppen unterschiedliche Vor- und Nachteile gegenüber verschiedenen Pathogenen bieten. Blutgruppe 0 scheint Schutz gegen schwere Malaria zu bieten. Das AB0-System existiert auch bei anderen Primaten, was auf eine evolutionäre Entstehung vor der Trennung der Menschenaffen hindeutet. Die Blutgruppen sind ein klassisches Lehrbeispiel für Polymorphismus als Ergebnis balancierter Selektion. Die Evolutionsgeschichte des ABO-Merkmals lässt sich im Stammbaum der Primaten veranschaulichen.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["balancierende Selektion","genetische Variation","Koevolution","gemeinsame Abstammung/Verwandtschaft"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"balancierende Selektion","taxonomyElementId":"fd96c34a-abc5-42d3-b804-e547bed55f48"},{"value":"genetische Variation","taxonomyElementId":"31375847-cad0-4b61-9b67-74e68ea8c520"},{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"}]},{"begruendung":"Blutgruppen sind genetisch fixierte Merkmale ohne Bezug zur individuellen Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Antigene auf der Oberfläche roter Blutkörperchen und die zu ihnen passenden Antikörper folgen dem Schlüssel-Schloss-Prinzip: Nur wenn die räumliche Struktur eines Antikörpers exakt zu einem bestimmten Antigen passt, kommt es zur Erkennungsreaktion, die bei unpassenden Blutgruppen eine gefährliche Verklumpung auslösen kann. Die Klassifikation der Blutgruppen nach AB0- und Rhesus-System und ihre Bedeutung für Bluttransfusionen abzuleiten setzt ein Verständnis dieser strukturellen Passung voraus.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Rezeptor-Ligand-Spezifität"],"relevante_unterkonzepte_taxonomie":[{"value":"Rezeptor-Ligand-Spezifität","taxonomyElementId":"a0ce4bf5-4332-4464-a1e2-3d27383c812e"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die Klassifikation der Blutgruppen nicht relevant.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für die Blutgruppenklassifikation nicht relevant.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Antigen-Antikörper-Erkennung nach dem Schlüssel-Schloss-Prinzip ist ein direktes Beispiel für Informationscodierung auf Zelloberflächen: Die Antigene der roten Blutkörperchen fungieren dabei als eine Art molekulares Erkennungsmerkmal, das vom Immunsystem gelesen und bei Unverträglichkeit mit passenden Antikörpern beantwortet wird. Die Klassifikation der Blutgruppen nach AB0- und Rhesus-System macht dieses Prinzip der rezeptorvermittelten Erkennung an einem für Bluttransfusionen praktisch bedeutsamen Beispiel greifbar.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_information_kommunikation__information"],"relevante_unterkonzepte":["Rezeptor-vermittelte Signalübertragung"],"relevante_unterkonzepte_taxonomie":[{"value":"Rezeptor-vermittelte Signalübertragung","taxonomyElementId":"2ec2b640-40c1-4d05-b65b-8892ce31ec99"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Molekül","teilkonzept_primaer":"bk_information_kommunikation__information","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Zelle","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Erbgangsaufgaben: Schüler berechnen die Blutgruppe von Kindern aus Elternblutgruppen – Grundlagen der Genetik verknüpfen."},{"rang":2,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Warum gibt es mehrere Blutgruppen beim Menschen? Warum hat die Evolution nicht eine beste Blutgruppe ausgewählt?'' – Einführung in balancierte Selektion."},{"rang":3,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Recherche und Stammbaum: ''Blutgruppe 0 schützt vor Malaria – wie haben Wissenschaftler das herausgefunden? Was bedeutet das für die Verteilung von Blutgruppen in Malariagebieten?'' Ergänzend: Stammbaum des ABO-Merkmals in der Primatenlinie als Veranschaulichung der evolutionären Geschichte."}],"bezug_zum_lehrplan_kontext":"Einer der stärksten direkten Evolutionsbezüge im gesamten Lehrplan; ideale Brücke zu Genetik und Evolutionsbiologie in höheren Klassen","moegliche_fehlvorstellungen":"Schüler könnten Blutgruppen als rein medizinische Kategorie ohne evolutionäre Bedeutung sehen; die evolutionäre Erklärung des Polymorphismus ist faszinierend und motivierend.","evolutionsdidaktischer_impuls":"Leitfrage: ''Wenn Blutgruppe 0 vor Malaria schützt – warum haben dann nicht alle Menschen Blutgruppe 0? Was hält die anderen Blutgruppen in der Population?'' Perfekte Einführung in das Konzept der balancierten Selektion."},"basiskonzepte_sekundaer":["bk_struktur_funktion"],"bk_prinzipien_taxonomie":[{"value":"Schlüssel-Schloss-Prinzip","taxonomyElementId":"4119f064-4a78-4bfe-a731-850a4debddf4"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-HUM-ABW-5"],"voraussetzende_lernziele":["GY-78-HUM-BHK-3"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '6bf34452-2a8d-51d9-9e6a-2e607073f68b'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-AUS-3","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-AUS-3","unterthema":"Ausscheidungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"mittel","originaltext":"die Bedeutung der Niere als Ausscheidungsorgan erläutern: Ableiten des Harns über Harnleiter, Harnblase, Harnröhre","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Harnableitung beschreiben","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Der Ableitungsweg des Harns zeigt bei Säugetieren, Reptilien und Vögeln Homologien, die auf gemeinsame Vorfahren hinweisen. Die Harnblase ist nicht bei allen Tetrapoden vorhanden: Vögel besitzen keine Harnblase, weil sie Harnsäure als festen Stoff ausscheiden und das Gewicht für den Flug minimieren müssen – ein Beispiel für die funktionelle Reduktion eines Organs als evolutionäre Anpassung. Der anatomische Verlauf des Harnleiters beim Mann ist ein klassisches Beispiel für evolutionäre Pfadabhängigkeit (''suboptimales Design'' durch historische Restriktionen).","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Homologie und Analogie/Konvergente und divergente Evolution","Anpassung und Angepasstheit","gemeinsame Abstammung/Verwandtschaft"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Homologie und Analogie/Konvergente und divergente Evolution","taxonomyElementId":"492006a1-28b5-4418-90ff-a167424785fc"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"}]},{"begruendung":"Die Harnableitung wird strukturell beschrieben, nicht als individueller Entwicklungsprozess.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Harnleiter, Harnblase und Harnröhre sind die strukturellen Stationen des Ableitungswegs und damit der Kern dieses Lernziels: Jedes dieser Organe übernimmt eine eigene, räumlich abgegrenzte Teilfunktion, vom Transport des Harns aus der Niere über seine zeitweilige Speicherung bis zu seiner endgültigen Ausleitung. Diese organisierte Abfolge strukturell getrennter Stationen zeigt exemplarisch, wie ein komplexer Vorgang auf mehrere spezialisierte Organe verteilt werden kann.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_struktur_funktion__struktur"],"relevante_unterkonzepte":["Gewebe- und Organebene der Kompartimentierung"],"relevante_unterkonzepte_taxonomie":[{"value":"Gewebe- und Organebene der Kompartimentierung","taxonomyElementId":"08929832-d41e-4cd4-9657-dc97ca8d3815"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die rein anatomische Ableitung des Harns nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoffumwandlung findet bereits in der Niere statt; die Ableitung selbst ist ein rein struktureller Transportweg.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Harnableitung nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q4","systemebene_primaer":"Organ","teilkonzept_primaer":"bk_struktur_funktion__struktur","basiskonzepte_primaer":["bk_struktur_funktion"],"kognitive_anforderung":"reproduktion_und_verstaendnis","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Schaubild: Weg des Harns von der Niere nach außen – Schüler beschriften und verstehen die Funktion jedes Abschnitts."},{"rang":2,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich: Harnsystem bei Säugetier vs. Vogel – warum fehlt Vögeln die Harnblase?"},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Gibt es suboptimales Design in der Natur? Ist der anatomische Verlauf des Harnleiters ein Beispiel dafür?'' – Einführung in evolutionäre Pfadabhängigkeit."}],"bezug_zum_lehrplan_kontext":"Abschluss des Ausscheidungssystem-Themas; Verbindung zu HUM-ZUS (Systemzusammenwirken)","moegliche_fehlvorstellungen":"Schüler könnten anatomische Strukturen als unveränderlich betrachten; die evolutionäre Reduktion von Organen muss als normales evolutionäres Phänomen dargestellt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Vögel haben keine Harnblase – wäre das für Menschen ein Vorteil oder Nachteil? Warum hat die Evolution für Vögel diese Lösung gewählt?'' Evolutionäre Anpassung durch Organreduktion."},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-AUS-2"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'd0316ecd-9064-5bfd-a8ae-7d48a98141f0'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-NER-2","thema":"Biologie des Menschen","anmerkung":"Str/Fkt und Info/Komm gemeinsam anwenden","_source_id":"GY-78-HUM-NER-2","unterthema":"Nervensystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"Bau und Funktion eines Sinnesorgans (Auge oder Ohr) erläutern","bk_prinzipien":["Schlüssel-Schloss-Prinzip","Signaltransduktion"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Sinnesorgan Bau und Funktion","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das Auge ist eines der bedeutendsten Beispiele für evolutionäre Komplexifizierung. Die moderne Evolutionsbiologie hat gezeigt, dass das Wirbeltierauge aus einfachsten lichtempfindlichen Zellen in einer kontinuierlichen Reihe von Zwischenstufen entstanden sein kann. Das Tintenfischauge und das Wirbeltierauge sind ein klassisches Beispiel für konvergente Evolution: Obwohl strukturell ähnlich, sind sie nicht homolog. Das Ohr ist ebenfalls evolutionär bedeutsam: Die Gehörknöchelchen der Säugetiere sind evolutionäre Abkömmlinge von Kieferknochen früherer Wirbeltiere – ein eindrückliches Beispiel für Exaptation, bei der eine Struktur evolutionär umfunktioniert wurde.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Homologie und Analogie/Konvergente und divergente Evolution","Exaptation (Umfunktionieren von Merkmalen)","Natürliche Selektion und Selektionsdruck","Übergangsformen/Entwicklungslinien"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Homologie und Analogie/Konvergente und divergente Evolution","taxonomyElementId":"492006a1-28b5-4418-90ff-a167424785fc"},{"value":"Exaptation (Umfunktionieren von Merkmalen)","taxonomyElementId":"2c3d2273-be42-4e8e-bc27-a8f1a8b94339"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Übergangsformen/Entwicklungslinien","taxonomyElementId":"70d40366-e362-4d6e-b2c2-a471dd235fdd"}]},{"begruendung":"Bau und Funktion von Auge oder Ohr werden strukturell erklärt, nicht als individueller Entwicklungsprozess.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Zusammenhang zwischen Bau, etwa der Linse des Auges oder dem Trommelfell des Ohrs, und der jeweiligen Funktion des Sinnesorgans ist Kern dieses Lernziels: Jede Struktur des Sinnesorgans lässt sich direkt auf ihre Rolle bei der Aufnahme und ersten Verarbeitung des jeweiligen Reizes zurückführen. Bau und Funktion eines Sinnesorgans zu erläutern ist damit ein besonders vollständiges Beispiel für das Struktur-Funktions-Prinzip dieses Basiskonzepts.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für Bau und Funktion des Sinnesorgans selbst nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für Bau und Funktion von Auge oder Ohr nicht relevant.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Auge und Ohr sind die ersten Stationen der Informationsaufnahme in der Reiz-Reaktions-Kette: Beide Organe wandeln physikalische Reize wie Licht oder Schallwellen mithilfe spezialisierter Sinneszellen in elektrische Signale um, die anschließend an das Nervensystem weitergeleitet werden können. Bau und Funktion dieser Organe zu verstehen ist damit die Voraussetzung für das Verständnis der gesamten nachfolgenden Reizverarbeitung.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_information_kommunikation__information"],"relevante_unterkonzepte":["Sinnesorgane und Rezeptortypen"],"relevante_unterkonzepte_taxonomie":[{"value":"Sinnesorgane und Rezeptortypen","taxonomyElementId":"8b649947-e0db-469f-bd86-0e451fea77c2"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q2","systemebene_primaer":"Organ","teilkonzept_primaer":"bk_struktur_funktion__funktion","basiskonzepte_primaer":["bk_struktur_funktion"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Zelle","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Bildserie: Evolution des Auges von Pigmentfleck bis zum Linsenauge – schrittweise Komplexifizierung nachvollziehen."},{"rang":2,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich Tintenfischauge vs. menschliches Auge: Was ist gleich, was ist anders? Konvergente Evolution erkennen."}],"bezug_zum_lehrplan_kontext":"Einer der stärksten Evolutionsbezüge im Nervensystem-Thema; Verbindung zur Widerlegung von Intelligent-Design-Argumenten","moegliche_fehlvorstellungen":"Schüler könnten das Auge als ''zu komplex'' für Evolution halten; die schrittweise Entstehung durch dokumentierte Zwischenstufen muss überzeugend dargestellt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Könnte das Auge wirklich durch schrittweise Selektion entstanden sein? Welche Zwischenstufen würden wir erwarten? Und wie kamen die Gehörknöchelchen zu ihrer heutigen Funktion – sie waren ursprünglich Kieferknochen!'' Direkte Auseinandersetzung mit zentralen evolutionsbiologischen Argumenten und dem Konzept der Exaptation."},"basiskonzepte_sekundaer":["bk_information_kommunikation"],"bk_prinzipien_taxonomie":[{"value":"Schlüssel-Schloss-Prinzip","taxonomyElementId":"4119f064-4a78-4bfe-a731-850a4debddf4"},{"value":"Signaltransduktion","taxonomyElementId":"599e5fa0-ac5f-4866-9fdb-69c99396b426"}],"empfohlene_klassenstufe":"8","interleaving_empfehlung":["GY-78-HUM-NER-9"],"ermoeglichende_lernziele":["GY-78-HUM-NER-3"],"voraussetzende_lernziele":["GY-78-HUM-NER-1","GY-78-ZEL-PTZ-2"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":2}'::jsonb WHERE id = 'db4c5966-f12f-5f6f-91ff-bb444357f2ac'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ABW-7","thema":"Biologie des Menschen","anmerkung":"Integrationslernziel Gesundheitsbildung","_source_id":"GY-78-HUM-ABW-7","unterthema":"Abwehrsystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Prävention von Infektionskrankheiten begründen (z. B. Hygiene, Impfungen)","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"begründen","kurzbezeichnung":"Infektionskrankheiten: Prävention begründen","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Präventionsmaßnahmen gegen Infektionskrankheiten können als menschliche Interventionen in den evolutionären Rüstungswettlauf zwischen Pathogenen und Wirten verstanden werden. Impfungen unterbrechen die Übertragungskette und können bei ausreichender Durchimpfungsrate (Herdenimmunität) Pathogene aus Populationen eliminieren (wie bei den Pocken geschehen). Hygienemaßnahmen verändern den Selektionsdruck auf Pathogene: Der Virulenz-Transmissibilitäts-Trade-off besagt, dass hoch virulente Erreger evolutionäre Nachteile gegenüber weniger virulenten Erregern haben, wenn die Übertragung eingeschränkt wird.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","Trade-offs/Zielkonflikte","Natürliche Selektion und Selektionsdruck","Aussterben"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Trade-offs/Zielkonflikte","taxonomyElementId":"c94a205b-9991-4899-8a68-a9dd12e48474"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Aussterben","taxonomyElementId":"cf369ee2-c943-4d3b-968b-707b015c3ddf"}]},{"begruendung":"Impfungen betreffen häufig die frühe individuelle Entwicklung, da die meisten Impfempfehlungen gezielt an bestimmte Phasen des Kindesalters geknüpft sind, in denen das Immunsystem noch heranreift. Die Begründung von Präventionsmaßnahmen berührt damit indirekt entwicklungsbiologische Aspekte, auch wenn der eigentliche Schwerpunkt des Lernziels auf der Immunabwehr liegt.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Wachstum"],"relevante_unterkonzepte_taxonomie":[{"value":"Wachstum","taxonomyElementId":"cdbe94e3-b8d8-4ad9-843f-58ad11a56faf"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Erreger sind für Präventionsmaßnahmen nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für Hygiene- und Impfmaßnahmen nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für die Prävention von Infektionskrankheiten nicht relevant.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Impfungen nutzen gezielt den Aufbau des immunologischen Gedächtnisses und sind damit ein Kernbeispiel für Informationsspeicherung im Immunsystem: Durch die kontrollierte Konfrontation mit abgeschwächten oder inaktivierten Erregerbestandteilen codiert das Immunsystem deren Merkmale in Gedächtniszellen, ohne dass die Krankheit selbst durchgemacht werden muss. Die Begründung von Präventionsmaßnahmen wie Hygiene und Impfungen stützt sich damit unmittelbar auf dieses Prinzip gespeicherter Information.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_information_kommunikation__information"],"relevante_unterkonzepte":["Codierung und Decodierung von Information"],"relevante_unterkonzepte_taxonomie":[{"value":"Codierung und Decodierung von Information","taxonomyElementId":"e3e511e0-2950-4026-a57e-442c206f75a7"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_information_kommunikation__information","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"analyse_und_bewertung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Simulationsmodell: Ausbreitung einer Infektionskrankheit bei verschiedenen Impfquoten – Herdenimmunität visualisieren."},{"rang":2,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Erfolgsgeschichte Pockenausrottung: Schüler recherchieren, wie Pocken durch Impfkampagnen ausgerottet wurden – evolutionäre Perspektive."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Wenn zu wenige Menschen geimpft sind, können Pathogene weiterleben und sich verändern – warum ist das aus evolutionärer Sicht gefährlich?''"}],"bezug_zum_lehrplan_kontext":"Synthese des gesamten Abwehrsystem-Themas; hochaktuelles gesellschaftliches Thema mit starkem Bezug zu Wissenschaftskommunikation","moegliche_fehlvorstellungen":"Schüler könnten Impfungen als ''unnötig'' betrachten, wenn Erkrankungen selten sind; das Konzept der Herdenimmunität und das evolutionäre Wiederaufflammen bei Impflücken muss erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Die Pocken wurden ausgerottet – das einzige Mal in der Geschichte, dass eine Tierart durch Menschenhand absichtlich ausgerottet wurde. War das richtig? Und was sagt uns das über die Macht von Impfungen im evolutionären Rüstungswettlauf?'' Hochmotivierende ethische und evolutionäre Diskussionsfrage."},"basiskonzepte_sekundaer":["bk_individuelle_entwicklung"],"empfohlene_klassenstufe":"8","interleaving_empfehlung":["GY-78-HUM-FES-7"],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-ABW-6"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'f69ce51b-e66d-53d4-bb7a-fed371d3428b'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ABW-6","thema":"Biologie des Menschen","anmerkung":"Aktive vs. passive Immunisierung: Gedächtnis vs. sofortige Antikörper","_source_id":"GY-78-HUM-ABW-6","unterthema":"Abwehrsystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Formen der Immunisierung (aktive und passive Immunisierung) erläutern","bk_prinzipien":["Codierung und Decodierung von Information"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Immunisierungsformen erläutern","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Aktive und passive Immunisierung nutzen das evolutionär entstandene Immungedächtnissystem des Menschen für präventive Zwecke. Die Geschichte der Impfung (Jenner, Pocken, Kuhpocken) zeigt, wie Menschen koevolutive Beziehungen zwischen Pathogenen und Wirten zur Immunisierung nutzten. mRNA-Impfstoffe (z. B. gegen SARS-CoV-2) sind das modernste Beispiel, wie molekularbiologisches Wissen über virale Genexpression für Immunisierungsstrategien genutzt werden kann.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Immunisierung ist eine präventive Maßnahme ohne Bezug zur individuellen Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Antikörper sind für die Formen der Immunisierung nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für aktive und passive Immunisierung nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für Immunisierungsformen nicht relevant.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Aktive Immunisierung nutzt gezielt den Aufbau des immunologischen Informationsgedächtnisses, indem der Körper durch einen abgeschwächten oder inaktivierten Erreger zur eigenen Antikörperproduktion und Gedächtniszellbildung angeregt wird, während passive Immunisierung stattdessen fertige Antikörper direkt zuführt, ohne dass eine eigene Informationsspeicherung erfolgt. Dieser Unterschied erklärt, warum aktive Immunisierung langfristig, passive dagegen nur kurzfristig wirksam ist.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_information_kommunikation__information"],"relevante_unterkonzepte":["Codierung und Decodierung von Information"],"relevante_unterkonzepte_taxonomie":[{"value":"Codierung und Decodierung von Information","taxonomyElementId":"e3e511e0-2950-4026-a57e-442c206f75a7"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_information_kommunikation__information","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Molekül","didaktische_strategien":{"top3_methoden":[{"rang":2,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Vergleichsaufgabe: Aktive vs. passive Immunisierung – Schüler stellen Unterschiede in Dauer, Aufwand und Schutzwirkung gegenüber."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Aktueller Bezug: mRNA-Impfstoffe gegen COVID-19 – wie funktionieren sie? Warum ist das ein evolutionsbiologisches Konzept?"}],"bezug_zum_lehrplan_kontext":"Grundlage für HUM-ABW-7 (Präventionsmaßnahmen); hochaktuelles und gesellschaftlich relevantes Thema","moegliche_fehlvorstellungen":"Schüler könnten aktive und passive Immunisierung verwechseln; die Unterschiede in Wirkdauer und Mechanismus müssen klar erarbeitet werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Edward Jenner nutzte 1796 eine koevolutive Beziehung zwischen Kuh und Mensch, um den ersten Impfstoff zu entwickeln – was hätte Darwin dazu gesagt?'' Verbindung von Wissenschaftsgeschichte, Koevolution und moderner Medizin."},"basiskonzepte_sekundaer":["bk_evolutive_entwicklung"],"bk_prinzipien_taxonomie":[{"value":"Codierung und Decodierung von Information","taxonomyElementId":"ef214769-1ffa-462e-bee3-b3000f803eb8"}],"empfohlene_klassenstufe":"8","interleaving_empfehlung":["GY-78-HUM-ABW-7"],"ermoeglichende_lernziele":["GY-78-HUM-ABW-7"],"voraussetzende_lernziele":["GY-78-HUM-ABW-5"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '9448b58a-78b5-50f2-9576-37c4da5c731d'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ABW-5","thema":"Biologie des Menschen","anmerkung":"Schlüssel-Schloss-Prinzip auf Antigen-Antikörper anwenden; Gedächtniszellen als Informationsspeicher","_source_id":"GY-78-HUM-ABW-5","unterthema":"Abwehrsystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"die Bedeutung weißer Blutzellen bei der körpereigenen Abwehr erläutern: Bildung von Antikörpern, spezifische Antigen-Antikörper-Reaktionen, Gedächtniszellen, Immunität","bk_prinzipien":["Schlüssel-Schloss-Prinzip","Codierung und Decodierung von Information"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Spezifische Abwehr und Gedächtniszellen","abstraktionsgrad":"hoch","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das adaptive Immunsystem mit seiner Antikörper-Produktion und Gedächtniszellbildung ist eine evolutionäre Innovation, die ausschließlich bei Kiefertieren vorkommt. Kieferlose Wirbeltiere wie Neunaugen haben ein funktionell analoges, aber strukturell verschiedenes System – konvergente Immunevolution. Die somatische Rekombination der Antikörpergene (V(D)J-Rekombination) ermöglicht die Erzeugung einer theoretisch unbegrenzten Diversität von Antikörpern aus einer begrenzten Anzahl von Gensegmenten – ein Mechanismus, der dem Prinzip genetischer Variation durch Rekombination ähnelt. Das immunologische Gedächtnis verkürzt die Reaktionszeit bei Zweitkontakt mit einem Pathogen und schützt somit vor wiederholter Erkrankung. Interessanterweise lässt sich die Selektion nützlicher Antikörper aus dem Repertoire aller möglichen Antikörper als Analogie zur natürlichen Selektion von Organismen verstehen: Varianten entstehen zufällig, nützliche werden selektiert und verstärkt.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","Homologie und Analogie/Konvergente und divergente Evolution","Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Homologie und Analogie/Konvergente und divergente Evolution","taxonomyElementId":"492006a1-28b5-4418-90ff-a167424785fc"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Die Bildung von Antikörpern und Gedächtniszellen ist ein immunologischer Prozess ohne direkten Bezug zur individuellen Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die spezifische Antigen-Antikörper-Bindung nach dem Schlüssel-Schloss-Prinzip ist ein direktes Struktur-Funktions-Beispiel: Jeder Antikörper besitzt eine räumliche Struktur, die nur zu einem ganz bestimmten Antigen passt, wodurch die Immunantwort hochspezifisch auf den jeweiligen Erreger zugeschnitten werden kann. Die Bildung von Antikörpern und Gedächtniszellen zu erläutern setzt ein Verständnis dieser strukturellen Erkennungsspezifität voraus.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Rezeptor-Ligand-Spezifität"],"relevante_unterkonzepte_taxonomie":[{"value":"Rezeptor-Ligand-Spezifität","taxonomyElementId":"a0ce4bf5-4332-4464-a1e2-3d27383c812e"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die spezifische Immunantwort nicht der zentrale Aspekt gegenüber der Informationsverarbeitung.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für Antikörperbildung und Immunität nicht der zentrale Aspekt.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Gedächtniszellen speichern Information über vorangegangene Erregerkontakte und sind damit ein Kernbeispiel für Informationsspeicherung in diesem Basiskonzept: Nach dem ersten Kontakt mit einem Erreger bleiben spezialisierte Zellen im Körper zurück, die dessen Oberflächenmerkmale gewissermaßen codiert ''erinnern'' und bei erneutem Kontakt eine deutlich schnellere und stärkere Antikörperbildung ermöglichen. Diese immunologische Gedächtnisbildung ist die molekularbiologische Grundlage für die im Lernziel behandelte spezifische Immunität.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_information_kommunikation__information"],"relevante_unterkonzepte":["Codierung und Decodierung von Information"],"relevante_unterkonzepte_taxonomie":[{"value":"Codierung und Decodierung von Information","taxonomyElementId":"e3e511e0-2950-4026-a57e-442c206f75a7"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Molekül","teilkonzept_primaer":"bk_information_kommunikation__information","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Zelle","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Schlüssel-Schloss-Analogie: Antigen-Antikörper-Reaktion als evolutionär optimiertes Erkennungssystem."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Zeitlicher Verlauf der Immunantwort: Erst- vs. Zweitkontakt mit Antigen – Schüler erkennen die Funktion des immunologischen Gedächtnisses als evolutionären Vorteil."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Evolutionärer Vergleich und Analogie zur biologischen Evolution: ''Neunaugen haben kein Immunglobulin-System – aber trotzdem ein adaptives Immunsystem. Was bedeutet das für die Evolution der Immunität? Und wie ähnelt die Selektion von Antikörpern der natürlichen Selektion von Organismen – Variation, Selektion, Verstärkung des Nützlichen?''"}],"bezug_zum_lehrplan_kontext":"Grundlage für HUM-ABW-6 (Immunisierung) und HUM-ABW-7 (Prävention); hochrelevant für das Verständnis von Impfungen","moegliche_fehlvorstellungen":"Schüler könnten Antikörper als ''fertig vorrätig'' betrachten; die maßgeschneiderte Produktion als Reaktion auf das spezifische Antigen muss erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Wie kann das Immunsystem Antikörper gegen Millionen verschiedener Fremdstoffe produzieren, obwohl wir nur ca. 20.000 Gene haben? Welche evolutionäre Erfindung macht das möglich? Und erinnert euch dieser Prozess an etwas – Variation entsteht zufällig, Nützliches wird selektiert und verstärkt?'' Einführung in die V(D)J-Rekombination und die Analogie zwischen Immunabwehr und biologischer Evolution."},"basiskonzepte_sekundaer":["bk_struktur_funktion","bk_evolutive_entwicklung"],"bk_prinzipien_taxonomie":[{"value":"Schlüssel-Schloss-Prinzip","taxonomyElementId":"4119f064-4a78-4bfe-a731-850a4debddf4"},{"value":"Codierung und Decodierung von Information","taxonomyElementId":"ef214769-1ffa-462e-bee3-b3000f803eb8"}],"empfohlene_klassenstufe":"8","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-HUM-ABW-6","GY-78-HUM-ABW-7"],"voraussetzende_lernziele":["GY-78-HUM-ABW-4","GY-78-HUM-VD-2","GY-78-HUM-BHK-4"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":2}'::jsonb WHERE id = 'efecc119-844f-5c3a-9a68-b41022e2fb0a'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ABW-3","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-ABW-3","unterthema":"Abwehrsystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"mittel","originaltext":"die Bedeutung weißer Blutzellen bei der körpereigenen Abwehr erläutern: Vorkommen","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Weiße Blutzellen: Vorkommen","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Weiße Blutzellen (Leukozyten) als zelluläre Grundlage des Immunsystems sind evolutionär bei allen Wirbeltieren vorhanden und zeigen eine zunehmende Spezialisierung von Fischen zu Säugetieren. Das Immunsystem ist selbst ein evolutionäres Produkt des Rüstungswettlaufs zwischen Wirten und Pathogenen. Die strategische Verteilung von Immunzellen ist eine evolutionäre Optimierung der Pathogenabwehr. Das Lymphsystem selbst ist ein evolutionäres Novum der Wirbeltiere.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck","gemeinsame Abstammung/Verwandtschaft"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"}]},{"begruendung":"Das Vorkommen weißer Blutzellen wird strukturell-funktional beschrieben, nicht als individueller Entwicklungsprozess.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Verteilung der Leukozyten in Blut und Lymphsystem ist ein strukturelles Merkmal des Abwehrsystems: Weiße Blutzellen sind nicht auf ein einziges Organ beschränkt, sondern über mehrere miteinander verbundene Kompartimente des Körpers verteilt, wodurch sie an fast jedem Ort schnell zur Abwehr bereitstehen. Die Bedeutung weißer Blutzellen zu erläutern beginnt daher folgerichtig mit ihrer strukturellen Verteilung im Körper.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_struktur_funktion__struktur"],"relevante_unterkonzepte":["Gewebe- und Organebene der Kompartimentierung"],"relevante_unterkonzepte_taxonomie":[{"value":"Gewebe- und Organebene der Kompartimentierung","taxonomyElementId":"08929832-d41e-4cd4-9657-dc97ca8d3815"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für das reine Vorkommen weißer Blutzellen nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für das Vorkommen weißer Blutzellen nicht relevant.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Leukozyten sind die zellulären Träger der Informationsverarbeitung im Immunsystem, deren Verteilung in Blut und Lymphsystem hier beschrieben wird: Nur wenn Immunzellen im gesamten Körper präsent sind, können sie an jedem Ort molekulare Gefahrensignale erkennen und darauf reagieren. Ihr Vorkommen ist damit die räumliche Voraussetzung für funktionierende immunologische Signalverarbeitung.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_information_kommunikation__information"],"relevante_unterkonzepte":["Signaltransduktion"],"relevante_unterkonzepte_taxonomie":[{"value":"Signaltransduktion","taxonomyElementId":"876b0ce3-b903-4bcc-9364-382a7ceae31e"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Zelle","teilkonzept_primaer":"bk_information_kommunikation__information","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"reproduktion_und_verstaendnis","systemebene_sekundaer":"Organ","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Körperkarte: Schüler markieren auf einer Körperumrisszeichnung, wo Immunzellen vorkommen und warum gerade dort."},{"rang":2,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Evolutionärer Vergleich: Immunsystem von Fischen vs. Säugetieren – was kommt hinzu?"},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Warum sind Schleimhäute (Mund, Nase, Darm) besonders reich an Immunzellen? Welche evolutionäre Logik steckt dahinter?''"}],"bezug_zum_lehrplan_kontext":"Grundlage für HUM-ABW-4 und -5 (Funktionen der Immunzellen); Verbindung zu HUM-BHK-3 (Blutbestandteile)","moegliche_fehlvorstellungen":"Schüler könnten das Immunsystem als ausschließlich im Blut lokalisiert betrachten; die weitreichende räumliche Verteilung und ihre evolutionäre Bedeutung muss betont werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum haben sich Immunzellen nicht nur im Blut angesammelt, sondern überall im Körper? Was sagt das über die evolutionäre Geschichte der Infektion?'' Evolutionäre Logik der räumlichen Immunverteidigung."},"basiskonzepte_sekundaer":["bk_struktur_funktion"],"empfohlene_klassenstufe":"8","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-HUM-ABW-4"],"voraussetzende_lernziele":["GY-78-HUM-BHK-3","GY-78-HUM-ABW-1"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '8a4a9a17-4f67-5e3f-b053-27df7983e36a'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-VD-2","thema":"Biologie des Menschen","anmerkung":"Schlüssellernziel für Stoff/Energie und Str/Fkt","_source_id":"GY-78-HUM-VD-2","unterthema":"Verdauungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"Verdauung als stufenweise enzymatische Umwandlung der unlöslichen Nährstoffe in ihre löslichen Grundbausteine erläutern","bk_prinzipien":["Fließgleichgewicht","Schlüssel-Schloss-Prinzip"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Enzymatische Verdauung erläutern","abstraktionsgrad":"mittel","ist_konzeptanker":true,"basiskonzeptbezug":[{"begruendung":"Verdauungsenzyme sind evolutionär entstandene Proteine. Besonders interessant ist die Evolution der Amylase: Beim Menschen ist das Amylasegen (AMY1) im Vergleich zu anderen Primaten in der Kopienzahl stark erhöht – eine evolutionäre Anpassung an eine stärkereichere Ernährung nach der Entdeckung des Feuers und dem Beginn des Getreidebaus. Die Anzahl der AMY1-Genkopien korreliert positiv mit dem Stärkeanteil in der traditionellen Ernährung verschiedener Populationen – ein Beispiel für rezente Selektion beim Menschen.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["gerichtete Selektion","Anpassung und Angepasstheit","genetische Variation","Domestikation"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"gerichtete Selektion","taxonomyElementId":"73e20c77-73a9-4560-8ba6-abe7a9eb2de2"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"genetische Variation","taxonomyElementId":"31375847-cad0-4b61-9b67-74e68ea8c520"},{"value":"Domestikation","taxonomyElementId":"300c7d55-390e-4c29-a319-4fa1a95292a9"}]},{"begruendung":"Die enzymatische Verdauung ist ein physiologischer Prozess ohne Bezug zur individuellen Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Schlüssel-Schloss-Prinzip der Enzym-Substrat-Bindung ist ein klassisches Beispiel für Struktur-Funktions-Zusammenhänge, das der stufenweisen enzymatischen Verdauung zugrunde liegt: Jedes Verdauungsenzym besitzt eine räumliche Struktur, die nur zu einem bestimmten Nährstoffbaustein passt, wodurch komplexe, unlösliche Nährstoffe gezielt in lösliche Grundbausteine zerlegt werden können. Diese strukturelle Passung erklärt, warum verschiedene Enzyme jeweils für unterschiedliche Nährstoffgruppen zuständig sind.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Enzym-Substrat-Spezifität"],"relevante_unterkonzepte_taxonomie":[{"value":"Enzym-Substrat-Spezifität","taxonomyElementId":"80abee9d-cc45-4917-8942-82c091008648"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die stufenweise enzymatische Umwandlung nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die stufenweise enzymatische Zerlegung unlöslicher Nährstoffe in ihre löslichen Grundbausteine ist der Kern der Stoffaufnahme: Große Nahrungsmoleküle wie Stärke, Fette oder Proteine müssen erst in kleinere, wasserlösliche Bausteine zerlegt werden, bevor sie überhaupt vom Körper aufgenommen werden können. Verdauung als stufenweise Umwandlung zu erläutern beschreibt damit den notwendigen ersten Schritt jeder Stoffaufnahme.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die enzymatische Verdauung nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Molekül","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Organ","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Experiment (GY-78-HUM-FPA-2): Stärkespaltung durch Speichelamylase – Schüler erleben enzymatische Verdauung direkt."},{"rang":2,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Fallbeispiel: ''Warum haben Menschen mehr Amylasegene als Schimpansen? Was sagt das über die Evolution unserer Ernährung?'' – rezente Selektion diskutieren."},{"rang":3,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Schaubild: Stufenweise Verdauung von Stärke → Maltose → Glucose im Verdauungssystem – Schüler identifizieren, wo welches Enzym wirkt."}],"bezug_zum_lehrplan_kontext":"Direkte Verbindung zu HUM-FPA-2 (Stärkespaltungsexperiment); Grundlage für HUM-VD-3 und -4","moegliche_fehlvorstellungen":"Schüler könnten Enzyme als statische, unveränderliche Moleküle betrachten; die evolutionäre Veränderung von Enzymgenen als Anpassungsreaktion muss hervorgehoben werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Menschen haben mehr Kopien des Amylasegens als Schimpansen – wann und warum hat sich das verändert? Was sagt uns das über die Evolution des Menschen?'' Einführung in rezente Selektion beim Menschen."},"basiskonzepte_sekundaer":["bk_struktur_funktion"],"bk_prinzipien_taxonomie":[{"value":"Fließgleichgewicht","taxonomyElementId":"23d0855d-a60f-4bfb-becb-8f1824c28c58"},{"value":"Schlüssel-Schloss-Prinzip","taxonomyElementId":"4119f064-4a78-4bfe-a731-850a4debddf4"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-HUM-FPA-2"],"ermoeglichende_lernziele":["GY-78-HUM-VD-3","GY-78-HUM-VD-4","GY-78-HUM-ABW-5","GY-78-HUM-FES-1"],"konzeptanker_begruendung":"Erste Einführung Schlüssel-Schloss-Prinzip im Kontext Enzyme; Konzeptanker für Str/Fkt – Funktion","voraussetzende_lernziele":["GY-78-HUM-VD-1","GY-78-ZEL-PTZ-2"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":2}'::jsonb WHERE id = 'e9e51d52-a93f-59d5-82bc-1977dd99da30'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-VD-6","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-VD-6","unterthema":"Verdauungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung erläutern: ballaststoffreiche Ernährung","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Gesunde Ernährung: Ballaststoffe","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"In der evolutionären Ernährungsumwelt des Menschen war die Nahrung reich an pflanzlichen Fasern, und das menschliche Darmmikrobiom ist evolutionär an die Fermentation von Ballaststoffen durch Darmbakterien angepasst. Das Darmmikrobiom des Menschen ist selbst ein Produkt der Koevolution zwischen Mensch und Darmbakterien über Millionen von Jahren. Eine ballaststoffarme Ernährung wirkt als evolutionäres Mismatch: Das Darmmikrobiom verliert Diversität, was mit einer Reihe moderner Erkrankungen assoziiert wird.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","Evolutionäres Mismatch","Anpassung und Angepasstheit","Nischenkonstruktion"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Nischenkonstruktion","taxonomyElementId":"90d33e38-ad06-4ce6-b3c3-3eee58a48292"}]},{"begruendung":"Ballaststoffreiche Ernährung betrifft die Verdauungsphysiologie, nicht die individuelle Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Organe sind für die Bedeutung von Ballaststoffen nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die Bedeutung ballaststoffreicher Ernährung nicht das zentrale Konzept.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Ballaststoffe beeinflussen unmittelbar die Verdauung und den Stoffwechsel des Darmmikrobioms: Obwohl sie vom menschlichen Körper selbst nicht verdaut werden können, dienen sie den im Darm lebenden Bakterien als Nahrung und beeinflussen dadurch deren Zusammensetzung und Stoffwechselaktivität. Maßnahmen zur ballaststoffreichen Ernährung zu erläutern setzt ein Verständnis dieser indirekten, aber bedeutsamen stofflichen Wirkung voraus.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffumwandlung"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffumwandlung","taxonomyElementId":"0d4c7b1d-0a19-483e-82fc-e5c1cc3a863d"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für ballaststoffreiche Ernährung nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Digitale Medien","beschreibung":"Infografik: Zusammensetzung des menschlichen Darmmikrobioms – Schüler erkennen die Vielfalt der Bakterienarten."},{"rang":2,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich: Ballaststoffgehalt traditioneller Ernährungen vs. westliche Ernährung – evolutionäre Einordnung."},{"rang":3,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallstudie: Studien über Darmmikrobiom bei Menschen in Industrieländern vs. traditionellen Gesellschaften (z. B. Hadza-Jäger-Sammler) – Schüler interpretieren die Ergebnisse."}],"bezug_zum_lehrplan_kontext":"Verbindung zu ZEL-BAK (Bakterien) und HUM-ABW (Abwehrsystem); Gesundheitserziehungsaspekt","moegliche_fehlvorstellungen":"Schüler könnten Darmbakterien generell als ''schädlich'' betrachten; die essenzielle Rolle der Darmflora für Gesundheit und ihre evolutionäre Herkunft muss klar gemacht werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Der Mensch hat ca. 39 Billionen Bakterien im Darm – warum brauchen wir diese Bakterien? Wie hat sich diese Gemeinschaft evolutionär entwickelt?'' Einführung in Koevolution zwischen Mensch und Darmmikrobiom."},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-VD-1"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'c1e1d316-e169-5545-b2ed-cec670d1746f'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ATM-4","thema":"Biologie des Menschen","anmerkung":"Abstraktester Schritt im Stoff/Energie-Block; phänomenologisch vorbereiten","_source_id":"GY-78-HUM-ATM-4","unterthema":"Atmungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"mittel","originaltext":"die Wort- und Summengleichung der Zellatmung formulieren und die Bedeutung von Sauerstoff für die Energiefreisetzung erläutern","bk_prinzipien":["Energetische Kopplung","Energieentwertung"],"ist_praktisch":false,"kognitionsverb":"formulieren_erläutern","kurzbezeichnung":"Zellatmungsgleichung formulieren","abstraktionsgrad":"hoch","ist_konzeptanker":true,"basiskonzeptbezug":[{"begruendung":"Die aerobe Zellatmung ist eine der bedeutendsten evolutionären Errungenschaften des Lebens. Die Entstehung der aeroben Atmung vor ca. 2,4 Milliarden Jahren ermöglichte eine drastische Steigerung der Energieausbeute aus organischen Molekülen. Die Mitochondrien, in denen die aerobe Zellatmung hauptsächlich stattfindet, sind evolutionäre Endosymbionten (ehemalige aerobe Proteobakterien). Die Summengleichung der Zellatmung ist die Umkehrreaktion der Photosynthese – ein elegantes Bild der evolutionären Verknüpfung von Autotrophie und Heterotrophie im Kohlenstoffkreislauf.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Endosymbiontentheorie","Tiefenzeit","Natürliche Selektion und Selektionsdruck","gemeinsame Abstammung/Verwandtschaft"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Endosymbiontentheorie","taxonomyElementId":"94eb6ae3-f936-4cab-9181-f45197233dfa"},{"value":"Tiefenzeit","taxonomyElementId":"733b2bfc-8d20-4d6f-b875-f97958cfbab7"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"}]},{"begruendung":"Die Zellatmung ist ein biochemischer Prozess ohne Bezug zur individuellen Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen der Mitochondrien wurden bereits andernorts behandelt; hier steht die Reaktionsgleichung im Fokus.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die Formulierung der Zellatmungsgleichung nicht relevant.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Zellatmung als Freisetzung von Energie aus Nährstoffen mithilfe von Sauerstoff ist der Kern dieses Basiskonzepts: In der Wort- und Summengleichung wird formal zusammengefasst, wie energiereiche Nährstoffe unter Sauerstoffverbrauch zu Kohlenstoffdioxid und Wasser abgebaut werden, wobei die zuvor in den Nährstoffen gespeicherte chemische Energie freigesetzt und für die ATP-Synthese genutzt wird. Diese Gleichung formulieren zu können verdichtet die gekoppelte Stoff- und Energieumwandlung der Zellatmung auf eine kompakte, formale Darstellung.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__energie"],"relevante_unterkonzepte":["Energetische Kopplung"],"relevante_unterkonzepte_taxonomie":[{"value":"Energetische Kopplung","taxonomyElementId":"a4fea8b0-1264-43c8-ab4c-ce962327d26a"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für die Zellatmungsgleichung nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organell","teilkonzept_primaer":"bk_stoff_energie_umwandlung__energie","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Organismus","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Historischer Einstieg: ''Wie hat sich die Erde durch Cyanobakterien verändert? Was bedeutete Sauerstoff für frühe Lebewesen?'' – Große Sauerstoffkatastrophe als Kontext."},{"rang":2,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Gleichungsvergleich: Zellatmungs- und Photosynthese-Gleichung nebeneinander – Schüler erkennen die Komplementarität."},{"rang":3,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Experiment (GY-78-HUM-FPA-3): CO₂-Nachweis in der Ausatemluft als direkter Beleg für Zellatmung."}],"bezug_zum_lehrplan_kontext":"Verbindung zu ZEL-PTZ-2 (Mitochondrien als Endosymbionten) und ZEL-PTZ-4 (Autotrophie/Heterotrophie); HUM-ZUS-3 (Zusammenhang Ernährung und Zellatmung)","moegliche_fehlvorstellungen":"Schüler könnten Zellatmung mit Lungenatmung verwechseln; die zelluläre Ebene der Energiefreisetzung (Mitochondrien) muss von der Organatmung klar abgegrenzt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Vor der Entstehung der Photosynthese gab es keinen Sauerstoff auf der Erde – wie haben Lebewesen damals Energie gewonnen? Was hat sich durch Sauerstoff verändert?'' Einführung in die Evolution der Zellatmung als historisches Ereignis."},"basiskonzepte_sekundaer":["bk_struktur_funktion"],"bk_prinzipien_taxonomie":[{"value":"Energetische Kopplung","taxonomyElementId":"9cd03f9a-998e-462d-a3c8-46fb60d0cc75"},{"value":"Energieentwertung","taxonomyElementId":"89267acc-76d8-4c21-9d6d-d8450bd849ec"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-HUM-FPA-3"],"ermoeglichende_lernziele":["GY-78-HUM-ZUS-3"],"konzeptanker_begruendung":"Zentrale Konzeptanker für Stoff/Energie – Energie; verbindet Verdauung, Atmung und Energiegewinnung","voraussetzende_lernziele":["GY-78-HUM-ATM-3","GY-78-ZEL-PTZ-4"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":2}'::jsonb WHERE id = 'fa033c50-5bbe-58a3-9c99-d2549e48bf4a'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-NER-12","thema":"Biologie des Menschen","anmerkung":"Prävention; Synapsenmodell anwenden","_source_id":"GY-78-HUM-NER-12","unterthema":"Nervensystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung erläutern: Vermeidung des Missbrauchs von Suchtmitteln (z. B. Alkohol, THC)","bk_prinzipien":["Signaltransduktion"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Gesunderhaltung: Suchtmittel","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Suchtmittel wie Alkohol und THC wirken auf das evolutionär entstandene Belohnungssystem (mesolimbisches Dopaminsystem). Suchtmittel kapern dieses System, indem sie direkt Dopamin freisetzen, ohne dass das ursprünglich adaptiv selektierte Verhalten ausgeführt wird – ein klassisches Beispiel für evolutionäres Mismatch. THC aus Cannabis bindet an evolutionär entstandene Endocannabinoid-Rezeptoren, die normalerweise durch körpereigene Cannabinoide aktiviert werden. Das Belohnungssystem ist evolutionär bei Wirbeltieren hochkonserviert und lässt sich phylogenetisch weit zurückverfolgen.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Evolutionäres Mismatch","Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck","Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)","taxonomyElementId":"80535000-9149-4a60-b7d3-5d56d5deddf3"}]},{"begruendung":"Suchtmittel wirken auf physiologische Signalsysteme, nicht primär auf die individuelle Entwicklung im engeren Sinn.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Rezeptoren sind hier dem Wirkmechanismus der Sucht nachgeordnet.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Suchtmittel wie Alkohol oder THC stören das natürliche Regelsystem des Belohnungssystems und verschieben dessen normalen Sollwert: Wiederholter Konsum gewöhnt das System an ein künstlich erhöhtes Erregungsniveau, sodass ohne die Substanz ein Mangelzustand empfunden wird. Diese Verschiebung des Sollwerts erschwert die Rückkehr zur ursprünglichen, unbeeinflussten Regulation erheblich.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Negative Rückkopplung (inkl. Homöostase-Prinzip)"],"relevante_unterkonzepte_taxonomie":[{"value":"Negative Rückkopplung (inkl. Homöostase-Prinzip)","taxonomyElementId":"b1a84980-ecba-4199-8157-4be6c4fada55"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für die Wirkung von Suchtmitteln nicht der zentrale Aspekt.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Alkohol und THC wirken direkt auf die chemische Signalübertragung an Synapsen, etwa über Dopamin oder Endocannabinoide, und verändern dadurch die nervale Kommunikation im Gehirn: Beide Substanzen beeinflussen, wie stark und wie lange bestimmte Botenstoffe an ihren Rezeptoren wirken, was die normale Signalverarbeitung verzerrt. Diese direkte Störung synaptischer Kommunikation erklärt sowohl die kurzfristige Wirkung als auch das Suchtpotenzial solcher Substanzen.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_information_kommunikation__kommunikation"],"relevante_unterkonzepte":["Nervale Kommunikation (Synapsen, Aktionspotenzial)"],"relevante_unterkonzepte_taxonomie":[{"value":"Nervale Kommunikation (Synapsen, Aktionspotenzial)","taxonomyElementId":"190ff2ff-f8c2-46e6-8244-9a03f956ed36"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q2","systemebene_primaer":"Molekül","teilkonzept_primaer":"bk_information_kommunikation__kommunikation","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"analyse_und_bewertung","systemebene_sekundaer":"Organismus","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Schaubild: Dopaminausschüttung bei natürlichem Belohnungsverhalten vs. bei Drogenkonsum – Unterschiede visualisieren."},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallanalyse: ''Warum wurden Endocannabinoid-Rezeptoren im menschlichen Gehirn gefunden? Was ist ihre ursprüngliche biologische Funktion? Bei welchen anderen Tieren finden sich ähnliche Belohnungssysteme?'' – Phylogenese des Belohnungssystems erkunden."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"''Warum empfinden Menschen Suchtmittel als angenehm? Was sagt uns das über unser evolutionäres Erbe? Und was passiert, wenn ein für die Savanne optimiertes System mit modernen psychoaktiven Substanzen konfrontiert wird?''"}],"bezug_zum_lehrplan_kontext":"Integrationslernziel mit hoher Relevanz für Gesundheitserziehung und Suchtprävention; Verbindung zu HUM-NER-10 (synaptische Veränderungen)","moegliche_fehlvorstellungen":"Schüler könnten denken, Sucht sei eine Frage der ''Willenskraft''; die neurobiologische und evolutionäre Grundlage der Sucht muss sachlich erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Unser Gehirn hat Rezeptoren für THC – aber THC kommt von der Cannabispflanze. Warum hat unser Gehirn diese Rezeptoren und was sagt uns das? Und seit wann existiert das Belohnungssystem in der Evolutionsgeschichte der Wirbeltiere?'' Einführung in das Konzept endogener Liganden und die Phylogenese des Belohnungssystems."},"basiskonzepte_sekundaer":["bk_steuerung_regelung"],"bk_prinzipien_taxonomie":[{"value":"Signaltransduktion","taxonomyElementId":"599e5fa0-ac5f-4866-9fdb-69c99396b426"}],"empfohlene_klassenstufe":"8","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-NER-10"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'a5ec15f7-eec7-5ecf-b68b-7f0c1f9deeba'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ABW-4","thema":"Biologie des Menschen","anmerkung":"","_source_id":"GY-78-HUM-ABW-4","unterthema":"Abwehrsystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"mittel","originaltext":"die Bedeutung weißer Blutzellen bei der körpereigenen Abwehr erläutern: Aufnahme und Abbau von körperfremden Stoffen und abgestorbenen Zellen (unspezifisch)","bk_prinzipien":["Fließgleichgewicht"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Unspezifische Abwehr erläutern","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die Phagozytose ist einer der evolutionär ältesten Abwehrmechanismen und findet sich bereits bei einzelligen Eukaryoten (z. B. Amöben fressen Bakterien durch Phagozytose). Die Phagozytose ist nicht nur eine Abwehrmethode, sondern auch die evolutionäre Methode, durch die die Endosymbiose stattfand: Ein früher Eukaryot nahm eine Bakterie durch Phagozytose auf und behielt sie als Endosymbionten (später Mitochondrium). Die molekularen Muster, die Phagozyten erkennen (PAMPs), sind evolutionär konserviert und ermöglichen die Erkennung bakterieller Oberflächen ohne vorherigen Kontakt.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Endosymbiontentheorie","Koevolution","Anpassung und Angepasstheit","Evolution von Einzellern zu Vielzellern"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Endosymbiontentheorie","taxonomyElementId":"94eb6ae3-f936-4cab-9181-f45197233dfa"},{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Evolution von Einzellern zu Vielzellern","taxonomyElementId":"e5b7c6e1-e650-4053-9b80-767aaf023d6f"}]},{"begruendung":"Phagozytose ist ein zellulärer Abwehrmechanismus ohne Bezug zur individuellen Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen der Fresszellen sind hier dem Vorgang des Abbaus nachgeordnet.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für die Phagozytose als unspezifischen Mechanismus nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Aufnahme und der Abbau körperfremder Stoffe und abgestorbener Zellen durch Phagozytose sind unmittelbar Stoffumwandlungsprozesse: Fresszellen des Immunsystems nehmen körperfremdes Material aktiv auf und zerlegen es enzymatisch in unschädliche Bestandteile, ähnlich wie bei der Verdauung. Die Erläuterung dieser unspezifischen Abwehr beschreibt damit einen weiteren, immunologisch bedeutsamen Stoffumwandlungsprozess im Körper.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffumwandlung"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffumwandlung","taxonomyElementId":"0d4c7b1d-0a19-483e-82fc-e5c1cc3a863d"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Als unspezifischer Mechanismus erkennt die Phagozytose Muster, ohne eine gezielte Informationsverarbeitung wie beim adaptiven Immunsystem.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Zelle","teilkonzept_primaer":"bk_stoff_energie_umwandlung__stoff","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Digitale Medien","beschreibung":"Videoanalyse: Zeitrafferaufnahme einer Amöbe, die Bakterien frisst – Phagozytose als evolutionär ursprünglicher Prozess."},{"rang":2,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Verbindungsaufgabe: ''Phagozytose dient heute der Immunabwehr – wie könnte dieselbe Methode zur Entstehung der Mitochondrien geführt haben?'' – kreative Verknüpfung mit Endosymbiontentheorie."},{"rang":3,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Schaubild: Evolutionäre Zeitlinie der Immunentwicklung: Phagozytose bei Einzellern → angeborene Immunität bei Tieren → adaptive Immunität bei Wirbeltieren."}],"bezug_zum_lehrplan_kontext":"Verbindung zu ZEL-PTZ-2 (Endosymbiose) und ZEL-BAK-1 (Bakterien); einer der faszinierendsten evolutionären Verbindungen im gesamten Lehrplan","moegliche_fehlvorstellungen":"Schüler könnten Phagozytose als rein tierische Fähigkeit betrachten; ihre evolutionär ursprüngliche Natur bei Einzellern und ihre Rolle bei der Endosymbiose muss hervorgehoben werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Amöben fressen Bakterien durch Phagozytose – genauso wie eure Immunzellen. Und die Mitochondrien in euren Zellen sind möglicherweise durch denselben Prozess entstanden. Was für ein seltsames evolutionäres Doppelleben hat die Phagozytose geführt!'' Hochmotivierende Verbindung zwischen Immunologie und Endosymbiontentheorie."},"basiskonzepte_sekundaer":["bk_information_kommunikation"],"bk_prinzipien_taxonomie":[{"value":"Fließgleichgewicht","taxonomyElementId":"23d0855d-a60f-4bfb-becb-8f1824c28c58"}],"empfohlene_klassenstufe":"8","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-HUM-ABW-5"],"voraussetzende_lernziele":["GY-78-HUM-ABW-3"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '6018f7e8-4b98-5a51-921d-56a196525cf3'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-AUS-2","thema":"Biologie des Menschen","anmerkung":"Gegenstromprinzip einführen; Verbindung zu ADH-Regelkreis","_source_id":"GY-78-HUM-AUS-2","unterthema":"Ausscheidungssystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"mittel","originaltext":"die Bedeutung der Niere als Ausscheidungsorgan erläutern: Bau und Funktion der Niere (Filtern des Blutes, Bilden des Harns)","bk_prinzipien":["Gegenstromprinzip","Oberflächenvergrößerung","Filtration"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Niere: Bau und Funktion","abstraktionsgrad":"hoch","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die Feinstruktur des Nephrons ist evolutionär zwischen Wirbeltierklassen unterschiedlich ausgeprägt und spiegelt Anpassungen an verschiedene Wasserverfügbarkeiten wider. Wüstentiere (z. B. Springmäuse) haben besonders lange Henle-Schleifen und können extrem konzentrierten Harn produzieren – ein direktes evolutionäres Anpassungsmerkmal. Der Vergleich der Nierenstruktur verschiedener Wirbeltiere ist daher ein direktes Fenster in die evolutionäre Physiologie.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Anpassung und Angepasstheit","gerichtete Selektion","Homologie und Analogie/Konvergente und divergente Evolution","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"gerichtete Selektion","taxonomyElementId":"73e20c77-73a9-4560-8ba6-abe7a9eb2de2"},{"value":"Homologie und Analogie/Konvergente und divergente Evolution","taxonomyElementId":"492006a1-28b5-4418-90ff-a167424785fc"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Bau und Funktion der Niere werden strukturell-funktional erklärt, nicht als individueller Entwicklungsprozess.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Nephron, Gegenstromprinzip und Filtration sind das Kernbeispiel für Struktur-Funktions-Zusammenhänge in diesem Themenfeld: Die millionenfache Wiederholung des Nephrons als funktionale Grundeinheit der Niere und die gegenläufige Anordnung von Gefäßen und Kanälchen im Nierenmark ermöglichen eine hochwirksame Harnkonzentrierung. Bau und Funktion der Niere als Filter- und Ausscheidungsorgan zu erläutern verknüpft damit mehrere strukturelle Prinzipien zu einem komplexen, aber gut nachvollziehbaren Gesamtsystem.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_struktur_funktion__funktion"],"relevante_unterkonzepte":["Gegenstromprinzip"],"relevante_unterkonzepte_taxonomie":[{"value":"Gegenstromprinzip","taxonomyElementId":"32743716-be07-4aa2-aad5-c585b14c0eea"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Niere reguliert über die je nach Bedarf angepasste Harnkonzentrierung den Wasser- und Salzhaushalt des Körpers: Bei Wassermangel wird mehr Wasser aus dem Vorharn rückresorbiert und ein konzentrierterer Harn ausgeschieden, bei Wasserüberschuss entsprechend weniger. Bau und Funktion der Niere lassen sich damit als Regelorgan verstehen, das innere Zustandsgrößen konstant hält.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Negative Rückkopplung (inkl. Homöostase-Prinzip)"],"relevante_unterkonzepte_taxonomie":[{"value":"Negative Rückkopplung (inkl. Homöostase-Prinzip)","taxonomyElementId":"b1a84980-ecba-4199-8157-4be6c4fada55"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Filtration und Rückresorption in der Niere sind zentrale Prozesse der Stoffumwandlung und -ausscheidung: Beim Filtern des Blutes werden zunächst nahezu alle gelösten Stoffe abgefiltert, bevor in einem zweiten Schritt lebenswichtige Stoffe wie Glukose gezielt wieder ins Blut zurückgeholt werden, während Abfallstoffe im Harn verbleiben. Bau und Funktion der Niere zu erläutern beschreibt damit einen mehrstufigen stofflichen Sortier- und Ausscheidungsprozess.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für Bau und Funktion der Niere nicht der zentrale Aspekt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q4","systemebene_primaer":"Organ","teilkonzept_primaer":"bk_struktur_funktion__funktion","basiskonzepte_primaer":["bk_struktur_funktion"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":"Gewebe","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Schemazeichnung: Nephron mit allen Abschnitten – Schüler beschriften und erläutern Funktion jedes Abschnitts."},{"rang":2,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich: Henle-Schleife bei Wüstenmaus vs. Biber – Schüler leiten aus der Länge der Schleife die Anpassung ab."},{"rang":3,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Fallbeispiel: ''Wie schafft es die Springmaus, fast ohne Trinkwasser zu überleben?'' – Nierenfunktion als evolutionäre Anpassung an Wüstenklima."}],"bezug_zum_lehrplan_kontext":"Kernlernziel des Ausscheidungssystem-Themas; Verbindung zu HUM-BHK (Blut als zu filtrierende Flüssigkeit)","moegliche_fehlvorstellungen":"Schüler könnten die Niere als statisches Filtrationsorgan ohne evolutionäre Diversität verstehen; die Variation der Nephronstruktur als evolutionäres Signal muss hervorgehoben werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum können Wüstentiere so viel konzentrierteren Urin produzieren als Menschen? Welche Unterschiede im Nierenaufbau liegen dem zugrunde?'' Evolutionäre Erklärung einer physiologischen Anpassung."},"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung","bk_steuerung_regelung"],"bk_prinzipien_taxonomie":[{"value":"Gegenstromprinzip","taxonomyElementId":"5c071b6e-34e5-45b7-8c6c-126bed239156"},{"value":"Oberflächenvergrößerung","taxonomyElementId":"cb401288-808e-40df-890e-7ddf6bd4c891"},{"value":"Filtration","taxonomyElementId":"19937ab4-23f1-402e-a1d7-e26a86e65bf9"}],"empfohlene_klassenstufe":"7","interleaving_empfehlung":["GY-78-HUM-FPA-4"],"ermoeglichende_lernziele":["GY-78-HUM-ZUS-2"],"voraussetzende_lernziele":["GY-78-HUM-AUS-1","GY-78-HUM-VD-4"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":2}'::jsonb WHERE id = 'c47918d8-50b3-5c68-a2be-aa138189df1b'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-NER-11","thema":"Biologie des Menschen","anmerkung":"Integrationslernziel mit Gesundheitsbildung","_source_id":"GY-78-HUM-NER-11","unterthema":"Nervensystem","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Gesunderhaltung erläutern: Vermeidung von Reizüberflutung durch Lärm oder Licht","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Gesunderhaltung: Reizüberflutung","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das menschliche Nervensystem ist evolutionär auf die Reizbedingungen der evolutionären Umwelt (Environment of Evolutionary Adaptedness, EEA) abgestimmt. Reizüberflutung durch künstliche Licht- und Lärmquellen moderner Industriegesellschaften stellt ein evolutionäres Mismatch dar: Das Nervensystem ist nicht auf die Verarbeitung der extremen Reizdichten moderner Städte ausgelegt. Dies erklärt, warum Lärm- und Lichtbelastung nachweislich zu Stress, Schlafstörungen und Gesundheitsschäden führt.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Evolutionäres Mismatch","Anpassung und Angepasstheit","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Reizüberflutung betrifft die Belastung des Nervensystems, nicht die individuelle Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen sind für die Vermeidung von Reizüberflutung nicht der zentrale Aspekt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind hier nicht vertieft; im Fokus steht die Reizmenge, die verarbeitet werden muss.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für die Vermeidung von Reizüberflutung nicht relevant.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Zu hohe Reizdichte durch Lärm oder Licht überfordert die Informationsverarbeitungskapazität des Nervensystems und ist damit der Kern dieses Lernziels: Wenn mehr Reize eintreffen, als das Gehirn sinnvoll verrechnen kann, sinkt die Qualität der Verarbeitung und Stresssymptome können auftreten. Maßnahmen zur Vermeidung von Reizüberflutung schützen damit gezielt die begrenzte Verarbeitungskapazität des zentralen Nervensystems.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_information_kommunikation__information"],"relevante_unterkonzepte":["Reizweiterleitung und zentrale Verarbeitung"],"relevante_unterkonzepte_taxonomie":[{"value":"Reizweiterleitung und zentrale Verarbeitung","taxonomyElementId":"ffeb5148-e656-44f8-9d71-37de90d75701"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q2","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_information_kommunikation__information","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich: Natürliche Reizbedingungen in der Savanne vs. moderne Großstadt – Schüler identifizieren Unterschiede und mögliche Gesundheitsfolgen."},{"rang":2,"favorit":false,"methode":"Narrativer Zugang","beschreibung":"Fallstudie: Auswirkungen von Nachtlicht auf den Melatonin-Spiegel – evolutionäre Erklärung des Schlaf-Wach-Rhythmus."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Reflexionsaufgabe: ''Wie viele Bildschirme, Lautsprecher und künstliche Lichtquellen umgeben euch täglich? Wie würde ein Mensch der Steinzeit darauf reagieren?''"}],"bezug_zum_lehrplan_kontext":"Integrationslernziel mit Bezug zu Gesundheitsförderung und Medienkompetenz; hohe Alltagsrelevanz für Schüler der Klassenstufe 7/8","moegliche_fehlvorstellungen":"Schüler könnten glauben, Menschen hätten sich inzwischen ''angepasst''; die Langsamkeit genetischer Evolution im Vergleich zur raschen Kulturentwicklung muss thematisiert werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Unser Nervensystem wurde für die Savanne gebaut – was passiert, wenn es mit Großstadtlärm und Smartphone-Licht konfrontiert wird?'' Einführung in das Konzept des evolutionären Mismatches."},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"8","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-NER-5"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '9fab5dc0-b154-58e6-9bf3-54e92afdc3ca'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ZUS-2","thema":"Biologie des Menschen","anmerkung":"Höchstes Syntheseziel des Lehrgangs; alle Basiskonzepte zusammenführen","_source_id":"GY-78-HUM-ZUS-2","unterthema":"Zusammenwirken der Systeme","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"das Zusammenwirken von Verdauungs-, Atmungs-, Herz-Kreislauf- und Ausscheidungssystem erläutern","bk_prinzipien":["Homöostase","Fließgleichgewicht"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Zusammenwirken der Organsysteme erläutern","abstraktionsgrad":"sehr hoch","ist_konzeptanker":true,"basiskonzeptbezug":[{"begruendung":"Das Zusammenwirken der Organsysteme ist das Ergebnis einer langen evolutionären Ko-Evolution dieser Systeme innerhalb der Wirbeltiere. Die funktionelle Integration von Verdauung, Atmung, Kreislauf und Ausscheidung zu einem kohärenten physiologischen System ist eine evolutionäre Leistung, die die Entstehung großer, homoiothermer Organismen ermöglichte. Die Systeme haben sich nicht unabhängig voneinander entwickelt, sondern in wechselseitiger evolutionärer Abhängigkeit. Das Verständnis des Zusammenwirkens schult das systemische Denken, das auch in der Evolutionsbiologie zentral ist.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","Anpassung und Angepasstheit","gemeinsame Abstammung/Verwandtschaft","Natürliche Selektion und Selektionsdruck"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"}]},{"begruendung":"Das Zusammenwirken der Organsysteme wird funktional erklärt, nicht als individueller Entwicklungsprozess.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen der Einzelorgane wurden bereits andernorts behandelt; hier steht das Zusammenspiel im Fokus.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das koordinierte Zusammenwirken von Verdauungs-, Atmungs-, Herz-Kreislauf- und Ausscheidungssystem zur Aufrechterhaltung der Homöostase ist der Kern dieses Lernziels: Keines dieser Systeme reguliert seine Aufgabe isoliert, sondern jedes ist über gemeinsame Regelgrößen wie den Blutzucker-, Sauerstoff- oder Wasserhaushalt eng mit den anderen verknüpft. Erst durch dieses fein abgestimmte Zusammenspiel mehrerer Regelkreise kann der Körper innere Zustände trotz stark wechselnder äußerer und innerer Anforderungen konstant halten.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_steuerung_regelung__regelung"],"relevante_unterkonzepte":["Negative Rückkopplung (inkl. Homöostase-Prinzip)"],"relevante_unterkonzepte_taxonomie":[{"value":"Negative Rückkopplung (inkl. Homöostase-Prinzip)","taxonomyElementId":"b1a84980-ecba-4199-8157-4be6c4fada55"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Verdauung, Atmung, Kreislauf und Ausscheidung bilden gemeinsam die durchgehende Kette der Stoffaufnahme, -verteilung und -abgabe im Körper: Ohne das koordinierte Zusammenwirken dieser vier Organsysteme könnten Stoffe weder aus der Umwelt aufgenommen noch im Körper verteilt oder am Ende wieder ausgeschieden werden. Das Zusammenwirken der Organsysteme zu erläutern zeigt damit den vollständigen stofflichen Kreislauf durch den Körper.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__stoff"],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation zwischen den Organsystemen wird hier nicht vertieft, im Fokus steht das funktionale Zusammenwirken.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q4","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_steuerung_regelung__regelung","basiskonzepte_primaer":["bk_steuerung_regelung"],"kognitive_anforderung":"synthese","systemebene_sekundaer":"Organ","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Systemdiagramm: Schüler zeichnen Pfeile zwischen den vier Organsystemen und beschriften die Verbindungen (was wird übertragen?)."},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallanalyse: ''Was passiert mit allen vier Systemen, wenn die Niere ausfällt?'' – Systemisches Denken üben."},{"rang":3,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Evolutionärer Vergleich: ''Haben Fische diese vier Systeme auch? Was ist ähnlich, was ist verschieden?'' – phylogenetischer Systemvergleich."}],"bezug_zum_lehrplan_kontext":"Syntheselernziel des gesamten Humanbiologiethemas; Vorbereitung auf integrative Biologiebetrachtung in höheren Klassen","moegliche_fehlvorstellungen":"Schüler könnten die Organsysteme als voneinander unabhängige Module betrachten; die evolutionäre Integration und Abhängigkeit muss explizit thematisiert werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum können Organsysteme nicht unabhängig voneinander evolvieren? Welche Konsequenzen hätte es, wenn die Lunge schneller evolvierte als das Herz?'' Einführung in evolutionäre Korrelationen zwischen Organsystemen."},"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung","bk_information_kommunikation"],"bk_prinzipien_taxonomie":[{"value":"Homöostase","taxonomyElementId":"d133832d-a92c-44f8-a967-db1f7b6a56ac"},{"value":"Fließgleichgewicht","taxonomyElementId":"23d0855d-a60f-4bfb-becb-8f1824c28c58"}],"empfohlene_klassenstufe":"8","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-HUM-ZUS-3"],"konzeptanker_begruendung":"Synthese aller Organsysteme als übergeordneter Regelkreis; zeigt Homöostase als emergente Systemeigenschaft","voraussetzende_lernziele":["GY-78-HUM-VD-4","GY-78-HUM-ATM-4","GY-78-HUM-BHK-1","GY-78-HUM-AUS-2"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":2}'::jsonb WHERE id = '2b43de98-338c-5b3e-a774-79105c8fbfa2'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-FES-7","thema":"Biologie des Menschen","anmerkung":"Verbindung zu Abwehrsystem und Impfung","_source_id":"GY-78-HUM-FES-7","unterthema":"Fortpflanzung, Entwicklung und Sexualität","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Maßnahmen zur Prävention sexuell übertragbarer Krankheiten (z. B. Hepatitis-B, HPV) begründen","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"begründen","kurzbezeichnung":"STI-Prävention begründen","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Sexuell übertragbare Krankheitserreger sind Produkte der koevolutiven Dynamik zwischen Pathogenen und ihren menschlichen Wirten. Der sexuelle Übertragungsweg ist evolutionär aus Sicht des Erregers besonders vorteilhaft, da er die Übertragung an den Reproduktionsakt des Wirts knüpft. HPV-Impfstoffe nutzen das evolutionär entstandene Immungedächtnis präventiv. Die Diskussion über Impfungen hat einen direkten evolutionären Bezug zur Koevolution von Wirt und Pathogen sowie zur Evolution des Immunsystems.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Koevolution","Natürliche Selektion und Selektionsdruck","Anpassung und Angepasstheit"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Koevolution","taxonomyElementId":"53b461d5-f547-4f1a-872f-390df917b8e5"},{"value":"Natürliche Selektion und Selektionsdruck","taxonomyElementId":"21fd80e9-da90-47b6-aaee-ac27ecbd8142"},{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"}]},{"begruendung":"Sexuell übertragbare Krankheiten wie HPV oder Hepatitis-B betreffen unmittelbar reproduktive Vorgänge und die Gesundheit der Fortpflanzungsorgane. Präventionsmaßnahmen zu begründen setzt daher ein Verständnis der reproduktiven Funktionen und ihrer Verwundbarkeit voraus, weshalb dieses Lernziel an das Basiskonzept anknüpft, auch wenn sein Schwerpunkt eher gesundheitlicher als entwicklungsbiologischer Natur ist.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Reproduktion"],"relevante_unterkonzepte_taxonomie":[{"value":"Reproduktion","taxonomyElementId":"d1597cd6-5648-49bc-9ad2-9f27f9f43bc5"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Organe sind für die Prävention übertragbarer Krankheiten nicht der Fokus.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für Präventionsmaßnahmen gegen sexuell übertragbare Krankheiten nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für die Prävention sexuell übertragbarer Krankheiten nicht relevant.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Immungedächtnis, das Impfungen präventiv nutzen, ist ein zentrales Beispiel für Informationsspeicherung im Immunsystem: Nach dem ersten Kontakt mit einem Erreger oder Impfstoff codiert das Immunsystem dessen charakteristische Oberflächenmerkmale in Gedächtniszellen, die bei einem erneuten Kontakt eine deutlich schnellere Abwehrreaktion ermöglichen. Die Begründung von STI-Präventionsmaßnahmen wie der HPV-Impfung stützt sich unmittelbar auf dieses Prinzip gespeicherter immunologischer Information.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_information_kommunikation__information"],"relevante_unterkonzepte":["Codierung und Decodierung von Information"],"relevante_unterkonzepte_taxonomie":[{"value":"Codierung und Decodierung von Information","taxonomyElementId":"e3e511e0-2950-4026-a57e-442c206f75a7"}],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_information_kommunikation__information","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"analyse_und_bewertung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Fallstudie HPV: Wie funktioniert der HPV-Impfstoff? Warum ist Impfung aus evolutionärer Sicht sinnvoll?"},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Koevolutions-Schema: Schüler zeichnen den ''Rüstungswettlauf'' zwischen Immunsystem und Virus nach."},{"rang":3,"favorit":false,"methode":"Recherche","beschreibung":"Rechercheprojekt: Wie hat sich die Häufigkeit bestimmter STIs durch Präventionsmaßnahmen verändert?"}],"bezug_zum_lehrplan_kontext":"Verbindung zu GY-78-HUM-ABW (Abwehrsystem, Immunisierung); gesundheitserzieherische Relevanz","moegliche_fehlvorstellungen":"Schüler könnten denken, der Virus ''will'' übertragen werden; der selektive Mechanismus (keine Absicht, sondern Selektion auf Übertragungserfolg) muss erklärt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Warum haben sich Viren auf den sexuellen Übertragungsweg spezialisiert? Ist das eine evolutionäre Strategie des Virus?'' Einführung in das Konzept der Pathogen-Koevolution."},"basiskonzepte_sekundaer":["bk_individuelle_entwicklung"],"empfohlene_klassenstufe":"8","interleaving_empfehlung":["GY-78-HUM-ABW-7"],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-ABW-6","GY-78-HUM-FES-5"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '3eb2416d-1925-52e0-a22a-5285cf664080'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-FES-5","thema":"Biologie des Menschen","anmerkung":"Integrationslernziel; respektvoller Umgang mit Diversität","_source_id":"GY-78-HUM-FES-5","unterthema":"Fortpflanzung, Entwicklung und Sexualität","_source_file":"lernziele_gy78.json","alltagsnaehe":"sehr hoch","originaltext":"Sexualität als natürliches Verhalten kennzeichnen sowie Varianten des biologischen Geschlechts, Geschlechtsidentitäten und sexuelle Orientierungen erläutern","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"kennzeichnen_erläutern","kurzbezeichnung":"Sexualität und Geschlechtsidentität erläutern","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die biologische Vielfalt sexueller Phänomene ist evolutionär zu erklären: Sexuelle Fortpflanzung als solche ist eine evolutionäre Strategie zur Erhöhung der genetischen Diversität (Rekombination), die die Anpassungsfähigkeit von Populationen erhöht. Intergeschlechtlichkeit zeigt, dass das biologische Geschlecht ein Kontinuum und kein binäres Merkmal ist – ein Spiegel der biologischen Variabilität, die selbst eine Grundlage der Evolution ist. Homosexualität und andere sexuelle Orientierungen kommen auch bei anderen Tierarten vor und haben evolutionäre Erklärungsansätze (z. B. Kin-Selection-Hypothese, antagonistische Pleiotropie).","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["phänotypische Variation","sexuelle Selektion","Rekombination","Verwandtenselektion"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"phänotypische Variation","taxonomyElementId":"be7d702a-d8e5-413e-9bd0-e6d6ed36deff"},{"value":"sexuelle Selektion","taxonomyElementId":"cac35a85-b91c-43ba-b0d3-b6eec8cecfb2"},{"value":"Rekombination","taxonomyElementId":"3d26b663-7905-4913-8bce-892e6de31585"},{"value":"Verwandtenselektion","taxonomyElementId":"6d0f28c3-e728-4531-a825-7e40c0fc10e1"}]},{"begruendung":"Sexualität, Geschlechtsidentität und sexuelle Orientierung sind zentrale Aspekte der individuellen Entwicklung des Menschen, die über die rein körperliche Reifung hinausgehen. Während die Pubertät vor allem körperliche Veränderungen umfasst, macht dieses Lernziel deutlich, dass individuelle Entwicklung im Menschen auch psychische, soziale und identitätsbezogene Dimensionen einschließt, die sich in enger Wechselwirkung mit der biologischen Geschlechtsreifung, aber nicht auf diese reduzierbar, entfalten.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_individuelle_entwicklung__reifung"],"relevante_unterkonzepte":["Pubertät und Geschlechtsreife"],"relevante_unterkonzepte_taxonomie":[{"value":"Pubertät und Geschlechtsreife","taxonomyElementId":"6173fdb3-eb7b-4f23-a49d-586b760416f3"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen einzelner Organe sind für dieses Lernziel zu Identität und Verhalten nicht der Fokus.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse werden hier nicht behandelt; im Zentrum stehen Verhalten und Identität.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für Sexualität, Geschlechtsidentität und Orientierung nicht relevant.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für dieses Lernziel zu Verhalten und Identität nicht der zentrale Aspekt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q3","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_individuelle_entwicklung__zelldifferenzierung","basiskonzepte_primaer":["bk_individuelle_entwicklung"],"kognitive_anforderung":"analyse_und_bewertung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Faktenbasierte Diskussion: ''Homosexualität bei Tieren – Beispiele aus der Natur'' (Bonobos, Pinguine) – naturwissenschaftliche Entmystifizierung."},{"rang":2,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Begriffsklärung: Biologisches Geschlecht vs. Geschlechtsidentität vs. sexuelle Orientierung – klare Unterscheidung auf wissenschaftlicher Basis."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Reflexionsaufgabe: ''Was bedeutet biologische Vielfalt für unsere Gesellschaft?'' – Transfer evolutionärer Konzepte auf gesellschaftliche Fragen."}],"bezug_zum_lehrplan_kontext":"Integrationslernziel mit Bezug zu Wertebildung und Inklusion; wissenschaftliche Fundierung gesellschaftlich relevanter Themen","moegliche_fehlvorstellungen":"Schüler könnten Variation als ''Fehler'' oder ''Abnormität'' betrachten; der evolutionäre Normalitätsbegriff von Variation muss explizit vermittelt werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Wenn biologische Vielfalt das Rohmaterial der Evolution ist – gilt das auch für die Vielfalt des Geschlechts und der sexuellen Orientierung?'' Einführung in die Idee, dass Variation in allen biologischen Merkmalen evolutionär normal ist."},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"8","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-FES-2"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":2}'::jsonb WHERE id = '156a9576-18ae-5e82-b99b-ed228b4817a5'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-HUM-ZUS-3","thema":"Biologie des Menschen","anmerkung":"Finale Syntheseleistung Stoff/Energie","_source_id":"GY-78-HUM-ZUS-3","unterthema":"Zusammenwirken der Systeme","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"den Zusammenhang zwischen Ernährung und Zellatmung erläutern","bk_prinzipien":["Energetische Kopplung","Fließgleichgewicht","Stoffkreislauf"],"ist_praktisch":false,"kognitionsverb":"erläutern","kurzbezeichnung":"Ernährung und Zellatmung verknüpfen","abstraktionsgrad":"hoch","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Der Zusammenhang zwischen Ernährung und Zellatmung ist der fundamentale Stoffwechselzyklus, auf dem alles heterotrophe Leben basiert. Die Tatsache, dass Glukose als universelles Substrat der Zellatmung dient, ist ein Beleg für die Universalität des evolutionären Stoffwechselcodes: Alle Eukaryoten nutzen denselben Glykolyseweg, was auf einen gemeinsamen Vorfahren hindeutet. Der Zusammenhang zwischen Nahrungsqualität und Energieeffizienz der Zellatmung erklärt auch, warum evolutionäre Nährstoffpräferenzen (z. B. für energiereiche Fette und Zucker) entstanden sind.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)","gemeinsame Abstammung/Verwandtschaft","Endosymbiontentheorie","Evolutionäres Mismatch"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)","taxonomyElementId":"80535000-9149-4a60-b7d3-5d56d5deddf3"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"},{"value":"Endosymbiontentheorie","taxonomyElementId":"94eb6ae3-f936-4cab-9181-f45197233dfa"},{"value":"Evolutionäres Mismatch","taxonomyElementId":"11f4452a-41e4-48bf-a21e-63c4690ede25"}]},{"begruendung":"Der Zusammenhang von Ernährung und Zellatmung ist ein Stoffwechselprozess ohne Bezug zur individuellen Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Struktur-Funktions-Beziehungen der Mitochondrien wurden bereits andernorts behandelt; hier steht der Stoffwechselzusammenhang im Fokus.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse sind für den grundlegenden Zusammenhang von Ernährung und Zellatmung nicht der zentrale Aspekt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Nahrung liefert die Substrate, aus denen die Zellatmung Energie in Form von ATP freisetzt – der Kern dieses Lernziels: Erst durch die Kopplung von Nährstoffaufnahme und Zellatmung wird die in der Nahrung gespeicherte chemische Energie tatsächlich für Lebensprozesse nutzbar gemacht. Den Zusammenhang zwischen Ernährung und Zellatmung zu erläutern verbindet damit unmittelbar Stoffaufnahme und Energiegewinnung zu einem zusammenhängenden Prozess.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_stoff_energie_umwandlung__energie"],"relevante_unterkonzepte":["Energetische Kopplung"],"relevante_unterkonzepte_taxonomie":[{"value":"Energetische Kopplung","taxonomyElementId":"a4fea8b0-1264-43c8-ab4c-ce962327d26a"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für den Zusammenhang von Ernährung und Zellatmung nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q4","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_stoff_energie_umwandlung__energie","basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"kognitive_anforderung":"synthese","systemebene_sekundaer":"Organell","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Flussdiagramm: Nahrung → Verdauung → Resorption → Transport (Blut) → Zellatmung in den Mitochondrien → ATP; Schüler verfolgen den Weg eines Glukosemoleküls."},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Energiebilanz: Schüler berechnen, wieviel ATP aus einer Mahlzeit theoretisch gewonnen werden kann – Verbindung von Ernährung und zellulärer Energetik."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Evolutionärer Kontext: ''Warum ist Zucker und Fett so kalorienreich – und warum finden wir es so gut? Evolutionäre Erklärung der Nahrungspräferenzen.'' Einbettung in das Leben allgemein: ''Ob Alge, Pilz oder Mensch – alle nutzen denselben Grundweg.''"}],"bezug_zum_lehrplan_kontext":"Synthese von HUM-VD und HUM-ATM; Verbindung zu ZEL-PTZ-2 (Mitochondrien als Endosymbionten) und ZEL-PTZ-4 (Autotrophie/Heterotrophie)","moegliche_fehlvorstellungen":"Schüler könnten Zellatmung ausschließlich mit Lungen assoziieren; die klare Abgrenzung von Lungen- und Zellatmung und die Verbindung zur Ernährung muss explizit gemacht werden.","evolutionsdidaktischer_impuls":"Leitfrage: ''Ob Alge, Pilz oder Mensch – alle nutzen denselben Grundweg (Glykolyse), um Glukose abzubauen. Was sagt uns diese überraschende Gemeinsamkeit über die Evolution des Stoffwechsels?'' Einführung in die evolutionäre Universalität des Kohlenstoffstoffwechsels."},"basiskonzepte_sekundaer":["bk_steuerung_regelung"],"bk_prinzipien_taxonomie":[{"value":"Energetische Kopplung","taxonomyElementId":"9cd03f9a-998e-462d-a3c8-46fb60d0cc75"},{"value":"Fließgleichgewicht","taxonomyElementId":"23d0855d-a60f-4bfb-becb-8f1824c28c58"},{"value":"Stoffkreislauf","taxonomyElementId":"df08b5ac-d37e-4767-8844-2bb4757a8233"}],"empfohlene_klassenstufe":"8","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["GY-78-HUM-VD-2","GY-78-HUM-ATM-4","GY-78-HUM-ZUS-2"],"skalenuebergang_erforderlich":true,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '334f1021-aadc-5531-8e24-3877f6e3e40a'::uuid;
UPDATE lpm_data_objects SET content = '{"id":"GY-78-WIR-WTG-5","thema":"Wirbellose in ihren Lebensräumen","anmerkung":"Erstes Anwendungslernziel; Überprüfung des Strukturverständnisses","_source_id":"GY-78-WIR-WTG-5","unterthema":"Wirbellose als vielfältige Tiergruppe","_source_file":"lernziele_gy78.json","alltagsnaehe":"hoch","originaltext":"den Tiergruppen Vertreter begründet zuordnen","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"zuordnen_begründen","kurzbezeichnung":"Tiergruppen: Vertreter zuordnen","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die begründete Zuordnung von Vertretern zu Tiergruppen ist eine grundlegende taxonomische Kompetenz, die direkt auf das evolutionsbiologische Konzept der natürlichen Klassifikation verweist. In der modernen Biologie gilt: Klassifikationen sind nur dann biologisch sinnvoll, wenn sie phylogenetische Abstammungsgemeinschaften (monophyletische Gruppen) widerspiegeln. Wenn Schüler ein Tier anhand von Merkmalen einer Gruppe zuordnen, wenden sie implizit das Konzept der Synapomorphien an. Das Missklassifizieren kann genutzt werden, um zu diskutieren, warum äußerliche Ähnlichkeit kein verlässliches Verwandtschaftskriterium ist. Die Einordnung von Tieren in einen Stammbaum und die Interpretation von Verwandtschaftsverhältnissen anhand gemeinsamer Merkmale ist das Kerngeschäft phylogenetischen Denkens.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Stammbäume und phylogenetische Systematik","gemeinsame Abstammung/Verwandtschaft","Homologie und Analogie/Konvergente und divergente Evolution","Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Stammbäume und phylogenetische Systematik","taxonomyElementId":"c5750e12-26aa-4bab-846a-660b99c70dce"},{"value":"gemeinsame Abstammung/Verwandtschaft","taxonomyElementId":"96fda3fd-f73e-4444-9157-ff7b3feeb4f1"},{"value":"Homologie und Analogie/Konvergente und divergente Evolution","taxonomyElementId":"492006a1-28b5-4418-90ff-a167424785fc"},{"value":"Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)","taxonomyElementId":"80535000-9149-4a60-b7d3-5d56d5deddf3"}]},{"begruendung":"Die taxonomische Zuordnung betrifft die Artebene, nicht die individuelle Entwicklung eines Organismus.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die begründete Zuordnung von Vertretern zu den jeweiligen Tiergruppen stützt sich direkt auf die zuvor erarbeiteten Struktur-Merkmale dieser Gruppen: Erst das Wissen um charakteristische Baumerkmale wie Segmentierung, Skeletttyp oder Körpergliederung ermöglicht eine fachlich begründete statt bloß auswendig gelernte Zuordnung. Diese Anwendung festigt damit unmittelbar das zuvor erworbene strukturelle Wissen.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":["bk_struktur_funktion__struktur"],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Regelungsprozesse spielen bei der taxonomischen Einordnung keine Rolle.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung ist für die begründete Gruppenzuordnung nicht ausschlaggebend.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information/Kommunikation ist für dieses Klassifikationslernziel nicht relevant.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"empfohlenes_quartal":"Q1","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_struktur_funktion__struktur","basiskonzepte_primaer":["bk_struktur_funktion"],"kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Bestimmungsübung mit einfachen Bestimmungsschlüsseln: Schüler bestimmen Wirbellose und begründen ihre Zuordnung Schritt für Schritt."},{"rang":2,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Stammbaum-Erstellung und -Interpretation: Schüler ordnen Tiergruppen anhand von Merkmalstabellen in einen Stammbaum ein und begründen die Verwandtschaftsverhältnisse; Diskussion, welche Merkmale für die Einordnung geeignet sind und was der Stammbaum über gemeinsame Abstammung aussagt."},{"rang":3,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Fehlerzuordnungs-Aufgabe: Tiere sind falsch zugeordnet – Schüler finden den Fehler und korrigieren ihn mit Begründung."}],"bezug_zum_lehrplan_kontext":"Synthese der Lernziele GY-78-WIR-WTG-2 bis -4; Vorbereitung auf systematische Denkweisen in späteren Klassenstufen","moegliche_fehlvorstellungen":"Schüler neigen dazu, Tiere nach Äußerlichkeiten (Farbe, Größe) zu klassifizieren statt nach stammesgeschichtlich relevanten Merkmalen.","evolutionsdidaktischer_impuls":"Leitfrage: ''Was macht ein Merkmal zum richtigen Merkmal für die Klassifikation? Warum reicht es nicht, dass ein Tier schleimig ist, um es zu den Schnecken zu zählen? Und was verrät ein Stammbaum über die Verwandtschaft der Tiere?''"},"basiskonzepte_sekundaer":["bk_evolutive_entwicklung"],"empfohlene_klassenstufe":"7","interleaving_empfehlung":[],"ermoeglichende_lernziele":["GY-78-WIR-WTG-7"],"voraussetzende_lernziele":["GY-78-WIR-WTG-2","GY-78-WIR-WTG-3","GY-78-WIR-WTG-4"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '420fb546-2fa6-5162-a130-7a112fe1c6dc'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.10 Bionik - vom Entdecken zum Erfinden","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.10.1","unterthema":"10.1 Der Klettverschluss","originaltext":"Vorbild: Klettfrucht, die am Fell von Tieren haften bleibt, sich aber loesen lässt. Prinzip: biegsame Widerhaken, die bei Verhakung nicht abbrechen und sich immer wieder erneut verhaken koennen. Funktionsmodell: zwei Kunststoffstreifen, wovon einer flexible Widerhaekchen, der andere Schlaufen hat; geprueft auf Material, Zugbelastung, Haltbarkeit. Übertragen: Klettverschluss für Schuhe und Jacken, der leicht und beliebig haeufig zu oeffnen und zu schliessen ist. Fachpraktisch: Fruechte einer Klettfrucht (Widerhaken) sowie Haft- und Klettband eines Klettverschlusses (z. B. aus Polyamid) mit der Lupe betrachten.","unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","note_2015_baseline":"Kein direktes 2015-Gegenstueck -- 2015 kannte nur die allgemeine Bionik-Methode und ein offenes Projekt, kein benanntes Klettverschluss-Fallbeispiel."}'::jsonb, description = 'Schuelerinnen und Schueler koennen die Schrittfolge der Bionik am Beispiel des Klettverschlusses erläutern und das biologische Vorbild mit der technischen Umsetzung vergleichen.' WHERE id = 'ffd21b65-dd3d-4c5b-9bf0-1e4b9a6fdd08'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.10 Bionik - vom Entdecken zum Erfinden","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.10.3","unterthema":"10.3 Vom Nebeltrinkerkäfer zur Trinkwassergewinnung","originaltext":"Vorbild: Fluegeldecken des Nebeltrinkerkaefers mit kleinen Hoeckern kondensieren Wasserdampf; Rillen transportieren die Wassertroepfchen zum Mund des Kaefers. Prinzip: \"wasserliebende\" Stoffe mit vergrößerter Oberfläche ermoeglichen Kondensation; Rillen aus \"wasserabweisenden\" Stoffen ermoeglichen Transport. Funktionsmodell: Netze zur Kondensation von Wasserdampf plus Ablaufrinnen zum Auffangen des kondensierten Wassers; geprueft wird die gewonnene Wassermenge an verschiedenen Netzen. Übertragen: Nebelkollektoren (Netze und Auffangvorrichtungen) zur Gewinnung von Trinkwasser in Trockengebieten. Fachpraktisch: ein Modell einer Nebelfangeinrichtung gestalten, z. B. mit unterschiedlicher Maschengroesse des Netzes variieren, und auf Effizienz untersuchen.","unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","note_2015_baseline":"Kein direktes 2015-Gegenstueck -- gleiche Anmerkung wie Klettverschluss."}'::jsonb, description = 'Schuelerinnen und Schueler koennen die Wassergewinnung des Nebeltrinkerkaefers als biologisches Vorbild für technische Nebelkollektoren erläutern.' WHERE id = '9dbd79a7-02e0-4f13-92ed-87c6f56a367a'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.7 Samenpflanzen","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.7","unterthema":"Ordnen von Samenpflanzen","_source_file":"lernziele_MNT56.json","originaltext":"Die Einteilung von Samenpflanzen nach verschiedenen Ordnungskriterien erläutern (z. B. Wild- und Kulturpflanzen, Pflanzenfamilien)","ist_praktisch":false,"source_detail":"Added 2026-10-14 from Susan Hanisch''s direct feedback (row 5ca2cf66), checked against the real document. Basiskonzept/method analysis below is Claude-drafted and unreviewed -- Susan still needs to check it before it counts as validated, same as the rest of this project''s AI-drafted content.","kognitionsverb":"erläutern","abstraktionsgrad":"mittel","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Die Einteilung in Pflanzenfamilien ist keine beliebige Sortierung, sondern spiegelt tatsaechliche Verwandtschaft wider -- zwei Pflanzen landen in derselben Familie, weil sie von einer gemeinsamen Vorfahrin abstammen, nicht nur weil sie aehnlich aussehen. Für Fuenft-/Sechstklaessler steht die Kriterien geleitete Einteilung selbst im Vordergrund, nicht die stammesgeschichtliche Begruendung dahinter; der Bezug ist real, aber noch nicht Unterrichtsgegenstand.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Verwandtschaft und Abstammung"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Einteilung nach Ordnungskriterien betrifft, welcher Gruppe eine Pflanze angehoert, nicht ihre eigene Entwicklung vom Samen zur ausgewachsenen Pflanze.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Kriterien, nach denen Samenpflanzen eingeteilt werden -- etwa Bluetenbau oder Nutzung -- sind an aeusseren Strukturmerkmalen festgemacht. Das Lernziel selbst fragt aber nach der Einteilung an sich, nicht danach, wie Struktur und Funktion einer Pflanze zusammenhaengen.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Ordnungskriterien für Pflanzen betreffen keine Steuerungs- oder Regelungsprozesse.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Kriterium \"Wild- vs. Kulturpflanze\" beruehrt zwar Nutzung durch den Menschen, aber keine Stoff- oder Energieumwandlung selbst.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Klassifikation ist eine Form der Informationsordnung, aber kein Informations- oder Kommunikationsprozess zwischen Lebewesen, wie ihn dieses Basiskonzept meint.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","empfohlenes_quartal":"Q1","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_evolutive_entwicklung__verwandtschaft","basiskonzepte_primaer":["bk_evolutive_entwicklung","bk_struktur_funktion"],"kognitive_anforderung":"reproduktion_und_verstaendnis","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Die Klasse sortiert mitgebrachte oder abgebildete Pflanzen zunaechst nach einem selbst gewaehlten Kriterium, dann nach Wild-/Kulturpflanze, dann nach Pflanzenfamilie -- und vergleicht, welche Einteilung am meisten über die Pflanze verraet."},{"rang":2,"favorit":false,"methode":"Kooperative Lernformen","beschreibung":"Gruppen erhalten je ein Ordnungskriterium und praesentieren der Klasse, wie \"ihre\" Einteilung dieselben Pflanzen anders gruppiert."},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Diskussion: Warum braucht man mehrere Ordnungskriterien statt nur eines? Woran erkennt man, ob ein Kriterium gut geeignet ist?"}],"bezug_zum_lehrplan_kontext":"Fasst die vorangegangenen Einzelkriterien (Wuchsform, Nutzung, Pflanzenfamilie) zu einer allgemeinen Aussage über Ordnungskriterien zusammen -- Abschluss des Unterthemas \"Ordnen von Samenpflanzen\".","moegliche_fehlvorstellungen":"Schueler:innen nehmen oft an, es gaebe nur eine \"richtige\" Einteilung von Pflanzen; der Vergleich mehrerer Kriterien macht deutlich, dass die Wahl des Kriteriums vom Zweck der Einteilung abhaengt.","evolutionsdidaktischer_impuls":"Leitfrage: \"Warum landen zwei sehr unterschiedlich aussehende Pflanzen manchmal in derselben Pflanzenfamilie?\" -- bereitet vor, dass Verwandtschaft (nicht nur aeusserliche Aehnlichkeit) spaeter als Ordnungsprinzip eingefuehrt wird."},"basiskonzepte_sekundaer":["bk_individuelle_entwicklung"],"empfohlene_klassenstufe":"5","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["MNT-56-M2-ORD-1c"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = '6e6774a9-3ed6-4dcd-a55c-33cd6767bacc'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.2 Mensch – Natur – Technik","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.2","unterthema":"Naturwissenschaftliches Arbeiten","_source_file":"lernziele_MNT56.json","originaltext":"Die Schrittfolge des Forschenden Lernens an einem konkreten Beispiel anwenden (gleiche 6-Schritt-Folge wie in §2.2.1).","ist_praktisch":true,"source_detail":"Added 2026-10-14 from Susan Hanisch''s direct feedback (row 4bed4bbe): this subtopic existed in the real curriculum document but had no corresponding item in OpenLPM at all. Basiskonzept/method analysis below is Claude-drafted and unreviewed.","kognitionsverb":"anwenden","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das Anwenden einer Forschungsmethode an einem beliebigen Beispiel hat keinen inhaltlichen Bezug zu Evolution -- welches Beispiel gewaehlt wird, legt der Lehrplan bewusst offen.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Methodenanwendung an einem freien Beispiel beruehrt keine individuellen Entwicklungsprozesse.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein struktureller Bezug bei dieser allgemeinen Methodenuebung.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Bezug zu Steuerungs- oder Regelungsprozessen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Haengt ganz vom spaeter gewaehlten konkreten Beispiel ab, nicht vom Lernziel selbst.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Dokumentieren und Auswerten von Beobachtungen -- ein fester Teil der 6-Schritt-Folge -- ist eine Form naturwissenschaftlicher Informationsverarbeitung und -darstellung, auch wenn das Lernziel selbst die Methode in den Vordergrund stellt, nicht das Kommunizieren von Ergebnissen.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Dokumentation und Auswertung"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","empfohlenes_quartal":"Q1","systemebene_primaer":null,"teilkonzept_primaer":"bk_information_kommunikation__dokumentation","basiskonzepte_primaer":["bk_information_kommunikation"],"kognitive_anforderung":"anwendung","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Die Klasse durchlaeuft die 6 Schritte gemeinsam an einem einfachen Alltagsbeispiel (z. B. \"Warum beschlaegt ein kaltes Glas?\"), jeder Schritt wird einzeln benannt und an der Tafel festgehalten."},{"rang":2,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Schueler:innen fuehren den Schritt \"Experimente durchfuehren\" selbst praktisch aus, statt ihn nur beschrieben zu bekommen."},{"rang":3,"favorit":false,"methode":"Kooperative Lernformen","beschreibung":"In Kleingruppen wird je ein eigenes, einfaches Beispiel durch alle 6 Schritte gefuehrt und der Klasse vorgestellt."}],"bezug_zum_lehrplan_kontext":"Überführt die in Abschnitt 2.2.1 eingefuehrte 6-Schritt-Folge des Forschenden Lernens erstmals in die Anwendung an einem konkreten Beispiel -- Bruecke zwischen den allgemeinen Methoden aus 2.2.1 und ihrem spaeteren fachlichen Einsatz.","moegliche_fehlvorstellungen":"Schueler:innen überspringen oft den Schritt \"begründete Vermutung aufstellen\" und gehen direkt zum Experimentieren -- die explizite Benennung jedes Schritts hilft, das zu vermeiden.","evolutionsdidaktischer_impuls":null},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"5","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["MNT-56-M1-NWA-1a","MNT-56-M1-NWA-1b","MNT-56-M1-NWA-1c"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'a1c69f68-f997-4d00-bfc3-80e54920c509'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.2 Mensch – Natur – Technik","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.2","unterthema":"Fachpraktisches Arbeiten","_source_file":"lernziele_MNT56.json","originaltext":"Nach der Schrittfolge des Forschenden Lernens ein Stoffgemisch aus Eisenspänen, Sand und Kies trennen (mit Magnet und Sieb).","ist_praktisch":true,"source_detail":"Added 2026-10-14 from Susan Hanisch''s direct feedback (row 4bed4bbe), exact wording from her quote, matching the real document. Basiskonzept/method analysis below is Claude-drafted and unreviewed.","kognitionsverb":"trennen","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Das Trennen eines unbelebten Stoffgemischs hat keinen biologischen oder evolutionaeren Bezug.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Bezug zu individuellen Entwicklungsprozessen von Lebewesen.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Trennmethode nutzt gezielt unterschiedliche physikalische Eigenschaften der drei Stoffe (Eisenspaene magnetisch, Sand/Kies unterschiedliche Korngroesse) -- ein frueher, wenn auch nicht-biologischer Fall davon, wie eine Struktureigenschaft eine Funktion (hier: Trennbarkeit) ermoeglicht.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Steuerungs- oder Regelungsprozess beteiligt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Es handelt sich um eine physikalische Stofftrennung, nicht um eine Stoffumwandlung (die Stoffe selbst aendern sich nicht) -- trotzdem eine fruehe, konkrete Begegnung mit dem allgemeinen Thema \"Stoffe und ihre Eigenschaften\", das spaeter in Abschnitt 2.2.3 vertieft wird.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Stofftrennung"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Informations- oder Kommunikationsbezug im Sinn dieses Basiskonzepts.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","empfohlenes_quartal":"Q1","systemebene_primaer":null,"teilkonzept_primaer":"bk_stoff_energie_umwandlung__stofftrennung","basiskonzepte_primaer":["bk_struktur_funktion","bk_stoff_energie_umwandlung"],"kognitive_anforderung":"anwendung","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Jede:r Schueler:in trennt das Stoffgemisch selbst mit Magnet und Sieb und protokolliert die einzelnen Schritte."},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Vor dem Trennen eine begründete Vermutung aufstellen, welcher Stoff sich wie trennen lässt und warum -- anschliessend überprüfen."},{"rang":3,"favorit":false,"methode":"Kooperative Lernformen","beschreibung":"Partnerarbeit: eine Person fuehrt die Trennung durch, die andere dokumentiert und stellt Rueckfragen zur Begruendung."}],"bezug_zum_lehrplan_kontext":"Erstes konkretes, fachpraktisches Beispiel für die in Abschnitt 2.2.1 eingefuehrte Forschendes-Lernen-Methode und für das spaeter in Abschnitt 2.2.3 vertiefte Thema Stofftrennung.","moegliche_fehlvorstellungen":"Manche Kinder erwarten, dass ein Magnet auch Sand \"anziehen\" koennte, wenn man ihn nur stark genug macht -- ein guter Anlass, Magnetismus als stoffspezifische Eigenschaft (nur bei Eisen/Stahl) zu klaeren.","evolutionsdidaktischer_impuls":null},"basiskonzepte_sekundaer":[],"empfohlene_klassenstufe":"5","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":[],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'edc9754e-ee0c-4d75-848a-e48910ae6e2d'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.5 Kohäsion, Adhäsion, Kapillarität","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.5","unterthema":"Kohäsion, Adhäsion","originaltext":"Kugelform eines Wassertropfens aufgrund anziehender Kräfte zwischen den Wasserteilchen (Kohäsion) und Oberflächenspannung. Kräfte zwischen Wasserteilchen und Teilchen eines anderen Stoffes, z. B. Glas (Adhäsion). Benetzung, wenn Adhäsion größer als Kohäsion (z. B. auf wasserliebenden Oberflächen). Abperlen, wenn Adhäsion kleiner als Kohäsion (z. B. auf wasserabweisenden Oberflächen). Alltagsbeispiele für Adhäsion (z. B. Kreide an Tafel). Einsatz wasserabweisender bzw. fein genoppter Materialien begründen (z. B. Outdoorkleidung, Autowachs). Fachpraktisch: Verhalten eines Wassertropfens auf \"wasserliebender\" und \"wasserabweisender\" Oberfläche; Veränderung der Oberflächenspannung durch Spuelmittel; Benetzen und Abrollen von Wassertropfen auf geneigten Ebenen unterschiedlicher Materialien.","unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","note_2015_baseline":"Neu als benanntes Konzept mit eigener Fachsprache (Kohäsion, Adhäsion, Oberflächenspannung, Benetzen/Abperlen). Die zugehoerige Kapillaritaets-Experiment existierte 2015 bereits (Modul 2, \"Untersuchungen: Kapillaritaet\") und ist vermutlich bereits als eigenes Lernziel live -- das wird in Stage 2 zu diesem Lernbereich umgetaggt, nicht hier dupliziert."}'::jsonb, title = 'Kohäsion und Adhäsion', description = 'Schuelerinnen und Schueler koennen das Benetzen von Materialien mit Wasser und das Abperlen von Wassertropfen auf verschiedenen Materialien beschreiben und mit Kohäsions- und Adhäsionskraeften begründen.' WHERE id = '0130a025-7ebe-4a4f-a5d1-3e44b5ace875'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.8 Wirbeltiere","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.8","unterthema":"Angepasstheit an Lebensweise und Lebensräume (Fische)","_source_file":"lernziele_MNT56.json","originaltext":"Fische (Bachforelle): Fortbewegung im Wasser (Stromlinienform, Schuppen, Flossen, Schwimmblase); Atmung (Kiemen).","ist_praktisch":false,"source_detail":"Added 2026-10-18 while aligning the repository to Dustin/Susan''s reviewed topic/subtopic CSV: Fische was the one vertebrate class with no dedicated item at all. Basiskonzept/method analysis below is Claude-drafted and unreviewed.","kognitionsverb":"beschreiben","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"begruendung":"Stromlinienform, Schuppen und Schwimmblase sind klassische Anpassungen an das Leben im Wasser -- ein greifbares, für Fuenft-/Sechstklaessler zugaengliches Beispiel dafür, wie Koerperform zur Lebensweise passt, auch ohne die stammesgeschichtliche Herleitung explizit zu behandeln.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_evolutionskonzepte":["Anpassung und Angepasstheit"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Beschreibt eine bestehende Koerperform/Atmungsweise, keine individuelle Entwicklung über die Lebenszeit.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Ein zentrales Struktur-Funktion-Beispiel: Stromlinienform ermoeglicht schnelles Schwimmen, Schuppen schuetzen und verringern Reibung, Flossen steuern Richtung und Antrieb, die Schwimmblase reguliert den Auftrieb, Kiemen ermoeglichen Sauerstoffaufnahme aus dem Wasser -- jede Struktur hat eine klar benennbare Funktion für das Leben im Wasser.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Schwimmblase reguliert den Auftrieb und damit die Position des Fisches im Wasser -- ein einfaches, aber echtes Regelungsbeispiel, auch wenn es hier nicht als solches benannt wird.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Auftriebsregulation"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Atmung über Kiemen ist der zentrale Ort der Sauerstoffaufnahme aus dem Wasser, Grundlage für die Energiegewinnung im Koerper -- derselbe Zusammenhang, der bei Saeugetieren über die Lunge laeuft.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Gasaustausch"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Informations- oder Kommunikationsbezug im Sinn dieses Basiskonzepts.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"unterthema_origin":"curriculum_modified","curriculum_version":"2026-erprobungsfassung","empfohlenes_quartal":"Q2","systemebene_primaer":"Organismus","teilkonzept_primaer":"bk_struktur_funktion__angepasstheit","basiskonzepte_primaer":["bk_struktur_funktion"],"kognitive_anforderung":"reproduktion_und_verstaendnis","didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Ein echter Fisch (oder ein gutes Foto/Modell einer Bachforelle) wird Struktur für Struktur untersucht: Welche Form hat er? Wozu dienen Schuppen, Flossen, die Schwimmblase?"},{"rang":2,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Vergleich mit einem U-Boot oder einem stromlinienfoermig geformten Fahrzeug: Welche Form bewegt sich leicht durchs Wasser, welche nicht?"},{"rang":3,"favorit":false,"methode":"(bioethische) Diskussion","beschreibung":"Warum braucht ein Fisch Kiemen und kein Saeugetier? Verknuepfung zum bereits behandelten Saeugetier-Beispiel."}],"bezug_zum_lehrplan_kontext":"Eine von vier kurzen Fallstudien zu \"Weitere Wirbeltierklassen,\" parallel zu Lurchen, Kriechtieren und Voegeln -- rundet die Reihe der fuenf Wirbeltierklassen ab, nachdem Saeugetiere bereits ausfuehrlich behandelt wurden.","moegliche_fehlvorstellungen":"Manche Kinder glauben, Fische \"trinken\" Wasser, um zu atmen, statt dass sie dem Wasser geloesten Sauerstoff über die Kiemen entnehmen -- ein guter Anlass, den Unterschied zwischen Wasseraufnahme und Gasaustausch zu klaeren.","evolutionsdidaktischer_impuls":"Leitfrage: \"Was haben Stromlinienform, Schuppen und Flossen gemeinsam?\" -- bereitet vor, Struktur und Funktion als zusammenhaengendes Anpassungsprinzip zu erkennen, das bei jeder Wirbeltierklasse wiederkehrt."},"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung","bk_steuerung_regelung"],"empfohlene_klassenstufe":"5","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["MNT-56-M3-WIR-1","MNT-56-M3-WIR-3"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb WHERE id = 'c32f2315-ca9c-433b-9f02-c827d3e5c69d'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.9 Der Mensch – Gesunderhaltung","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.9","unterthema":"Sexualität und Fortpflanzung","originaltext":"Akzeptanz unterschiedlicher sexueller Orientierungen und Identitaeten.","unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","note_2015_baseline":"Kein 2015-Gegenstueck -- echte neue inhaltliche Ergaenzung, nicht nur eine Umformulierung des bestehenden Pubertaets-Lernziels (MNT-56-M4-SEX-1), neben dem dieses Item bewusst eigenstaendig eingefuegt wird statt das bestehende Lernziel live zu überschreiben."}'::jsonb WHERE id = 'c2b5ff73-faa0-43fa-9f00-234bb52fe29f'::uuid;
UPDATE lpm_data_objects SET content = '{"thema":"2.2.10 Bionik - vom Entdecken zum Erfinden","source":"LP Thueringen MNT Gym 2026 Erprobungsfassung, Abschnitt 2.2.10.2","unterthema":"10.2 Die Leichtbauweise","originaltext":"Vorbild: feste, aber leichte Strukturen, z. B. Bienenwaben, Knochen, Palmenblaetter. Prinzip: hohe Stabilitaet bei geringem Materialeinsatz, z. B. durch Faltung. Funktionsmodell: selbstversteifende Wirkung von Woelb- und Faltungsstrukturen; geprueft auf Zusammenhang zwischen Strukturen und Festigkeit (Druckbelastung). Übertragen: Bau von Bruecken und Daechern, Verpackungsmaterialien. Fachpraktisch: Forschendes Lernen am Beispiel eines Brueckenmodells -- Konstruktion einer leichten, stabilen Bruecke; Untersuchen von Vorbildern aus der Natur (Knochenquerschnitt, Palmenblattstruktur mit der Lupe); Planen von Faltkonstruktionen; Bauen, Variieren und Testen einfacher Brueckenmodelle auf Stabilitaet.","unterthema_origin":"curriculum","curriculum_version":"2026-erprobungsfassung","note_2015_baseline":"Kein direktes 2015-Gegenstueck -- gleiche Anmerkung wie Klettverschluss."}'::jsonb WHERE id = 'd9ed3d9a-4344-4813-bc0d-551641038def'::uuid;
